export interface CurrentPlayback {
  id: number;
  stationId?: number;
  showId?: number;
  title: string;
  artist?: string;
  artwork?: string;
  startTime: Date;
  isLive: boolean;
}

export interface PlaybackState {
  isPlaying: boolean;
  currentTime: number;
  duration: number;
  volume: number;
  isMuted: boolean;
  isLoading: boolean;
  error?: string;
}

export interface AudioPlayerControls {
