        headers: { 'Accept': 'application/json' } 
      });
      const data = await response.json();
      res.set('Cache-Control', 'no-store');
      res.set('Access-Control-Allow-Origin', '*');
      res.json(data);
    } catch (error) {
      console.error('Nowplaying proxy error:', error);
