## client/src/components/AudioPlayer.tsx
```typescript
import React, { useRef, useEffect, useState } from 'react';
import { Play, Pause, Volume2, VolumeX } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Card, CardContent } from '@/components/ui/card';
import { useWebSocket } from '@/hooks/useWebSocket';
import type { AudioTrack, PlaybackState, AudioPlayerControls } from '@/types/audio';

interface AudioPlayerProps {
  className?: string;
}

export function AudioPlayer({ className }: AudioPlayerProps) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [currentTrack, setCurrentTrack] = useState<AudioTrack | null>(null);
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0,
    duration: 0,
    volume: 1,
    isMuted: false,
    isLoading: false,
  });

  // WebSocket connection for real-time updates
  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  const wsUrl = `${protocol}//${window.location.host}/ws`;

  useWebSocket(wsUrl, {
    onMessage: (message) => {
      if (message.type === 'currentPlayback') {
        const playback = message.data;
        const track: AudioTrack = {
          id: playback.id.toString(),
          title: playback.title,
          artist: playback.artist || 'Unknown Artist',
          artwork: playback.artwork,
          isLive: playback.isLive,
        };
        setCurrentTrack(track);
      }
    }
  });

  // Initialize with default track
  useEffect(() => {
    const initialTrack: AudioTrack = {
      id: '1',
      title: 'DJ Amadeezy Mix',
      artist: 'DJ Amadeezy',
      artwork: 'https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=300&h=300&fit=crop',
      isLive: true,
    };
    setCurrentTrack(initialTrack);
  }, []);

  // Audio event handlers
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const handleTimeUpdate = () => {
      setPlaybackState(prev => ({
        ...prev,
        currentTime: audio.currentTime,
      }));
    };

    const handleDurationChange = () => {
      setPlaybackState(prev => ({
        ...prev,
        duration: audio.duration,
      }));
    };

    const handlePlay = () => {
      setPlaybackState(prev => ({
        ...prev,
        isPlaying: true,
        isLoading: false,
      }));
    };

    const handlePause = () => {
      setPlaybackState(prev => ({
        ...prev,
        isPlaying: false,
      }));
    };

    const handleLoadStart = () => {
      setPlaybackState(prev => ({
        ...prev,
        isLoading: true,
      }));
    };

    const handleLoadedData = () => {
      setPlaybackState(prev => ({
        ...prev,
        isLoading: false,
      }));
    };

    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('durationchange', handleDurationChange);
    audio.addEventListener('play', handlePlay);
    audio.addEventListener('pause', handlePause);
    audio.addEventListener('loadstart', handleLoadStart);
    audio.addEventListener('loadeddata', handleLoadedData);

    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('durationchange', handleDurationChange);
      audio.removeEventListener('play', handlePlay);
      audio.removeEventListener('pause', handlePause);
      audio.removeEventListener('loadstart', handleLoadStart);
      audio.removeEventListener('loadeddata', handleLoadedData);
    };
  }, []);

  const controls: AudioPlayerControls = {
    play: () => {
      const audio = audioRef.current;
      if (audio) {
        audio.src = 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3';
        audio.play();
      }
    },
    pause: () => {
      const audio = audioRef.current;
      if (audio) {
        audio.pause();
      }
    },
    stop: () => {
      const audio = audioRef.current;
      if (audio) {
        audio.pause();
        audio.currentTime = 0;
      }
    },
    seek: (time: number) => {
      const audio = audioRef.current;
      if (audio) {
        audio.currentTime = time;
      }
    },
    setVolume: (volume: number) => {
      const audio = audioRef.current;
      if (audio) {
        audio.volume = volume;
        setPlaybackState(prev => ({
          ...prev,
          volume,
          isMuted: volume === 0,
        }));
      }
    },
    mute: () => {
      const audio = audioRef.current;
      if (audio) {
        audio.muted = true;
        setPlaybackState(prev => ({
          ...prev,
          isMuted: true,
        }));
      }
    },
    unmute: () => {
      const audio = audioRef.current;
      if (audio) {
        audio.muted = false;
        setPlaybackState(prev => ({
          ...prev,
          isMuted: false,
        }));
      }
    },
  };

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const progressPercent = playbackState.duration > 0 
    ? (playbackState.currentTime / playbackState.duration) * 100 
    : 0;

  if (!currentTrack) {
    return (
      <Card className={className}>
        <CardContent className="p-6">
          <div className="text-center text-muted-foreground">
            No track selected
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={className}>
      <CardContent className="p-6">
        <audio ref={audioRef} crossOrigin="anonymous" preload="metadata" />

        <div className="space-y-4">
          {/* Track info */}
          <div className="text-center">
            {currentTrack.artwork && (
              <img 
                src={currentTrack.artwork} 
                alt={currentTrack.title}
                className="w-24 h-24 rounded-lg mx-auto mb-4 object-cover"
              />
            )}
            <h3 className="font-semibold">{currentTrack.title}</h3>
            <p className="text-sm text-muted-foreground">{currentTrack.artist}</p>
            {currentTrack.isLive && (
              <span className="inline-block mt-1 px-2 py-1 text-xs bg-red-500 text-white rounded">
                LIVE
              </span>
            )}
          </div>

          {/* Progress bar */}
          <div className="space-y-2">
            <div className="w-full bg-secondary rounded-full h-2">
              <div 
                className="bg-primary h-2 rounded-full transition-all duration-300"
                style={{ width: `${progressPercent}%` }}
              />
            </div>
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>{formatTime(playbackState.currentTime)}</span>
              <span>{formatTime(playbackState.duration)}</span>
            </div>
          </div>

          {/* Controls */}
          <div className="flex items-center justify-center space-x-4">
            <Button
              variant="outline"
              size="icon"
              onClick={playbackState.isPlaying ? controls.pause : controls.play}
              disabled={playbackState.isLoading}
            >
              {playbackState.isPlaying ? <Pause /> : <Play />}
            </Button>

            <div className="flex items-center space-x-2">
              <Button
                variant="ghost"
                size="icon"
                onClick={playbackState.isMuted ? controls.unmute : controls.mute}
              >
                {playbackState.isMuted ? <VolumeX /> : <Volume2 />}
              </Button>

              <Slider
                value={[playbackState.isMuted ? 0 : playbackState.volume]}
                onValueChange={(value) => controls.setVolume(value[0])}
                max={1}
                step={0.1}
                className="w-20"
              />
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}
