import { useState } from 'react';
import { Link } from 'wouter';
import { Play, Pause, Volume2, VolumeX, Music, Share2, Link2, Check } from 'lucide-react';
import { SiX, SiFacebook } from 'react-icons/si';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Badge } from '@/components/ui/badge';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { useToast } from '@/hooks/use-toast';
import type { Episode } from '@shared/schema';
import { useAudio } from '@/providers/AudioProvider';

interface EpisodePlayerProps {
  episode: Episode;
}

export function EpisodePlayer({ episode }: EpisodePlayerProps) {
  const { state, actions } = useAudio();
  const { toast } = useToast();
  const [volumeOpen, setVolumeOpen] = useState(false);
  const [shareOpen, setShareOpen] = useState(false);
  const [copied, setCopied] = useState(false);

  // Check if this specific episode is currently loaded/playing
  const isThisEpisodeLoaded = state.src === episode.audioUrl;
  const isPlaying = isThisEpisodeLoaded && state.status === 'playing';
  const currentTime = isThisEpisodeLoaded ? state.currentTime : 0;
  const volume = state.volume * 100;

  // Get the shareable URL for this episode
  const getShareUrl = () => {
    return `${window.location.origin}/episode/${episode.id}`;
  };

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(getShareUrl());
      setCopied(true);
      toast({
        title: "Link copied!",
        description: "Episode link copied to clipboard",
      });
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      toast({
        title: "Failed to copy",
        description: "Please copy the URL from your browser",
        variant: "destructive",
      });
    }
  };

  const handleShareTwitter = () => {
    const text = `Check out "${episode.title}" by ${episode.hostName} on Enamorado Radio`;
    const url = encodeURIComponent(getShareUrl());
    window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${url}`, '_blank');
    setShareOpen(false);
  };

  const handleShareFacebook = () => {
    const url = encodeURIComponent(getShareUrl());
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${url}`, '_blank');
    setShareOpen(false);
  };

  // Parse tracklist from JSON string
  const tracks: Array<{artist: string; title: string; timestamp?: number}> = 
    episode.tracklist ? JSON.parse(episode.tracklist) : [];

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handlePlayPause = async () => {
    console.log('🎵 Episode player: handlePlayPause, isPlaying:', isPlaying, 'isLoaded:', isThisEpisodeLoaded);

    if (isPlaying) {
      console.log('⏸ Pausing episode audio...');
      actions.pause();
    } else if (isThisEpisodeLoaded) {
      console.log('▶️ Resuming episode audio...');
      actions.toggle();
    } else {
      console.log('▶️ Starting episode audio...');
      try {
        await actions.play(episode.audioUrl, {
          title: episode.title,
          artist: episode.hostName,
          artwork: episode.artworkUrl || undefined,
          isLive: false,
        });
        console.log('✅ Episode playback started via shared AudioProvider');
      } catch (error) {
        console.error('❌ Episode play error:', error);
      }
    }
  };

  const handleSeek = (value: number[]) => {
    const newTime = (value[0] / 100) * episode.duration;
    actions.seek(newTime);
  };

  const handleVolumeChange = (value: number[]) => {
    const newVolume = value[0] / 100;
    actions.setVolume(newVolume);
  };

  const openSpotifyTrack = (spotifyId: string) => {
    window.open(`https://open.spotify.com/track/${spotifyId}`, '_blank');
  };

  const openSoundCloudTrack = (soundcloudUrl: string) => {
    window.open(soundcloudUrl, '_blank');
  };

  const openYouTubeTrack = (youtubeUrl: string) => {
    window.open(youtubeUrl, '_blank');
  };

  const openDiscogsTrack = (discogsUrl: string) => {
    window.open(discogsUrl, '_blank');
  };

  const progress = episode.duration > 0 ? (currentTime / episode.duration) * 100 : 0;

  return (
    <div className="bg-black text-white min-h-screen pb-20">
      {/* Header */}
      <div className="p-6 border-b border-gray-800">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <Link 
            href="/" 
            className="text-gray-400 hover:text-white transition-colors font-mono text-sm"
            data-testid="link-back-home"
            aria-label="Back to home page"
          >
            ← Back to Home
          </Link>
          <div className="flex items-center gap-3">
            <Popover open={shareOpen} onOpenChange={setShareOpen}>
              <PopoverTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-gray-400 hover:text-white transition-colors"
                  data-testid="button-share-episode"
                  aria-label="Share episode"
                >
                  <Share2 className="h-5 w-5" />
                </Button>
              </PopoverTrigger>
              <PopoverContent 
                align="end"
                className="w-48 p-2 bg-gray-900/95 backdrop-blur-sm border-gray-700"
              >
                <div className="flex flex-col gap-1">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleCopyLink}
                    className="justify-start text-white hover:bg-gray-800"
                    data-testid="button-copy-link"
                  >
                    {copied ? (
                      <Check className="h-4 w-4 mr-2 text-green-500" />
                    ) : (
                      <Link2 className="h-4 w-4 mr-2" />
                    )}
                    {copied ? 'Copied!' : 'Copy Link'}
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleShareTwitter}
                    className="justify-start text-white hover:bg-gray-800"
                    data-testid="button-share-twitter"
                  >
                    <SiX className="h-4 w-4 mr-2" />
                    Share on X
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleShareFacebook}
                    className="justify-start text-white hover:bg-gray-800"
                    data-testid="button-share-facebook"
                  >
                    <SiFacebook className="h-4 w-4 mr-2" />
                    Share on Facebook
                  </Button>
                </div>
              </PopoverContent>
            </Popover>
            <Badge className="bg-navy text-white font-mono">EPISODE</Badge>
          </div>
        </div>
      </div>

      {/* Episode Info with Prominent Play Button */}
      <div className="p-6 bg-gradient-to-b from-gray-900 to-black">
        <div className="max-w-4xl mx-auto">
          <div className="flex flex-col md:flex-row gap-6">
            {/* Artwork with Hover Play Button */}
            <div className="relative w-full md:w-64 h-64 bg-gray-800 rounded-xl overflow-hidden flex-shrink-0 group shadow-2xl">
              {episode.artworkUrl ? (
                <img 
                  src={episode.artworkUrl} 
                  alt={episode.title}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-gray-800 to-gray-900">
                  <Music className="w-24 h-24 text-gray-600" />
                </div>
              )}
              {/* Play/Pause Button Overlay - Only on Hover */}
              <button
                onClick={handlePlayPause}
                data-testid="button-play-episode"
                className="absolute inset-0 hidden group-hover:flex items-center justify-center bg-black/0 hover:bg-black/60 transition-all"
              >
                <div className="w-20 h-20 rounded-full bg-navy hover:bg-navy-dark flex items-center justify-center transition-all transform hover:scale-110 shadow-lg">
                  {isPlaying ? (
                    <Pause className="h-10 w-10 text-white" />
                  ) : (
                    <Play className="h-10 w-10 text-white ml-1" />
                  )}
                </div>
              </button>
            </div>

            {/* Episode Details */}
            <div className="flex-1 flex flex-col justify-center">
              <h1 className="text-3xl md:text-4xl font-bold mb-2 font-mono">{episode.title}</h1>
              <p className="text-gray-400 text-lg mb-2 font-mono">{episode.hostName}</p>
              <p className="text-gray-500 text-sm mb-4 font-mono">
                {episode.seriesTitle} • {formatTime(episode.duration)}
              </p>
              {episode.description && (
                <p className="text-gray-400 text-sm mb-4 leading-relaxed">
                  {episode.description}
                </p>
              )}
              <div className="flex flex-wrap gap-2">
                {episode.tags?.map((tag: string, index: number) => (
                  <Link key={index} href={`/episodes?tag=${encodeURIComponent(tag)}`}>
                    <Badge className="bg-gray-800 text-gray-300 hover:bg-navy hover:text-white transition-colors font-mono cursor-pointer">
                      {tag}
                    </Badge>
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Current Track Display - disabled for now */}

      {/* Tracklist */}
      <div className="p-6 pb-32">
        <div className="max-w-4xl mx-auto">
          <h3 className="text-2xl font-bold mb-6 font-mono">TRACKLIST</h3>
          {tracks.length === 0 ? (
            <div className="text-center py-12 bg-gray-900/50 rounded-xl border border-gray-800">
              <Music className="w-12 h-12 mx-auto mb-4 text-gray-600" />
              <p className="text-gray-500 font-mono">
                No tracklist available for this episode
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              {tracks.map((track, index) => (
                <div
                  key={index}
                  className="bg-gray-900/50 border border-gray-700 hover:border-sky-500 p-4 rounded-lg transition-all duration-150 hover:bg-gray-900 hover:-translate-y-0.5 hover:shadow-lg hover:shadow-sky-500/20 group cursor-default"
                >
                  <div className="flex items-start gap-3">
                    <div className="text-sky-400 font-mono font-bold text-sm pt-0.5 min-w-[2rem]">
                      #{String(index + 1).padStart(2, '0')}
                    </div>
                    <div className="flex-1">
                      <div className="text-base font-bold text-white font-mono group-hover:text-sky-400 transition-colors">
                        {track.artist}
                      </div>
                      <div className="text-sm text-gray-400 mt-1">
                        {track.title}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Audio Controls - Fixed Bottom */}
      <div 
        data-testid="episode-player-controls"
        className="fixed bottom-0 left-0 right-0 bg-black/95 backdrop-blur-lg border-t border-gray-800 p-4 z-[60]"
      >
        <div className="max-w-4xl mx-auto">
          {/* Progress Bar */}
          <div className="mb-3">
            <Slider
              value={[progress]}
              onValueChange={handleSeek}
              max={100}
              step={0.1}
              className="w-full cursor-pointer"
            />
          </div>

          {/* Controls Row */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              {/* Play/Pause */}
              <Button
                variant="ghost"
                size="sm"
                onClick={handlePlayPause}
                className="text-white hover:text-navy hover:bg-gray-900 transition-colors"
                data-testid="button-play-pause-controls"
              >
                {isPlaying ? <Pause className="h-6 w-6" /> : <Play className="h-6 w-6" />}
              </Button>

              {/* Time Display */}
              <div className="flex items-center gap-2 text-sm font-mono">
                <span className="text-white">{formatTime(currentTime)}</span>
                <span className="text-gray-600">/</span>
                <span className="text-gray-400">{formatTime(episode.duration)}</span>
              </div>

              {/* Persistent playback indicator */}
              {isThisEpisodeLoaded && (
                <span className="text-xs text-sky-400 font-mono hidden sm:inline">
                  Browse the site while listening
                </span>
              )}
            </div>

            {/* Volume Control - Vertical SoundCloud-style Popover */}
            <Popover open={volumeOpen} onOpenChange={setVolumeOpen}>
              <PopoverTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-white hover:text-sky-400 transition-colors"
                  data-testid="button-volume-episode"
                  aria-label={`Volume ${volume}%`}
                >
                  {volume === 0 ? (
                    <VolumeX className="h-5 w-5" />
                  ) : (
                    <Volume2 className="h-5 w-5" />
                  )}
                </Button>
              </PopoverTrigger>
              <PopoverContent 
                side="top" 
                align="center"
                className="w-12 p-2 bg-gray-900/95 backdrop-blur-sm border-gray-700"
              >
                <div className="flex flex-col items-center gap-2">
                  {/* Volume Percentage */}
                  <div className="text-xs font-mono text-white font-bold">
                    {volume}%
                  </div>

                  {/* Vertical Slider */}
                  <div className="h-[100px] flex items-center">
                    <Slider
                      value={[volume]}
                      onValueChange={handleVolumeChange}
                      max={100}
                      step={1}
                      orientation="vertical"
                      className="h-full"
                      aria-label="Volume control"
                      data-testid="slider-volume-vertical"
                      style={{
                        writingMode: 'bt-lr' as any,
                        WebkitAppearance: 'slider-vertical' as any,
                      }}
                    />
                  </div>
                </div>
              </PopoverContent>
            </Popover>
          </div>
        </div>
      </div>
    </div>
  );
}

server/simpleStreamingService.ts.content:
// Simple streaming service - uses uploaded MP3 files and HTML5 audio
import { storage } from './storage';

interface PlaylistItem {
  id: string;
  title: string;
  artist: string;
  duration: number; // seconds
  audioUrl: string; // path to MP3 file
  artworkUrl?: string;
  source: 'uploaded' | 'dj_mix' | 'submission';
  metadata?: any;
}

interface StreamState {
  currentTrack: PlaylistItem | null;
  isPlaying: boolean;
  currentTime: number;
  volume: number;
  playlist: PlaylistItem[];
  currentIndex: number;
  listeners: number;
}

class SimpleStreamingService {
  private state: StreamState = {
    currentTrack: null,
    isPlaying: false,
    currentTime: 0,
    volume: 0.7,
    playlist: [],
    currentIndex: 0,
    listeners: Math.floor(Math.random() * 30) + 5
  };

  private updateInterval: NodeJS.Timeout | null = null;
  private subscribers: Set<(state: StreamState) => void> = new Set();

  constructor() {
    this.initializePlaylist();
    this.startProgressTracking();
  }

  // Initialize with real uploaded files
  private async initializePlaylist() {
    // Add Jarrad's mix (we have this file)
    this.state.playlist.push({
      id: 'jarrad_how_did_i_do',
      title: 'how did i do',
      artist: 'Jarrad',
      duration: 1800, // 30 minutes estimated
      audioUrl: '/attached_assets/how did i do_1753594094475.mp3',
      artworkUrl: 'https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=300&h=300&fit=crop',
      source: 'dj_mix'
    });

    // Load approved song submissions
    const approvedSongs = await storage.getApprovedSongSubmissions();
    for (const song of approvedSongs) {
      if (song.platform === 'spotify' && song.platformUrl) {
        // For Spotify tracks, we'd need to either:
        // 1. Use Spotify Web Playback SDK (requires Premium)
        // 2. Link to external Spotify player
        // 3. Use preview URLs (30 seconds only)

        let metadata;
        try {
          metadata = song.metadata ? JSON.parse(song.metadata) : null;
        } catch (e) {
          metadata = null;
        }

        this.state.playlist.push({
          id: `spotify_${song.id}`,
          title: song.songTitle,
          artist: song.artistName,
          duration: metadata?.duration || 30, // Spotify previews are 30s
          audioUrl: metadata?.preview_url || song.platformUrl, // Fall back to Spotify link
          artworkUrl: metadata?.imageUrl,
          source: 'submission',
          metadata: metadata
        });
      }
    }

    // Start playing first track
    if (this.state.playlist.length > 0) {
      this.state.currentTrack = this.state.playlist[0];
      this.state.currentIndex = 0;
      this.notifySubscribers();
    }

    console.log(`[streaming] Initialized playlist with ${this.state.playlist.length} tracks`);
  }

  // Track progress for auto-advance
  private startProgressTracking() {
    this.updateInterval = setInterval(() => {
      if (this.state.isPlaying && this.state.currentTrack) {
        this.state.currentTime += 1;

        // Auto-advance when track finishes
        if (this.state.currentTime >= this.state.currentTrack.duration) {
          this.playNext();
        }

        // Update listener count occasionally
        if (Math.random() < 0.1) {
          this.state.listeners = Math.floor(Math.random() * 50) + 5;
        }

        this.notifySubscribers();
      }
    }, 1000);
  }

  // Admin controls
  play() {
    this.state.isPlaying = true;
    this.notifySubscribers();
    console.log(`[streaming] Playing: ${this.state.currentTrack?.title}`);
  }

  pause() {
    this.state.isPlaying = false;
    this.notifySubscribers();
    console.log(`[streaming] Paused: ${this.state.currentTrack?.title}`);
  }

  playNext() {
    if (this.state.playlist.length === 0) return;

    this.state.currentIndex = (this.state.currentIndex + 1) % this.state.playlist.length;
    this.state.currentTrack = this.state.playlist[this.state.currentIndex];
    this.state.currentTime = 0;
    this.state.isPlaying = true;

    console.log(`[streaming] Now playing: ${this.state.currentTrack.title} by ${this.state.currentTrack.artist}`);
    this.notifySubscribers();
  }

  playPrevious() {
    if (this.state.playlist.length === 0) return;

    this.state.currentIndex = this.state.currentIndex === 0 
      ? this.state.playlist.length - 1 
      : this.state.currentIndex - 1;
    this.state.currentTrack = this.state.playlist[this.state.currentIndex];
    this.state.currentTime = 0;
    this.state.isPlaying = true;

    this.notifySubscribers();
  }

  setVolume(volume: number) {
    this.state.volume = Math.max(0, Math.min(1, volume));
    this.notifySubscribers();
  }

  seek(time: number) {
    if (this.state.currentTrack) {
      this.state.currentTime = Math.max(0, Math.min(this.state.currentTrack.duration, time));
      this.notifySubscribers();
    }
  }

  // Add new track to playlist (when approved)
  async addTrack(submission: any) {
    let newTrack: PlaylistItem;

    if (submission.platform === 'spotify') {
      let metadata;
      try {
        metadata = submission.metadata ? JSON.parse(submission.metadata) : null;
      } catch (e) {
        metadata = null;
      }

      newTrack = {
        id: `spotify_${submission.id}`,
        title: submission.songTitle,
        artist: submission.artistName,
        duration: metadata?.duration || 30,
        audioUrl: metadata?.preview_url || submission.platformUrl,
        artworkUrl: metadata?.imageUrl,
        source: 'submission',
        metadata: metadata
      };
    } else {
      // For uploaded files or other platforms
      newTrack = {
        id: `submission_${submission.id}`,
        title: submission.songTitle,
        artist: submission.artistName,
        duration: 180, // Default 3 minutes
        audioUrl: submission.audioUrl || submission.platformUrl,
        source: 'submission'
      };
    }

    this.state.playlist.push(newTrack);
    console.log(`[streaming] Added "${newTrack.title}" to playlist`);
    this.notifySubscribers();
  }

  // Get current state for API
  getState(): StreamState {
    return { ...this.state };
  }

  // Subscribe to updates
  subscribe(callback: (state: StreamState) => void) {
    this.subscribers.add(callback);
    return () => this.subscribers.delete(callback);
  }

  private notifySubscribers() {
    this.subscribers.forEach(callback => callback(this.getState()));
  }

  // Admin: Update now playing manually
  setNowPlaying(title: string, artist: string, artworkUrl?: string) {
    this.state.currentTrack = {
      id: `manual_${Date.now()}`,
      title,
      artist,
      duration: 180, // Default duration
      audioUrl: '', // No actual audio for manual entries
      artworkUrl,
      source: 'uploaded'
    };
    this.state.currentTime = 0;
    this.notifySubscribers();
    console.log(`[streaming] Manually set now playing: ${title} by ${artist}`);
  }

  destroy() {
    if (this.updateInterval) {
      clearInterval(this.updateInterval);
    }
    this.subscribers.clear();
  }
}

// Singleton instance
export const simpleStreamingService = new SimpleStreamingService();

// Development logging
if (process.env.NODE_ENV === 'development') {
  console.log('[streaming] Simple streaming service initialized');

  simpleStreamingService.subscribe((state) => {
    if (state.currentTrack && state.isPlaying) {
      const progress = `${Math.floor(state.currentTime/60)}:${(state.currentTime%60).toString().padStart(2,'0')}`;
      const duration = `${Math.floor(state.currentTrack.duration/60)}:${(state.currentTrack.duration%60).toString().padStart(2,'0')}`;
      console.log(`[streaming] ${state.currentTrack.title} - ${progress}/${duration} (${state.listeners} listeners)`);
    }
  });
}

client/src/components/CustomRadioPlayer..content:
import { useState, useRef, useEffect } from 'react';
import { Play, Pause, Volume2, VolumeX, Radio, SkipForward } from 'lucide-react';

interface Track {
  title: string;
  artist: string;
  audioUrl?: string;
}

const sampleTracks: Track[] = [
  {
    title: "Jus Know (feat. Travis Scott)",
    artist: "PARTYNEXTDOOR",
    audioUrl: "https://commondatastorage.googleapis.com/codeskulptor-demos/DDR_assets/Kangaroo_MusiQue_-_The_Neverwritten_Role_Playing_Game.mp3"
  },
  {
    title: "Female Energy - Freestyle",
    artist: "WILOUGH",
    audioUrl: "https://commondatastorage.googleapis.com/codeskulptor-assets/week7-brrring.m4a"
  },
  {
    title: "Without U",
    artist: "spookyblakc",
    audioUrl: "https://www.soundjay.com/misc/sounds/bell-ringing-05.mp3"
  },
  {
    title: "Days In The East",
    artist: "Drake",
    audioUrl: "https://commondatastorage.googleapis.com/codeskulptor-demos/DDR_assets/Sevish_-__nbsp_.mp3"
  }
];

interface CustomRadioPlayerProps {
  onPlayingStateChange?: (isPlaying: boolean) => void;
}

export default function CustomRadioPlayer({ onPlayingStateChange }: CustomRadioPlayerProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [volume, setVolume] = useState(70);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(180); // 3 minutes placeholder
  const [listeners, setListeners] = useState(24);
  const audioRef = useRef<HTMLAudioElement>(null);

  const currentTrack = sampleTracks[currentTrackIndex];

  useEffect(() => {
    // Simulate listener count changes
    const interval = setInterval(() => {
      setListeners(prev => prev + Math.floor(Math.random() * 3) - 1);
    }, 10000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    // Load new track when track index changes
    if (audioRef.current && currentTrack.audioUrl) {
      audioRef.current.src = currentTrack.audioUrl;
      audioRef.current.load();
    }
  }, [currentTrackIndex]);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const updateTime = () => setCurrentTime(Math.floor(audio.currentTime));
    const updateDuration = () => setDuration(Math.floor(audio.duration));
    const handleEnded = () => {
      setCurrentTrackIndex((prevIndex) => (prevIndex + 1) % sampleTracks.length);
      setCurrentTime(0);
      // Keep playing state since we're auto-advancing to next track
    };

    audio.addEventListener('timeupdate', updateTime);
    audio.addEventListener('loadedmetadata', updateDuration);
    audio.addEventListener('ended', handleEnded);

    return () => {
      audio.removeEventListener('timeupdate', updateTime);
      audio.removeEventListener('loadedmetadata', updateDuration);
      audio.removeEventListener('ended', handleEnded);
    };
  }, []);

  const togglePlayPause = () => {
    const audio = audioRef.current;
    if (!audio) return;

    const newPlayingState = !isPlaying;

    if (isPlaying) {
      audio.pause();
      setIsPlaying(false);
    } else {
      audio.play().catch(error => {
        console.error('Error playing audio:', error);
        // Handle autoplay restrictions
      });
      setIsPlaying(true);
    }

    // Notify parent component about playing state change
    onPlayingStateChange?.(newPlayingState);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVolume = parseInt(e.target.value);
    setVolume(newVolume);
    if (audioRef.current) {
      audioRef.current.volume = newVolume / 100;
    }
  };

  const handleProgressClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const audio = audioRef.current;
    if (!audio || !duration) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickPercentage = clickX / rect.width;
    const newTime = clickPercentage * duration;

    audio.currentTime = newTime;
    setCurrentTime(Math.floor(newTime));
  };

  const nextTrack = () => {
    setCurrentTrackIndex((prevIndex) => (prevIndex + 1) % sampleTracks.length);
    setCurrentTime(0);
    // Keep current playing state when manually advancing tracks
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const progressPercentage = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <div className="bg-gray-900 rounded-lg p-6 text-white shadow-2xl border border-gray-700">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="bg-navy p-2 rounded-lg">
            <Radio className="w-5 h-5 text-white" />
          </div>
          <div>
            <h3 className="font-bold text-lg font-mono">Enamorado Radio</h3>
            <div className="flex items-center gap-2 text-sm text-gray-400">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
              <span>Live Stream</span>
            </div>
          </div>
        </div>

        <div className="text-right">
          <div className="text-sm text-gray-400">{listeners} listeners</div>
          <div className="text-xs text-gray-500">24/7</div>
        </div>
      </div>

      {/* Current Track Info */}
      <div className="mb-6">
        <h4 className="text-xl font-bold mb-1">{currentTrack.title}</h4>
        <p className="text-gray-400">{currentTrack.artist}</p>
      </div>

      {/* Progress Bar */}
      <div className="mb-6">
        <div className="relative">
          <div 
            className="w-full h-2 bg-gray-700 rounded-full cursor-pointer"
            onClick={handleProgressClick}
          >
            <div 
              className="h-full bg-navy rounded-full transition-all duration-300"
              style={{ width: `${progressPercentage}%` }}
            />
          </div>
        </div>
        <div className="flex justify-between text-xs text-gray-400 mt-2">
          <span>{formatTime(currentTime)}</span>
          <span>{formatTime(duration)}</span>
        </div>
      </div>

      {/* Controls */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={togglePlayPause}
            className="bg-navy hover:bg-navy-dark p-3 rounded-full transition-colors"
          >
            {isPlaying ? (
              <Pause className="w-6 h-6 text-white" />
            ) : (
              <Play className="w-6 h-6 text-white ml-1" />
            )}
          </button>

          <button
            onClick={nextTrack}
            className="bg-gray-700 hover:bg-gray-600 p-2 rounded-full transition-colors"
          >
            <SkipForward className="w-4 h-4 text-white" />
          </button>

          <div className="flex items-center gap-2">
            <VolumeX className="w-4 h-4 text-gray-400" />
