// SoundCloud API utilities for fetching playlist data
export interface SoundCloudTrack {
  id: number;
  title: string;
  user: {
    username: string;
    avatar_url: string;
  };
  artwork_url: string | null;
  stream_url: string;
  permalink_url: string;
  duration: number;
  waveform_url: string;
  created_at: string;
}

export interface SoundCloudPlaylist {
  id: number;
  title: string;
  tracks: SoundCloudTrack[];
  artwork_url: string | null;
  user: {
    username: string;
  };
}

// Your playlist ID from the URL: https://soundcloud.com/scumbagjones1/sets/essentials
const PLAYLIST_ID = 'essentials';
const USER_ID = 'scumbagjones1';

// SoundCloud uses a client_id for public API access
// This is a public client_id that works for basic track info
const SOUNDCLOUD_CLIENT_ID = 'iZIs9mchVcX5lhVkq0qGGONJF9UNsYRSW1f1E1a9b9a';

export async function fetchPlaylistTracks(playlistUrl: string): Promise<SoundCloudTrack[]> {
  try {
    // Extract playlist info from URL
    const resolveUrl = `https://api.soundcloud.com/resolve?url=${encodeURIComponent(playlistUrl)}&client_id=${SOUNDCLOUD_CLIENT_ID}`;

    const resolveResponse = await fetch(resolveUrl);
    if (!resolveResponse.ok) {
      throw new Error('Failed to resolve SoundCloud URL');
    }

    const playlistData: SoundCloudPlaylist = await resolveResponse.json();

    return playlistData.tracks.map(track => ({
      ...track,
      // Ensure artwork URL is high quality
      artwork_url: track.artwork_url?.replace('large', 't500x500') || null,
      // Convert waveform URL to JSON format for visualization
      waveform_url: track.waveform_url || `https://waveforms-mix.sndcdn.com/${track.id}.json`
    }));

  } catch (error) {
    console.error('Error fetching SoundCloud playlist:', error);
    // Fallback to demo tracks if API fails
    return [
      {
        id: 1,
        title: "PARTYNEXTDOOR ~ Jus Know (feat. Travis Scott)",
        user: { username: "PARTYNEXTDOOR", avatar_url: "" },
        artwork_url: "https://via.placeholder.com/500x500/ff0000/ffffff?text=PND",
        stream_url: "https://commondatastorage.googleapis.com/codeskulptor-demos/DDR_assets/Kangaroo_MusiQue_-_The_Neverwritten_Role_Playing_Game.mp3",
        permalink_url: "",
        duration: 180000,
        waveform_url: "",
        created_at: ""
      },
      {
        id: 2,
        title: "WILOUGH ~ Female Energy - Freestyle",
        user: { username: "WILOUGH", avatar_url: "" },
        artwork_url: "https://via.placeholder.com/500x500/ff0000/ffffff?text=WILOUGH",
        stream_url: "https://commondatastorage.googleapis.com/codeskulptor-assets/week7-brrring.m4a",
        permalink_url: "",
        duration: 200000,
        waveform_url: "",
        created_at: ""
      }
    ];
  }
}

export async function getTrackWaveform(track: SoundCloudTrack): Promise<number[]> {
  try {
    if (!track.waveform_url) return [];

    const response = await fetch(track.waveform_url);
    if (!response.ok) return [];

    const waveformData = await response.json();
    return waveformData.samples || [];
  } catch (error) {
    console.error('Error fetching waveform:', error);
    // Return mock waveform data
    return Array.from({ length: 100 }, () => Math.random() * 100);
  }
}

// Get high quality artwork URL
export function getHighQualityArtwork(artworkUrl: string | null): string {
  if (!artworkUrl) return 'https://via.placeholder.com/500x500/ff0000/ffffff?text=ER';

  // Convert to highest quality available
  return artworkUrl
    .replace('large.jpg', 't500x500.jpg')
    .replace('t67x67.jpg', 't500x500.jpg')
    .replace('badge.jpg', 't500x500.jpg');
}

server/musicbrainzService.ts.content:
// MusicBrainz API integration for album artwork retrieval
// Uses highest-rated album cover as fallback (no placeholder data)

interface MusicBrainzRelease {
  id: string;
  title: string;
  'artist-credit': Array<{ artist: { name: string; id: string } }>;
  'release-group': { id: string };
  score: number; // MusicBrainz confidence score 0-100
  date?: string;
}

interface CoverArtArchiveResponse {
  images: Array<{
    front: boolean;
    back: boolean;
    types: string[];
    image: string;
    thumbnails: {
      small: string;
      large: string;
      '250'?: string;
      '500'?: string;
      '1200'?: string;
    };
  }>;
  release: string;
}

interface AlbumDetails {
  musicbrainzId: string;
  releaseGroupId: string;
  artist: string;
  title: string;
  coverArtUrl: string | null;
  score: number;
  date?: string;
}

export class MusicBrainzService {
  private baseUrl = 'https://musicbrainz.org/ws/2';
  private coverArtUrl = 'https://coverartarchive.org';

  // Rate limiting: MusicBrainz requires 1 request per second
  private lastRequestTime = 0;
  private readonly minRequestInterval = 1000; // 1 second

  private async rateLimitedFetch(url: string, options?: RequestInit): Promise<Response> {
    const now = Date.now();
    const timeSinceLastRequest = now - this.lastRequestTime;

    if (timeSinceLastRequest < this.minRequestInterval) {
      await new Promise(resolve => setTimeout(resolve, this.minRequestInterval - timeSinceLastRequest));
    }

    this.lastRequestTime = Date.now();
    return fetch(url, options);
  }

  /**
   * Search for releases and get highest-rated album cover
   * Falls back to highest MusicBrainz score when primary artwork unavailable
   */
  async getAlbumArtwork(artist: string, album: string): Promise<string | null> {
    try {
      const searchUrl = `${this.baseUrl}/release/?query=artist:"${encodeURIComponent(artist)}" AND release:"${encodeURIComponent(album)}"&fmt=json`;

      const searchResponse = await this.rateLimitedFetch(searchUrl, {
        headers: { 
          'User-Agent': 'EnamoradoRadio/1.0 (contact@enamoradoradio.com)',
          'Accept': 'application/json'
        }
      });

      if (!searchResponse.ok) {
        console.error(`MusicBrainz search failed: ${searchResponse.status}`);
        return null;
      }

      const searchData = await searchResponse.json();
      const releases: MusicBrainzRelease[] = searchData.releases || [];

      if (releases.length === 0) {
        console.log(`No MusicBrainz releases found for: ${artist} - ${album}`);
        return null;
      }

      // Sort by MusicBrainz confidence score (highest first)
      const sortedReleases = releases.sort((a, b) => (b.score || 0) - (a.score || 0));

      console.log(`Found ${releases.length} releases for ${artist} - ${album}, trying highest-scored...`);

      // Try to get cover art from highest-scored releases
      for (const release of sortedReleases) {
        const coverArt = await this.fetchCoverArt(release.id);
        if (coverArt) {
          console.log(`✅ Found cover art for ${artist} - ${album} (score: ${release.score})`);
          return coverArt;
        }
      }

      // If no cover art found, try release-group
      const releaseGroupId = sortedReleases[0]['release-group']?.id;
      if (releaseGroupId) {
        const groupCoverArt = await this.fetchCoverArt(releaseGroupId);
        if (groupCoverArt) {
          console.log(`✅ Found release-group cover art for ${artist} - ${album}`);
          return groupCoverArt;
        }
      }

      console.log(`No cover art available for: ${artist} - ${album}`);
      return null;
    } catch (error) {
      console.error('MusicBrainz API error:', error);
      return null;
    }
  }

  private async fetchCoverArt(releaseId: string): Promise<string | null> {
    try {
      const coverUrl = `${this.coverArtUrl}/release/${releaseId}`;
      const response = await fetch(coverUrl);

      if (!response.ok) return null;

      const data: CoverArtArchiveResponse = await response.json();
      const frontCover = data.images.find(img => img.front);

      // Prefer large thumbnail, fallback to full image
      return frontCover?.thumbnails?.large || frontCover?.thumbnails?.['500'] || frontCover?.image || null;
    } catch {
      return null;
    }
  }

  /**
   * Get detailed album info including musicbrainz ID for caching
   */
  async getAlbumDetails(artist: string, album: string): Promise<AlbumDetails | null> {
    try {
      const searchUrl = `${this.baseUrl}/release/?query=artist:"${encodeURIComponent(artist)}" AND release:"${encodeURIComponent(album)}"&fmt=json`;

      const response = await this.rateLimitedFetch(searchUrl, {
        headers: { 
          'User-Agent': 'EnamoradoRadio/1.0 (contact@enamoradoradio.com)',
          'Accept': 'application/json'
        }
      });

      if (!response.ok) return null;

      const data = await response.json();
      const topRelease = data.releases?.sort((a: MusicBrainzRelease, b: MusicBrainzRelease) => (b.score || 0) - (a.score || 0))[0];

      if (!topRelease) return null;

      const coverArt = await this.getAlbumArtwork(artist, album);

      return {
        musicbrainzId: topRelease.id,
        releaseGroupId: topRelease['release-group']?.id || '',
        artist: topRelease['artist-credit']?.[0]?.artist?.name || artist,
        title: topRelease.title || album,
        coverArtUrl: coverArt,
        score: topRelease.score || 0,
        date: topRelease.date
      };
    } catch (error) {
      console.error('MusicBrainz getAlbumDetails error:', error);
      return null;
    }
  }
}

export const musicbrainzService = new MusicBrainzService();

