import { useState, useRef, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Link } from 'wouter';
import { Play, ExternalLink, ChevronLeft, ChevronRight, Disc } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { enrichMultipleAlbums, type AlbumInfo } from '@/../../shared/musicApi';

interface Album {
  id: number;
  title: string;
  artist: string;
  coverUrl: string;
  description: string;
  genre: string[];
  releaseYear: number;
  spotifyUrl?: string;
  appleMusicUrl?: string;
  bandcampUrl?: string;
  featured: boolean;
  month: string;
  year: number;
}

export default function AlbumsOfTheMonth() {
  const [selectedAlbum, setSelectedAlbum] = useState<Album | null>(null);
  const [isVinylVisible, setIsVinylVisible] = useState<number | null>(null);
  const [enrichedAlbums, setEnrichedAlbums] = useState<Album[]>([]);
  const [enrichmentFailed, setEnrichmentFailed] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Fetch albums from API
  const { data: albumsData, isLoading: isLoadingAlbums, error: albumsError } = useQuery({
    queryKey: ['/api/albums'],
    queryFn: async () => {
      const response = await fetch('/api/albums?page=1&limit=12');
      if (!response.ok) {
        throw new Error('Failed to fetch albums');
      }
      return response.json();
    }
  });

  const albums = albumsData?.albums || [];

  // Enrich albums with real artwork when albums are loaded
  useEffect(() => {
    if (albums.length === 0) return;

    const loadAlbumArtwork = async () => {
      console.log('[Albums] Starting artwork enrichment...');
      setEnrichmentFailed(false);

      const albumsToEnrich = albums.map((album: any) => ({
        id: album.id,
        title: album.title,
        artist: album.artist,
        coverUrl: album.coverUrl,
        spotifyUrl: album.spotifyUrl,
        releaseYear: album.releaseYear
      }));

      try {
        const enriched = await enrichMultipleAlbums(albumsToEnrich);
        console.log('[Albums] Enrichment complete:', enriched);

        // Merge back with original album data using title + artist matching for better reliability
        const updatedAlbums = albums.map((album: any) => {
          const enrichedData = enriched.find(e => 
            e.title.toLowerCase() === album.title.toLowerCase() && 
            e.artist.toLowerCase() === album.artist.toLowerCase()
          );
          return {
            ...album,
            id: parseInt(album.id), // Ensure ID is number for consistency
            coverUrl: enrichedData?.coverUrl || '/default-cover.jpg', // No AI fallback
            spotifyUrl: enrichedData?.spotifyUrl || album.spotifyUrl || 
              `https://open.spotify.com/search/${encodeURIComponent(album.artist + " " + album.title)}`
          };
        });

        setEnrichedAlbums(updatedAlbums);
      } catch (error) {
        console.error('[Albums] Enrichment failed:', error);
        setEnrichmentFailed(true);
        // Fallback to original album data with default covers
        const fallbackAlbums = albums.map((album: any) => ({
          ...album,
          id: parseInt(album.id),
          coverUrl: '/default-cover.jpg', // No AI fallback
          spotifyUrl: album.spotifyUrl || 
            `https://open.spotify.com/search/${encodeURIComponent(album.artist + " " + album.title)}`
        }));
        setEnrichedAlbums(fallbackAlbums);
      }
    };

    loadAlbumArtwork();
  }, [albums]);

  const handleAlbumHover = (albumId: number | null) => {
    setIsVinylVisible(albumId);
  };

  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const scrollAmount = 320;
      scrollRef.current.scrollBy({
        left: direction === 'left' ? -scrollAmount : scrollAmount,
        behavior: 'smooth'
      });
    }
  };

  return (
    <div className="bg-white text-black min-h-screen">
      <div className="max-w-6xl mx-auto px-6 py-8">
        {/* Back to Home */}
        <div className="mb-6">
          <Link 
            href="/"
            className="inline-flex items-center text-gray-600 hover:text-navy transition-colors font-mono"
          >
            ← Back to Home
          </Link>
        </div>

        {/* NTS-Style Header */}
        <div className="mb-8 border-b-2 border-black pb-6">
          <h1 className="text-4xl font-bold uppercase tracking-wide mb-4 font-mono">
            ALBUMS OF THE MONTH
          </h1>
          <div className="flex flex-col md:flex-row md:items-end md:justify-between gap-4">
            <p className="text-lg max-w-2xl">
              Four standout albums selected by our editorial team.
            </p>
            <div className="text-sm font-mono">
              JANUARY 2025 SELECTION
            </div>
          </div>
        </div>

        {/* Current Month Feature */}
        <div className="mb-12">
          <h2 className="text-2xl font-bold uppercase tracking-wide mb-8">
            CURRENT SELECTION
          </h2>

          {/* Cover Flow Style Gallery */}
          <div className="relative">
            {/* Navigation Buttons */}
            <Button
              variant="ghost"
              size="sm"
              className="absolute left-0 top-1/2 -translate-y-1/2 z-10 bg-black/50 hover:bg-black/70"
              onClick={() => scroll('left')}
            >
              <ChevronLeft className="h-6 w-6" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="absolute right-0 top-1/2 -translate-y-1/2 z-10 bg-black/50 hover:bg-black/70"
              onClick={() => scroll('right')}
            >
              <ChevronRight className="h-6 w-6" />
            </Button>

            {/* Clean Album Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-0 border-2 border-black">
              {isLoadingAlbums ? (
                // Loading state
                Array.from({ length: 4 }).map((_, index) => (
                  <div key={index} className="border-r-2 border-b-2 border-black p-6 bg-gray-50">
                    <div className="aspect-square mb-4 bg-gray-200 flex items-center justify-center">
                      <Disc className="w-16 h-16 text-gray-400 animate-spin" />
                    </div>
                    <div className="space-y-2">
                      <div className="h-4 bg-gray-200 rounded"></div>
                      <div className="h-3 bg-gray-200 rounded w-3/4"></div>
                    </div>
                  </div>
                ))
              ) : (
                (enrichedAlbums.length > 0 ? enrichedAlbums : albums).map((album: any, index: number) => (
                <div
                  key={album.id}
                  className="border-r-2 border-b-2 border-black p-6 hover:bg-gray-50 transition-colors group cursor-pointer"
                  onMouseEnter={() => handleAlbumHover(album.id)}
                  onMouseLeave={() => handleAlbumHover(null)}
                  onClick={() => setSelectedAlbum(album)}
                >
                  {/* Album Cover */}
                  <div className="aspect-square mb-4 relative overflow-hidden bg-white">
                    {album.coverUrl && album.coverUrl !== '/default-cover.jpg' ? (
                      <img 
                        src={album.coverUrl} 
                        alt={`${album.title} by ${album.artist}`}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          // Replace with disc icon fallback when image fails
                          const parent = e.currentTarget.parentElement;
                          if (parent) {
                            parent.innerHTML = `
                              <div class="w-full h-full bg-gray-200 flex items-center justify-center">
                                <div class="text-center text-gray-400">
                                  <svg class="w-16 h-16 mx-auto mb-2" fill="currentColor" viewBox="0 0 24 24">
                                    <circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="2" fill="none"/>
                                    <circle cx="12" cy="12" r="3" fill="currentColor"/>
                                  </svg>
                                  <p class="text-xs font-mono">No Cover Art</p>
                                </div>
                              </div>
                            `;
                          }
                        }}
                      />
                    ) : (
                      <div className="w-full h-full bg-gray-200 flex items-center justify-center">
                        <div className="text-center text-gray-400">
                          <Disc className="w-16 h-16 mx-auto mb-2" />
                          <p className="text-xs font-mono">No Cover Art</p>
                        </div>
                      </div>
                    )}

                    {/* Play Button Overlay */}
                    <div className="absolute inset-0 bg-black bg-opacity-50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <Button size="sm" className="bg-white text-black hover:bg-gray-200">
                        <Play className="h-4 w-4 mr-1" />
                        PLAY
                      </Button>
                    </div>
                  </div>

                  {/* Album Info */}
                  <div className="space-y-2">
                    <h3 className="font-bold text-lg uppercase tracking-wide leading-tight">
                      {album.title}
                    </h3>

                    <p className="text-base font-medium">
                      {album.artist}
                    </p>

                    <div className="flex flex-wrap gap-1 pt-2">
                      {album.genre.map((g: string, genreIndex: number) => (
                        <span key={genreIndex} className="text-xs font-mono bg-black text-white px-2 py-1">
                          {g}
                        </span>
                      ))}
                      <span className="text-xs font-mono bg-black text-white px-2 py-1">
                        {album.releaseYear ?? "Unknown Year"}
                      </span>
                    </div>

                    {/* Spotify Link */}
                    {album.spotifyUrl && (
                      <div className="pt-2">
                        <a 
                          href={album.spotifyUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-xs font-mono text-gray-600 hover:text-black flex items-center gap-1"
                        >
                          <ExternalLink className="h-3 w-3" />
                          SPOTIFY
                        </a>
                      </div>
                    )}
                  </div>
                </div>
                ))
              )}
            </div>

            {/* Error UI */}
            {enrichmentFailed && (
              <div className="text-navy font-mono text-sm mt-4 p-4 border-2 border-red-200 bg-red-50">
                ⚠️ Some album artwork couldn't be loaded from MusicBrainz.
              </div>
            )}

            {albumsError && (
              <div className="text-navy font-mono text-sm mt-4 p-4 border-2 border-red-200 bg-red-50">
                ⚠️ Failed to load albums. Please try again later.
              </div>
            )}
          </div>
        </div>

        {/* Selected Album Detail - Clean Style */}
        {selectedAlbum && (
          <div className="bg-red-50 border-2 border-navy p-8 mb-8">
            <div className="flex flex-col md:flex-row gap-6">
              <div className="md:w-1/3">
                <img 
                  src={selectedAlbum.coverUrl} 
                  alt={`${selectedAlbum.title} by ${selectedAlbum.artist}`}
                  className="w-full max-w-xs mx-auto border-2 border-gray-200"
                />
              </div>
              <div className="md:w-2/3">
                <h3 className="text-3xl font-bold mb-2 font-mono text-navy">{selectedAlbum.title}</h3>
                <p className="text-xl text-gray-600 mb-4 font-mono">{selectedAlbum.artist}</p>
                <p className="text-gray-600 mb-4 text-lg leading-relaxed font-mono">{selectedAlbum.description}</p>

                <div className="flex gap-2 mb-6">
                  {selectedAlbum.genre.map((genre, index) => (
                    <span key={index} className="bg-navy text-white px-3 py-1 text-sm font-mono">
                      {genre}
                    </span>
                  ))}
                  <span className="bg-gray-600 text-white px-3 py-1 text-sm font-mono">
                    {selectedAlbum.releaseYear}
                  </span>
                </div>

                {/* Streaming Links */}
                <div className="flex flex-wrap gap-3">
                  {selectedAlbum.spotifyUrl && (
                    <a 
                      href={selectedAlbum.spotifyUrl} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="bg-navy hover:bg-navy-dark text-white px-6 py-2 font-mono transition-colors flex items-center"
                    >
                      <ExternalLink className="h-4 w-4 mr-2" />
                      Spotify
                    </a>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Archive Section */}
        <div className="border-t-2 border-gray-300 pt-8">
          <h2 className="text-2xl font-semibold mb-4 font-mono text-navy">Previous Months</h2>
          <p className="text-gray-600 mb-6 font-mono">
            albums for your listening pleasure. Explore our curated picks below or dive into our archive to discover past selections.
          </p>
          <a 
            href="/editorial-picks"
            className="inline-flex items-center bg-navy hover:bg-navy-dark text-white px-6 py-3 font-mono transition-colors"
          >
            <ExternalLink className="h-4 w-4 mr-2" />
            View Editorial Picks Archive
          </a>
        </div>
      </div>
    </div>
  );
}

shared/platformDetection.ts.content:
// Platform detection utility for music URLs
// Supports reference-only approach for Spotify/Apple Music

export type MusicPlatform = 'spotify' | 'apple' | 'soundcloud' | 'mixcloud' | 'youtube' | 'audio' | 'upload' | 'unknown';

export type PlaybackMode = 'embed' | 'file' | 'stream';

export interface PlatformInfo {
  platform: MusicPlatform;
  playbackMode: PlaybackMode;
  isRadioIngestable: boolean;
  requiresAlternative: boolean;
  embedSupported: boolean;
}

/**
 * Detect music platform from URL
 */
export function detectMusicPlatform(url: string): PlatformInfo {
  if (!url || typeof url !== 'string') {
    return {
      platform: 'unknown',
      playbackMode: 'file',
      isRadioIngestable: false,
      requiresAlternative: true,
      embedSupported: false
    };
  }

  const urlLower = url.toLowerCase();

  // Spotify detection
  if (urlLower.includes('spotify.com') || urlLower.includes('open.spotify.com')) {
    return {
      platform: 'spotify',
      playbackMode: 'embed',
      isRadioIngestable: false,
      requiresAlternative: true,
      embedSupported: true
    };
  }

  // Apple Music detection
  if (urlLower.includes('music.apple.com') || urlLower.includes('itunes.apple.com')) {
    return {
      platform: 'apple',
      playbackMode: 'embed',
      isRadioIngestable: false,
      requiresAlternative: true,
      embedSupported: true
    };
  }

  // SoundCloud detection (radio ingestable)
  if (urlLower.includes('soundcloud.com')) {
    return {
      platform: 'soundcloud',
      playbackMode: 'stream',
      isRadioIngestable: true,
      requiresAlternative: false,
      embedSupported: true
    };
  }

  // Mixcloud detection (radio ingestable)
  if (urlLower.includes('mixcloud.com')) {
    return {
      platform: 'mixcloud',
      playbackMode: 'stream',
      isRadioIngestable: true,
      requiresAlternative: false,
      embedSupported: true
    };
  }

  // YouTube detection (reference-only for copyright safety)
  if (urlLower.includes('youtube.com') || urlLower.includes('youtu.be')) {
    return {
      platform: 'youtube',
      playbackMode: 'embed',
      isRadioIngestable: false,
      requiresAlternative: true,
      embedSupported: true
    };
  }

  // Audio.com detection
  if (urlLower.includes('audio.com')) {
    return {
      platform: 'audio',
      playbackMode: 'stream',
      isRadioIngestable: true,
      requiresAlternative: false,
      embedSupported: false
    };
  }

  // Direct MP3/audio file
  if (urlLower.match(/\.(mp3|wav|flac|m4a|aac|ogg)(\?|$)/)) {
    return {
      platform: 'upload',
      playbackMode: 'file',
      isRadioIngestable: true,
      requiresAlternative: false,
      embedSupported: false
    };
  }

  // Unknown/unsupported platform
  return {
    platform: 'unknown',
    playbackMode: 'embed',
    isRadioIngestable: false,
    requiresAlternative: true,
    embedSupported: false
  };
}

/**
 * Get display information for platform
 */
export function getPlatformDisplayInfo(platform: MusicPlatform): {
  name: string;
  badge: string;
  color: string;
  description: string;
} {
  switch (platform) {
    case 'spotify':
      return {
        name: 'Spotify',
        badge: 'Web-only',
        color: 'green',
        description: 'Can embed on website, cannot be aired on radio without alternative source'
      };
    case 'apple':
      return {
        name: 'Apple Music',
        badge: 'Web-only',
        color: 'gray',
        description: 'Can embed on website, cannot be aired on radio without alternative source'
      };
    case 'youtube':
      return {
        name: 'YouTube',
        badge: 'Web-only',
        color: 'red',
        description: 'Can embed on website, cannot be aired on radio without alternative source'
      };
    case 'soundcloud':
      return {
        name: 'SoundCloud',
        badge: 'Radio-ready',
        color: 'orange',
        description: 'Can be aired on radio and embedded on website'
      };
    case 'mixcloud':
      return {
        name: 'Mixcloud',
        badge: 'Radio-ready',
        color: 'blue',
        description: 'Can be aired on radio and embedded on website'
      };
    case 'audio':
      return {
        name: 'Audio.com',
        badge: 'Radio-ready',
        color: 'purple',
        description: 'Can be aired on radio'
      };
    case 'upload':
      return {
        name: 'Direct Audio',
        badge: 'Radio-ready',
        color: 'emerald',
        description: 'Direct audio file, can be aired on radio'
      };
    default:
      return {
        name: 'Unknown',
        badge: 'Unsupported',
        color: 'gray',
        description: 'Platform not supported'
      };
  }
}

/**
 * Check if URL is a reference-only platform (Spotify, Apple Music, YouTube)
 */
export function isReferenceOnly(url: string): boolean {
  const info = detectMusicPlatform(url);
  return !info.isRadioIngestable;
}

/**
 * Get platform badge component props
 */
export function getPlatformBadgeProps(platform: MusicPlatform): {
  variant: 'default' | 'secondary' | 'destructive' | 'outline';
  className: string;
  text: string;
} {
  const info = getPlatformDisplayInfo(platform);

  if (!detectMusicPlatform('').isRadioIngestable) {
    return {
      variant: 'outline',
      className: 'border-amber-500 text-amber-700 bg-amber-50',
      text: info.badge
    };
  }

  return {
    variant: 'default',
    className: 'border-green-500 text-green-700 bg-green-50',
    text: info.badge
  };
}

/**
 * Extract track ID from platform URLs for metadata fetching
 */
export function extractTrackId(url: string): { platform: MusicPlatform; trackId: string | null } {
  const platform = detectMusicPlatform(url).platform;

  switch (platform) {
    case 'spotify':
      const spotifyMatch = url.match(/spotify\.com\/track\/([a-zA-Z0-9]+)/);
      return { platform, trackId: spotifyMatch ? spotifyMatch[1] : null };

    case 'apple':
      const appleMatch = url.match(/music\.apple\.com\/[^/]+\/album\/[^/]+\/(\d+)/);
      return { platform, trackId: appleMatch ? appleMatch[1] : null };

    case 'youtube':
      const youtubeMatch = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/)([a-zA-Z0-9_-]+)/);
      return { platform, trackId: youtubeMatch ? youtubeMatch[1] : null };

    default:
      return { platform, trackId: null };
  }
}

server/azuracastHelpers.ts.content:
import axios from 'axios';
// @ts-ignore - No type definitions available\nimport SftpClient from 'ssh2-sftp-client';

const base = process.env.AZURACAST_BASE_URL;
const apiKey = process.env.AZURACAST_API_KEY;
const station = process.env.AZURACAST_STATION || 'enamorado_radio';

const headers = { 
  "X-API-Key": apiKey, 
  "Content-Type": "application/json" 
};

export async function rescanLibrary() {
  try {
    // Use admin endpoint (more reliable than station endpoint)
    await axios.post(`${base}/api/admin/station/${station}/files/rescan`, {}, { headers });
    console.log('✅ AzuraCast library rescan completed');
  } catch (error: any) {
    console.warn('⚠️ AzuraCast library rescan failed:', error.response?.status, error.response?.statusText);
    // Don't throw - treat as non-critical for workflow
  }
}

export async function ensurePlaylist(name: string) {
  const response = await axios.get(`${base}/api/station/${station}/playlists`, { headers });
  const playlists = response.data;

  let found = playlists.find((p: any) => p.name === name);
  if (found) return found;

  const created = await axios.post(`${base}/api/station/${station}/playlists`, {
    name, 
    type: "default", 
    order: "shuffle", 
    is_enabled: true,
    include_in_on_demand: true
  }, { headers });

  return created.data;
}

export async function addMediaToPlaylist(playlistId: number, paths: string[]) {
  const response = await axios.post(
    `${base}/api/station/${station}/playlist/${playlistId}/media`, 
    { paths }, 
    { headers }
  );
  return response.data;
}

export async function createSchedule(
  playlistId: number, 
  days: string[], 
  startTime: string, 
  endTime: string, 
  loopOnce = true
) {
  const response = await axios.post(
    `${base}/api/station/${station}/playlist/${playlistId}/schedule`, 
    { 
      days, 
      start_time: startTime, 
      end_time: endTime, 
      loop_once: loopOnce 
    }, 
    { headers }
  );
  return response.data;
}

export async function uploadViaSftp(localPath: string, remoteFilename: string) {
  const sftp = new SftpClient();

  await sftp.connect({
    host: process.env.AZ_SFTP_HOST!,
    port: Number(process.env.AZ_SFTP_PORT || 2022),
    username: process.env.AZ_SFTP_USER!,
    password: process.env.AZ_SFTP_PASS!
  });

  // Upload to station media folder
  await sftp.put(localPath, remoteFilename);
  await sftp.end();

  return remoteFilename;
}

export async function getNowPlaying() {
  const response = await axios.get(`${base}/api/nowplaying/${station}`, { headers });
  return response.data;
}

client/src/pages/Discover.tsx.content:
import { useState, useEffect } from "react";
import { Link } from "wouter";
import { Search, Filter, Play, Radio, User, Calendar, Tag as TagIcon, TrendingUp, Music } from "lucide-react";
import { SearchModal } from "../components/SearchModal";
import { TagSystem } from "../components/TagSystem";

interface Show {
  id: string;
  title: string;
  host: string;
  description: string;
  tags: string[];
  category: string;
  isLive: boolean;
  duration: number;
  startTime?: string;
  artwork?: string;
}

export default function Discover() {
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [showSearch, setShowSearch] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [sortBy, setSortBy] = useState<'latest' | 'popular' | 'trending'>('latest');

  const shows: Show[] = [
    {
      id: '1',
      title: 'Deep Routes',
      host: 'Marcus Rivera',
      description: 'Deep house specialist with 15+ years digging through Detroit\'s underground',
      tags: ['house', 'deep', 'underground', 'detroit'],
      category: 'Live Show',
      isLive: true,
      duration: 120,
      startTime: '2025-01-15T20:00:00'
    },
    {
      id: '2',
      title: 'Experimental Sounds',
      host: 'Alex Stone',
      description: 'Pushing boundaries with avant-garde and experimental music',
      tags: ['experimental', 'avant-garde', 'ambient', 'modern'],
      category: 'Experimental',
      isLive: false,
      duration: 90,
      startTime: '2025-01-16T18:00:00'
    },
    {
      id: '3',
      title: 'Midnight Sessions',
      host: 'Luna Park',
      description: 'Late night ambient and downtempo selections for the sleepless',
      tags: ['ambient', 'downtempo', 'chill', 'contemporary'],
      category: 'Residency',
      isLive: false,
      duration: 60,
      startTime: '2025-01-17T00:00:00'
    },
    {
      id: '4',
      title: 'Techno Archaeology',
      host: 'Luna Park',
      description: 'Digging through decades of techno evolution',
      tags: ['techno', 'underground', 'electronic', '90s'],
      category: 'Residency',
      isLive: false,
      duration: 90,
      startTime: '2025-01-18T22:00:00'
    },
    {
      id: '5',
      title: 'Jazz Futures',
      host: 'Sarah Moon',
      description: 'Contemporary jazz and experimental fusion',
      tags: ['jazz', 'experimental', 'contemporary', 'fusion'],
      category: 'Guest Mix',
      isLive: false,
      duration: 75,
      startTime: '2025-01-19T19:00:00'
    },
    {
      id: '6',
      title: 'Industrial Complex',
      host: 'Viktor Noir',
      description: 'Dark and heavy industrial soundscapes',
      tags: ['industrial', 'dark', 'electronic', 'minimal'],
      category: 'Live Show',
      isLive: false,
      duration: 100,
      startTime: '2025-01-20T21:00:00'
    }
  ];

  const filteredShows = shows.filter(show => {
    if (selectedTags.length === 0) return true;
    return selectedTags.every(tag => show.tags.includes(tag));
  });

  const sortedShows = [...filteredShows].sort((a, b) => {
    switch (sortBy) {
      case 'popular':
        return b.tags.length - a.tags.length; // More tags = more popular
      case 'trending':
        return a.isLive ? -1 : 1; // Live shows first
      case 'latest':
      default:
        return new Date(b.startTime || 0).getTime() - new Date(a.startTime || 0).getTime();
    }
  });

  const handleTagToggle = (tag: string) => {
    setSelectedTags(prev => 
      prev.includes(tag) 
        ? prev.filter(t => t !== tag)
        : [...prev, tag]
    );
  };

  const handleClearAllTags = () => {
    setSelectedTags([]);
  };

  const formatTime = (timeString?: string) => {
    if (!timeString) return '';
    return new Date(timeString).toLocaleTimeString('en-US', { 
      hour: 'numeric', 
      minute: '2-digit',
      hour12: true 
    });
  };

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'Live Show': return 'bg-navy/20 text-navy-light';
      case 'Residency': return 'bg-blue-500/20 text-blue-400';
      case 'Guest Mix': return 'bg-green-500/20 text-green-400';
      case 'Experimental': return 'bg-purple-500/20 text-purple-400';
      default: return 'bg-gray-500/20 text-gray-400';
    }
  };

  return (
    <div className="min-h-screen bg-black text-white">
      {/* Header */}
      <header className="sticky top-0 z-40 bg-black/90 backdrop-blur-xl border-b border-white/10">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-8">
              <Link href="/" className="text-2xl font-bold tracking-tight">
                ENAMORADO
              </Link>
              <nav className="hidden md:flex items-center space-x-6 text-sm">
                <Link href="/" className="text-white/80 hover:text-white transition-colors">
                  HOME
                </Link>
                <Link href="/discover" className="text-blue-400 font-medium">
                  DISCOVER
                </Link>
                <Link href="/radio" className="text-white/80 hover:text-white transition-colors">
                  RADIO
                </Link>
              </nav>
            </div>
            <div className="flex items-center space-x-4">
              <button 
                onClick={() => setShowSearch(true)}
                className="p-2 hover:bg-white/10 rounded transition-colors"
              >
                <Search className="w-5 h-5" />
              </button>
              <button 
                onClick={() => setShowFilters(!showFilters)}
                className={`p-2 rounded transition-colors ${
                  showFilters ? 'bg-white/20' : 'hover:bg-white/10'
                }`}
              >
                <Filter className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Page Header */}
        <div className="text-center mb-12">
          <h1 className="text-5xl font-bold mb-4">Discover</h1>
          <p className="text-xl text-white/80 max-w-2xl mx-auto">
            Explore our vast catalog of shows, genres, and artists. Use tags to find exactly what you're looking for.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          {/* Sidebar - Tags and Filters */}
          <div className={`lg:col-span-1 space-y-6 ${showFilters ? 'block' : 'hidden lg:block'}`}>
            {/* Sort Options */}
            <div className="bg-gray-800 rounded-lg p-4">
              <h3 className="font-medium text-white mb-3">Sort By</h3>
              <div className="space-y-2">
                {[
                  { key: 'latest', label: 'Latest', icon: Calendar },
                  { key: 'popular', label: 'Popular', icon: TrendingUp },
                  { key: 'trending', label: 'Trending', icon: Radio }
                ].map(({ key, label, icon: Icon }) => (
                  <button
                    key={key}
                    onClick={() => setSortBy(key as any)}
                    className={`w-full flex items-center space-x-2 p-2 rounded transition-colors ${
                      sortBy === key
                        ? 'bg-blue-500 text-white'
                        : 'text-gray-300 hover:bg-gray-700'
                    }`}
                  >
                    <Icon className="w-4 h-4" />
                    <span>{label}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Results Count */}
            <div className="bg-gray-800 rounded-lg p-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-400">{sortedShows.length}</div>
                <div className="text-gray-400 text-sm">Shows Found</div>
                {selectedTags.length > 0 && (
                  <div className="text-xs text-gray-500 mt-1">
                    with {selectedTags.length} tag{selectedTags.length !== 1 ? 's' : ''}
                  </div>
                )}
              </div>
            </div>

            {/* Tag System */}
            <TagSystem 
              selectedTags={selectedTags}
              onTagToggle={handleTagToggle}
              onClearAll={handleClearAllTags}
            />
          </div>

          {/* Main Content - Show Results */}
          <div className="lg:col-span-3">
            {/* Quick Stats */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
              <div className="bg-gradient-to-r from-blue-500/10 to-blue-600/10 rounded-lg p-6 border border-blue-500/20">
                <div className="flex items-center space-x-3">
                  <Radio className="w-8 h-8 text-blue-400" />
                  <div>
                    <div className="text-2xl font-bold text-blue-400">
                      {shows.filter(s => s.isLive).length}
                    </div>
                    <div className="text-blue-300 text-sm">Live Now</div>
                  </div>
                </div>
              </div>

              <div className="bg-gradient-to-r from-green-500/10 to-green-600/10 rounded-lg p-6 border border-green-500/20">
                <div className="flex items-center space-x-3">
                  <User className="w-8 h-8 text-green-400" />
                  <div>
                    <div className="text-2xl font-bold text-green-400">
                      {new Set(shows.map(s => s.host)).size}
                    </div>
                    <div className="text-green-300 text-sm">DJs & Hosts</div>
                  </div>
                </div>
              </div>

              <div className="bg-gradient-to-r from-purple-500/10 to-purple-600/10 rounded-lg p-6 border border-purple-500/20">
                <div className="flex items-center space-x-3">
                  <TagIcon className="w-8 h-8 text-purple-400" />
                  <div>
                    <div className="text-2xl font-bold text-purple-400">
                      {new Set(shows.flatMap(s => s.tags)).size}
                    </div>
                    <div className="text-purple-300 text-sm">Unique Tags</div>
                  </div>
                </div>
              </div>
            </div>

            {/* Shows Grid */}
            <div className="space-y-4">
              {sortedShows.length > 0 ? (
                sortedShows.map((show) => (
                  <div
                    key={show.id}
                    className="bg-gray-800/50 backdrop-blur-sm rounded-lg p-6 border border-white/10 hover:border-blue-500/30 transition-all duration-300 cursor-pointer group"
                  >
                    <div className="flex items-start space-x-4">
                      {/* Artwork Placeholder */}
                      <div className="w-20 h-20 bg-gradient-to-br from-gray-600 to-gray-800 rounded-lg flex-shrink-0 flex items-center justify-center relative">
                        <Music className="w-8 h-8 text-gray-400" />
                        {show.isLive && (
                          <div className="absolute -top-1 -right-1 w-4 h-4 bg-navy rounded-full animate-pulse"></div>
                        )}
                      </div>

                      {/* Show Info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between mb-2">
                          <div>
                            <h3 className="font-bold text-lg group-hover:text-blue-400 transition-colors">
                              {show.title}
                            </h3>
                            <p className="text-gray-400">by {show.host}</p>
                          </div>
                          <div className="flex items-center space-x-2">
                            <span className={`px-2 py-1 rounded text-xs font-medium ${getCategoryColor(show.category)}`}>
                              {show.category}
                            </span>
                            {show.isLive && (
                              <span className="bg-navy text-white px-2 py-1 rounded text-xs font-medium">
                                LIVE
                              </span>
                            )}
                          </div>
                        </div>

                        <p className="text-gray-300 mb-3 line-clamp-2">{show.description}</p>

                        {/* Tags */}
                        <div className="flex flex-wrap gap-2 mb-3">
                          {show.tags.map((tag, index) => (
                            <button
                              key={index}
                              onClick={(e) => {
                                e.stopPropagation();
                                handleTagToggle(tag);
                              }}
                              className={`px-2 py-1 rounded text-xs transition-colors ${
                                selectedTags.includes(tag)
                                  ? 'bg-blue-500 text-white'
                                  : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                              }`}
                            >
                              #{tag}
                            </button>
                          ))}
                        </div>

                        {/* Meta Info */}
                        <div className="flex items-center justify-between text-sm text-gray-400">
                          <div className="flex items-center space-x-4">
                            {show.startTime && (
                              <span>{formatTime(show.startTime)}</span>
                            )}
                            <span>{formatDuration(show.duration)}</span>
                          </div>
                          <button className="flex items-center space-x-2 bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded transition-colors">
                            <Play className="w-4 h-4" />
                            <span>{show.isLive ? 'Listen Live' : 'Play'}</span>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="text-center py-16">
                  <TagIcon className="w-16 h-16 mx-auto mb-4 text-gray-600" />
                  <h3 className="text-xl font-semibold mb-2">No shows found</h3>
                  <p className="text-gray-400 mb-4">
                    Try adjusting your tag selection or browse all shows
                  </p>
                  <button
                    onClick={handleClearAllTags}
                    className="bg-blue-500 hover:bg-blue-600 text-white px-6 py-3 rounded-lg transition-colors"
                  >
                    Clear All Tags
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Search Modal */}
      <SearchModal isOpen={showSearch} onClose={() => setShowSearch(false)} />
    </div>
  );
}

