import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { Music, Headphones, ArrowRight, Hash } from "lucide-react";
import { Badge } from "@/components/ui/badge";

interface Genre {
  name: string;
  slug: string;
  mixCount: number;
  episodeCount: number;
  total: number;
}

// Genre color mapping for visual distinction
const genreColors = {
  electronic: "from-blue-500 to-cyan-500",
  jungle: "from-green-500 to-emerald-500", 
  ambient: "from-purple-500 to-pink-500",
  house: "from-orange-500 to-red-500",
  techno: "from-gray-600 to-slate-700",
  "hip-hop": "from-yellow-500 to-orange-500",
  jazz: "from-indigo-500 to-purple-500",
  rock: "from-red-500 to-pink-500",
  default: "from-gray-500 to-gray-600"
};

function GenreCard({ genre }: { genre: Genre }) {
  const colorClass = genreColors[genre.slug as keyof typeof genreColors] || genreColors.default;

  return (
    <Link href={`/genre/${genre.slug}`} className="block group">
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden hover:border-navy transition-all duration-300 shadow-sm hover:shadow-md group-hover:scale-[1.02]">
        {/* Genre Header with Gradient */}
        <div className={`h-32 bg-gradient-to-br ${colorClass} relative overflow-hidden`}>
          <div className="absolute inset-0 bg-black/20"></div>
          <div className="relative z-10 h-full flex items-center justify-center">
            <div className="text-center text-white">
              <Hash className="w-8 h-8 mx-auto mb-2 opacity-80" />
              <h3 className="font-mono font-bold text-lg uppercase tracking-wide">
                {genre.name}
              </h3>
            </div>
          </div>

          {/* Hover Arrow */}
          <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
            <ArrowRight className="w-5 h-5 text-white" />
          </div>
        </div>

        {/* Content Stats */}
        <div className="p-4">
          <div className="flex items-center justify-between mb-3">
            <Badge variant="outline" className="font-mono text-xs">
              {genre.total} items
            </Badge>
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between text-sm font-mono text-gray-600">
              <div className="flex items-center">
                <Music className="w-3 h-3 mr-2" />
                Mixes
              </div>
              <span className="font-semibold">{genre.mixCount}</span>
            </div>

            {genre.episodeCount > 0 && (
              <div className="flex items-center justify-between text-sm font-mono text-gray-600">
                <div className="flex items-center">
                  <Headphones className="w-3 h-3 mr-2" />
                  Episodes
                </div>
                <span className="font-semibold">{genre.episodeCount}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </Link>
  );
}

export default function GenreDiscovery() {
  const { data: genres = [], isLoading, error } = useQuery<Genre[]>({
    queryKey: ["/api/genres"],
    queryFn: async () => {
      const r = await fetch("/api/genres", { cache: "no-store" });
      if (!r.ok) throw new Error("Failed to load genres");
      return r.json();
    },
  });

  if (isLoading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-10">
        <div className="text-center font-mono text-gray-500">Loading genres…</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-10">
        <div className="text-center font-mono text-navy">Failed to load genres</div>
      </div>
    );
  }

  const totalContent = genres.reduce((sum, genre) => sum + genre.total, 0);

  return (
    <div className="max-w-7xl mx-auto px-4 py-10">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h1 className="text-3xl font-bold font-mono text-navy mb-2">
              Explore Genres
            </h1>
            <p className="font-mono text-gray-600">
              Discover content organized by musical style and genre
            </p>
          </div>
          <div className="text-right">
            <div className="text-2xl font-bold font-mono text-gray-900">
              {genres.length}
            </div>
            <div className="text-xs font-mono text-gray-500 uppercase">
              Genres
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-6 text-sm font-mono text-gray-600">
          <div className="flex items-center">
            <Music className="w-4 h-4 mr-1" />
            {genres.reduce((sum, g) => sum + g.mixCount, 0)} total mixes
          </div>
          <div className="flex items-center">
            <Headphones className="w-4 h-4 mr-1" />
            {genres.reduce((sum, g) => sum + g.episodeCount, 0)} total episodes
          </div>
          <div className="flex items-center">
            <Hash className="w-4 h-4 mr-1" />
            {totalContent} total items
          </div>
        </div>
      </div>

      {/* Genre Grid */}
      {genres.length === 0 ? (
        <div className="text-center py-12">
          <Hash className="w-16 h-16 text-gray-400 mx-auto mb-4" />
          <h3 className="font-mono text-lg text-gray-600 mb-2">No genres yet</h3>
          <p className="font-mono text-sm text-gray-500 mb-6">
            Submit some content to start building your genre collection
          </p>
          <Link href="/submit-mix">
            <button className="bg-navy hover:bg-navy-dark text-white font-mono px-6 py-2 rounded">
              Submit Content
            </button>
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {genres.map((genre) => (
            <GenreCard key={genre.slug} genre={genre} />
          ))}
        </div>
      )}

      {/* Footer Note */}
      {genres.length > 0 && (
        <div className="mt-12 text-center">
          <p className="font-mono text-xs text-gray-500">
            Genres are automatically detected from submitted content. 
            <Link href="/submit-mix" className="text-navy hover:underline ml-1">
              Add more content →
            </Link>
          </p>
        </div>
      )}
    </div>
  );
}

client/src/components/AdminMixCard.tsx.content:
import { useState, useEffect } from 'react';
import { Play, Check, Star, X, Upload, ExternalLink, Music, Clock, User } from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { getThumbUrl, formatDateSafe } from "@/lib/display";

interface AdminMixCardProps {
  mix: {
    id: number;
    name: string;
    title: string;
    genre: string;
    about: string;
    url: string;
    artUrl?: string;
    featureOnSite?: boolean;
    pushToAzura?: boolean;
    filePath?: string;
    fileName?: string;
    submittedAt: string;
    status: 'pending' | 'approved' | 'featured';
  };
  onApprove?: (id: number) => void;
  onFeature?: (id: number) => void;
  onDelete?: (id: number) => void;
  onAttachFile?: (id: number, file: File) => void;
  onPushToAzura?: (id: number) => void;
}

export default function AdminMixCard({ 
  mix, 
  onApprove, 
  onFeature, 
  onDelete, 
  onAttachFile, 
  onPushToAzura 
}: AdminMixCardProps) {

  const isApproved = mix.status === 'approved' || mix.status === 'featured';
  const isFeatured = mix.status === 'featured';
  const [artwork, setArtwork] = useState<string>(getThumbUrl(mix.artUrl));

  useEffect(() => {
    let ignore = false;

    async function fetchOembedArtwork() {
      if (mix.artUrl || !mix.url) return;

      if (mix.url.includes('soundcloud.com') || mix.url.includes('mixcloud.com')) {
        try {
          const response = await fetch(`/api/oembed?url=${encodeURIComponent(mix.url)}`);
          if (!response.ok) return;

          const data = await response.json();
          if (!ignore && (data?.thumbnail_url || data?.artUrl)) {
            const artworkUrl = data.thumbnail_url || data.artUrl;
            setArtwork(artworkUrl);

            try {
              const updateResponse = await fetch(`/api/mixes/${mix.id}/artwork`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ artUrl: artworkUrl })
              });

              if (updateResponse.ok) {
                (mix as any).artUrl = artworkUrl;
              }
            } catch (error) {
              console.error('Error saving artwork for mix:', mix.id, error);
            }
          }
        } catch (error) {
          console.error('Failed to fetch oembed artwork for mix:', mix.id, error);
        }
      }
    }

    fetchOembedArtwork();
    return () => { ignore = true; };
  }, [mix.url, mix.id, mix.artUrl]);

  // Admin toggle functions
  async function toggleApprove() {
    if (onApprove) {
      onApprove(mix.id);
    } else {
      // Fallback to direct API call
      try {
        const response = await fetch(`/api/admin/mixes/${mix.id}/approve`, { method: 'POST' });
        if (response.ok) {
          window.location.reload(); // Simple refresh for now
        }
      } catch (error) {
        console.error('Error toggling approval:', error);
      }
    }
  }

  async function toggleFeature() {
    if (!isApproved) {
      alert('Mix must be approved first before featuring');
      return;
    }

    if (onFeature) {
      onFeature(mix.id);
    } else {
      // Fallback to direct API call
      try {
        const response = await fetch(`/api/admin/mixes/${mix.id}/feature`, { method: 'POST' });
        if (response.ok) {
          window.location.reload(); // Simple refresh for now
        }
      } catch (error) {
        console.error('Error toggling feature:', error);
      }
    }
  }

  return (
    <div className="relative bg-white dark:bg-gray-900 rounded-xl overflow-hidden transition-all duration-300 group focus-within:outline-none focus-within:ring-2 focus-within:ring-navy/50">
      {/* Hairline border */}
      <div className="absolute inset-0 rounded-xl pointer-events-none shadow-[0_0_0_1px_rgba(12,12,13,0.08)] dark:shadow-[0_0_0_1px_rgba(255,255,255,0.1)] group-hover:shadow-[0_0_0_1px_rgba(0,63,135,0.3),0_6px_14px_rgba(0,0,0,0.12)] dark:group-hover:shadow-[0_0_0_1px_rgba(0,63,135,0.5),0_6px_14px_rgba(0,0,0,0.5)] transition-shadow"></div>

      {/* Artwork */}
      <div className="aspect-square bg-gray-200 dark:bg-gray-800 relative overflow-hidden">
        <img 
          src={artwork} 
          alt={mix.title}
          className="w-full h-full object-cover object-center group-hover:scale-105 transition-transform duration-300"
        />

        {/* Admin Status Badges */}
        <div className="absolute top-3 left-3 space-y-1">
          {isApproved ? (
            <Badge variant="default" className="text-xs font-mono bg-green-600 border-0">
              APPROVED
            </Badge>
          ) : (
            <Badge className="text-xs font-mono bg-yellow-100 text-yellow-700 border-0">
              PENDING
            </Badge>
          )}

          {isFeatured && (
            <Badge variant="default" className="text-xs font-mono bg-yellow-600 border-0">
              FEATURED
            </Badge>
          )}
        </div>
      </div>

      <div className="p-3 sm:p-4">
        {/* Genre and Date */}
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs font-mono bg-navy/10 dark:bg-navy/30 text-navy dark:text-navy-light px-2 py-0.5 rounded-full uppercase">
            {mix.genre}
          </span>
          <div className="text-xs font-mono text-gray-500 dark:text-gray-400 flex items-center">
            <Clock className="w-3 h-3 mr-1" />
            {formatDateSafe(mix.submittedAt)}
          </div>
        </div>

        {/* Title and Artist */}
        <div className="mb-3">
          <h4 className="text-base sm:text-lg font-bold font-mono text-gray-900 dark:text-white mb-1 group-hover:text-navy dark:group-hover:text-navy-light transition-colors">
            {mix.title}
          </h4>
          <div className="flex items-center text-gray-600 dark:text-gray-400 font-mono text-sm">
            <User className="w-3 h-3 mr-1" />
            {mix.name}
          </div>
        </div>

        {/* Admin Action Buttons */}
        <div className="space-y-2 mb-4">
          <div className="flex gap-2">
            <Button
              onClick={toggleApprove}
              variant={isApproved ? "default" : "outline"}
              size="sm"
              className={isApproved ? "bg-green-600 hover:bg-green-700" : "text-green-600 border-green-600 hover:bg-green-50"}
            >
              <Check className="h-3 w-3 mr-1" />
              {isApproved ? 'Approved ✓' : 'Approve'}
            </Button>

            <Button
              onClick={toggleFeature}
              variant={isFeatured ? "default" : "outline"}
              size="sm"
              className={
                isFeatured 
                  ? "bg-yellow-600 hover:bg-yellow-700" 
                  : !isApproved 
                    ? "text-gray-400 border-gray-400 cursor-not-allowed" 
                    : "text-yellow-600 border-yellow-600 hover:bg-yellow-50"
              }
              disabled={!isApproved}
            >
              <Star className="h-3 w-3 mr-1" />
              {isFeatured ? 'Featured ⭐' : 'Feature'}
            </Button>
          </div>

          {onDelete && (
            <Button
              onClick={() => onDelete(mix.id)}
              variant="outline"
              size="sm"
              className="text-red-600 border-red-600 hover:bg-red-50 w-full"
            >
              <X className="h-3 w-3 mr-1" />
              Delete
            </Button>
          )}
        </div>

        {/* File Upload Section */}
        <div className="border-t pt-3 mb-3">
          <div className="text-xs text-gray-500 mb-2">
            {mix.filePath ? 'File attached' : 'No file attached'}
          </div>
          {onAttachFile && (
            <Button
              variant="outline"
              size="sm"
              className="text-blue-600 border-blue-600 hover:bg-blue-50 w-full mb-2"
              onClick={() => {
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = '.mp3,.wav,.m4a';
                input.onchange = (e) => {
                  const file = (e.target as HTMLInputElement).files?.[0];
                  if (file) onAttachFile(mix.id, file);
                };
                input.click();
              }}
            >
              <Upload className="h-3 w-3 mr-1" />
              {mix.filePath ? 'Replace MP3' : 'Attach MP3'}
            </Button>
          )}

          {mix.filePath && onPushToAzura && (
            <Button
              variant="outline"
              size="sm"
              className="text-purple-600 border-purple-600 hover:bg-purple-50 w-full"
              onClick={() => onPushToAzura(mix.id)}
            >
              Push to AzuraCast
            </Button>
          )}
        </div>

        {/* Listen Button */}
        <Button 
          size="sm" 
          className="bg-navy hover:bg-navy-dark text-white font-mono w-full"
          onClick={() => window.open(mix.url, '_blank')}
        >
          <ExternalLink className="w-4 h-4 mr-2" />
          Listen to Original
        </Button>
      </div>
    </div>
  );
}

