import React, { useState } from 'react';
import { defaultThemes, PlayerTheme } from '@/types/playerThemes';
import { Play, Pause, SkipForward, Volume2, Users } from 'lucide-react';

interface PlayerThemeDemoProps {
  theme: PlayerTheme;
  isPlaying: boolean;
  onThemeSelect: (themeId: string) => void;
}

function ThemePreview({ theme, isPlaying, onThemeSelect }: PlayerThemeDemoProps) {
  const playerStyles: React.CSSProperties = {
    background: theme.colors.background,
    color: theme.colors.text,
    borderColor: theme.colors.border,
    borderRadius: theme.effects.borderRadius,
    boxShadow: theme.effects.shadow,
    fontFamily: theme.fonts.primary,
    ...(theme.effects.glassEffect && {
      backdropFilter: 'blur(20px)',
      border: `1px solid ${theme.colors.border}`,
    }),
  };

  return (
    <div className="p-4">
      <div className="mb-3">
        <h3 className="font-mono font-semibold text-sm">{theme.name}</h3>
        <p className="font-mono text-xs text-gray-600">{theme.description}</p>
      </div>

      <div style={playerStyles} className="border p-3 max-w-sm cursor-pointer transform hover:scale-105 transition-transform">
        {/* Mini player preview */}
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center space-x-2">
            <div 
              className={`w-1.5 h-1.5 rounded-full ${theme.effects.animations ? 'animate-pulse' : ''}`}
              style={{ backgroundColor: theme.colors.accent }}
            ></div>
            <span style={{ fontFamily: theme.fonts.mono }} className="text-xs font-medium">LIVE</span>
          </div>
          <div className="flex items-center space-x-1" style={{ color: theme.colors.secondary }}>
            <Users className="w-2.5 h-2.5" />
            <span style={{ fontFamily: theme.fonts.mono }} className="text-xs">23</span>
          </div>
        </div>

        <div className="flex items-center space-x-2 mb-2">
          <div className="w-8 h-8 bg-gray-300 rounded flex items-center justify-center">
            <span className="text-gray-500 text-xs">♪</span>
          </div>
          <div className="flex-1 min-w-0">
            <h4 style={{ fontFamily: theme.fonts.mono }} className="text-xs font-medium truncate">
              Sample Track
            </h4>
            <p style={{ fontFamily: theme.fonts.mono, color: theme.colors.secondary }} className="text-xs truncate">
              Demo Artist
            </p>
          </div>
        </div>

        {/* Progress bar */}
        <div className="mb-2">
          <div 
            className="w-full h-0.5 rounded-full"
            style={{ backgroundColor: theme.colors.progressBg }}
          >
            <div 
              className="h-0.5 rounded-full w-1/3"
              style={{ background: theme.colors.progressFill }}
            ></div>
          </div>
        </div>

        {/* Controls */}
        <div className="flex items-center justify-center space-x-2">
          <button
            className="flex items-center justify-center w-6 h-6 text-white rounded-full"
            style={{ 
              background: theme.colors.buttonBg,
              borderRadius: theme.effects.borderRadius,
            }}
          >
            {isPlaying ? (
              <Pause className="w-2.5 h-2.5" />
            ) : (
              <Play className="w-2.5 h-2.5 ml-0.5" />
            )}
          </button>

          <button
            className="flex items-center justify-center w-4 h-4"
            style={{ color: theme.colors.secondary }}
          >
            <SkipForward className="w-2.5 h-2.5" />
          </button>

          <div className="flex items-center space-x-1" style={{ color: theme.colors.secondary }}>
            <Volume2 className="w-2.5 h-2.5" />
            <div 
              className="w-8 rounded-full h-0.5"
              style={{ backgroundColor: theme.colors.progressBg }}
            >
              <div 
                className="h-0.5 rounded-full w-2/3"
                style={{ backgroundColor: theme.colors.secondary }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      <button
        onClick={() => onThemeSelect(theme.id)}
        className="w-full mt-3 px-3 py-2 bg-navy text-white rounded font-mono text-xs hover:bg-navy-dark transition-colors"
      >
        Apply Theme
      </button>
    </div>
  );
}

export function PlayerThemeDemo() {
  const [isPlaying, setIsPlaying] = useState(true);

  const handleThemeSelect = (themeId: string) => {
    // Save theme preference
    localStorage.setItem('enamorado-player-theme', themeId);

    // Show confirmation
    const themeDisplayName = defaultThemes.find(t => t.id === themeId)?.name || 'Unknown';
    alert(`Applied "${themeDisplayName}" theme! Refresh the page to see changes in the radio player.`);
  };

  return (
    <div className="bg-white rounded-lg border border-gray-200 p-6">
      <div className="text-center mb-6">
        <h2 className="text-xl font-mono font-bold mb-2">Player Themes</h2>
        <p className="font-mono text-sm text-gray-600">
          Customize your radio player experience
        </p>
        <button
          onClick={() => setIsPlaying(!isPlaying)}
          className="mt-2 px-3 py-1 border border-gray-300 rounded font-mono text-xs hover:bg-gray-50"
        >
          {isPlaying ? 'Preview Paused' : 'Preview Playing'}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {defaultThemes.map((theme) => (
          <ThemePreview
            key={theme.id}
            theme={theme}
            isPlaying={isPlaying}
            onThemeSelect={handleThemeSelect}
          />
        ))}
      </div>

      <div className="mt-6 p-4 bg-gray-50 rounded-lg">
        <h3 className="font-mono font-semibold text-sm mb-2">How to Use</h3>
        <ul className="font-mono text-xs text-gray-600 space-y-1">
          <li>• Click "Apply Theme" on any theme preview above</li>
          <li>• Your selection is saved automatically</li>
          <li>• Refresh the page to see changes in the top-right radio player</li>
          <li>• You can also change themes using the palette icon on the player</li>
        </ul>
      </div>
    </div>
  );
}

server/persistentStorage.ts.content:
import fs from 'fs/promises';
import path from 'path';
import {
  Episode, 
  Guide,
  HeroBanner,
  MixSubmission,
  PlaylistSubmission,
  EpisodeSubmission,
  Schedule, 
  ResidentApplication,
  Resident,
  Admin,
  Settings,
  CurrentPlayback,
  AlbumSuggestion,
  AlbumVote,
  AlbumPick,
  AlbumPickItem,
  AlbumSuggestionNote,
  InsertEpisode,
  InsertGuide,
  InsertHeroBanner,
  InsertMixSubmission,
  InsertPlaylistSubmission,
  InsertEpisodeSubmission,
  InsertSchedule,
  InsertResidentApplication,
  InsertResident,
  InsertAdmin,
  InsertSettings,
  InsertCurrentPlayback,
  InsertAlbumSuggestion,
  InsertAlbumVote,
  InsertAlbumPick,
  InsertAlbumPickItem,
  InsertAlbumSuggestionNote
} from "@shared/schema";
import { IStorage } from "./storage";
import { backupManager } from "./backupManager";

// File-based persistent storage to solve the memory reset issue
export class FileStorage implements IStorage {
  private dataDir = './data';
  private nextIdFile = path.join(this.dataDir, 'nextId.json');

  private episodes: Episode[] = [];
  private guides: Guide[] = [];
  private heroBanners: HeroBanner[] = [];
  private mixSubmissions: MixSubmission[] = [];
  private playlistSubmissions: PlaylistSubmission[] = [];
  private episodeSubmissions: EpisodeSubmission[] = [];
  private scheduleItems: Schedule[] = [];
  private residentApplications: ResidentApplication[] = [];
  private residents: Resident[] = [];
  private admins: Admin[] = [];
  private settings: Settings[] = [];
  private currentPlayback: CurrentPlayback | null = null;
  private albumSuggestions: AlbumSuggestion[] = [];
  private albumVotes: AlbumVote[] = [];
  private albumPicks: AlbumPick[] = [];
  private albumPickItems: AlbumPickItem[] = [];
  private albumSuggestionNotes: AlbumSuggestionNote[] = [];
  private nextId = 1;

  constructor() {
    this.loadData();
  }

  // Migrate data to ensure both status field and boolean flags are properly set
  private migrateMixData(mix: any): MixSubmission {
    // Preserve status field as primary source of truth, set boolean flags based on status
    if (mix.status && typeof mix.status === 'string') {
      const newMix = {
        ...mix,
        // Keep the status field as canonical source of truth
        status: mix.status,
        // Set boolean flags based on status for backward compatibility
        featureOnSite: mix.status === 'featured',
        pushToAzura: mix.status === 'approved' || mix.status === 'featured'
      };
      return newMix;
    }

    // If no status field, infer it from boolean flags (legacy data)
    let status = 'pending';
    if (mix.featureOnSite) {
      status = 'featured';
    } else if (mix.pushToAzura) {
      status = 'approved';
    }

    return {
      ...mix,
      status,
      featureOnSite: mix.featureOnSite ?? false,
      pushToAzura: mix.pushToAzura ?? false
    };
  }

  private async ensureDataDir() {
    try {
      await fs.mkdir(this.dataDir, { recursive: true });
    } catch (error) {
      // Directory already exists or other error
    }
  }

  public async reloadData() {
    await this.loadData();
    console.log(`🔄 Storage data reloaded: ${this.mixSubmissions.length} mix submissions found`);
  }

  private async loadData() {
    await this.ensureDataDir();

    try {
      // Load all data files
      const files = [
        'episodes.json',
        'guides.json',
        'heroBanners.json',
        'mixSubmissions.json',
        'playlistSubmissions.json',
        'episodeSubmissions.json',
        'scheduleItems.json',
        'residentApplications.json',
        'residents.json',
        'admins.json',
        'settings.json',
        'currentPlayback.json',
        'albumSuggestions.json',
        'albumVotes.json',
        'albumPicks.json',
        'albumPickItems.json',
        'albumSuggestionNotes.json'
      ];

      for (const file of files) {
        try {
          const filePath = path.join(this.dataDir, file);
          const data = await fs.readFile(filePath, 'utf8');
          const parsed = JSON.parse(data);

          switch (file) {
            case 'episodes.json':
              this.episodes = parsed || [];
              break;
            case 'guides.json':
              this.guides = parsed || [];
              break;
            case 'heroBanners.json':
              this.heroBanners = parsed || [];
              break;
            case 'mixSubmissions.json':
              this.mixSubmissions = (parsed || []).map((mix: any) => this.migrateMixData(mix));
              break;
            case 'playlistSubmissions.json':
              this.playlistSubmissions = parsed || [];
              break;
            case 'episodeSubmissions.json':
              this.episodeSubmissions = parsed || [];
              break;
            case 'scheduleItems.json':
              this.scheduleItems = parsed || [];
              break;
            case 'residentApplications.json':
              this.residentApplications = parsed || [];
              break;
            case 'residents.json':
              this.residents = parsed || [];
              break;
            case 'admins.json':
              this.admins = parsed || [];
              break;
            case 'settings.json':
              this.settings = parsed || [];
              break;
            case 'currentPlayback.json':
              this.currentPlayback = parsed || null;
              break;
            case 'albumSuggestions.json':
              this.albumSuggestions = parsed || [];
              break;
            case 'albumVotes.json':
              this.albumVotes = parsed || [];
              break;
            case 'albumPicks.json':
              this.albumPicks = parsed || [];
              break;
            case 'albumPickItems.json':
              this.albumPickItems = parsed || [];
              break;
            case 'albumSuggestionNotes.json':
              this.albumSuggestionNotes = parsed || [];
              break;
          }
        } catch (error) {
          // File doesn't exist yet - start with empty array
          console.log(`No existing ${file} found, starting fresh`);
        }
      }

      // Load next ID
      try {
        const idData = await fs.readFile(this.nextIdFile, 'utf8');
        this.nextId = JSON.parse(idData).nextId || 1;
      } catch (error) {
        this.nextId = 1;
      }

      // Safety check: Ensure nextId is higher than all existing IDs to prevent collisions
      const allIds: number[] = [
        ...this.episodes.map(e => e.id),
        ...this.guides.map(g => g.id),
        ...this.heroBanners.map(b => b.id),
        ...this.mixSubmissions.map(m => m.id),
        ...this.playlistSubmissions.map(p => p.id),
        ...this.episodeSubmissions.map(e => e.id),
        ...this.scheduleItems.map(s => s.id),
        ...this.residentApplications.map(r => r.id),
        ...this.residents.map(r => r.id),
        ...this.admins.map(a => a.id),
        ...this.albumSuggestions.map(a => a.id),
        ...this.albumVotes.map(v => v.id),
        ...this.albumPicks.map(p => p.id),
        ...this.albumPickItems.map(i => i.id),
        ...this.albumSuggestionNotes.map(n => n.id)
      ];

      const maxExistingId = allIds.length > 0 ? Math.max(...allIds) : 0;
      if (maxExistingId >= this.nextId) {
        this.nextId = maxExistingId + 1;
        console.log(`⚠️  nextId corrected from file to ${this.nextId} (max existing ID: ${maxExistingId})`);
        // Save corrected nextId
        await fs.writeFile(this.nextIdFile, JSON.stringify({ nextId: this.nextId }));
      }

      console.log(`Loaded persistent data: ${this.mixSubmissions.length} mix submissions found`);

    } catch (error) {
      console.error('Error loading persistent data:', error);
    }
  }

  private async saveData(type: string, data: any) {
    await this.ensureDataDir();

    try {
      const filePath = path.join(this.dataDir, `${type}.json`);
      await fs.writeFile(filePath, JSON.stringify(data, null, 2));

      // Save next ID
      await fs.writeFile(this.nextIdFile, JSON.stringify({ nextId: this.nextId }));
    } catch (error) {
      console.error(`Error saving ${type}:`, error);
    }
  }

  // Episodes
  async getEpisodes(filters?: { featured?: boolean; genre?: string; limit?: number }): Promise<Episode[]> {
    let filtered = [...this.episodes];

    if (filters?.featured !== undefined) {
      filtered = filtered.filter(e => e.isFeatured === filters.featured);
    }

    if (filters?.genre) {
      filtered = filtered.filter(e => e.genre.toLowerCase().includes(filters.genre!.toLowerCase()));
    }

    filtered.sort((a, b) => new Date(b.airDate).getTime() - new Date(a.airDate).getTime());

    if (filters?.limit) {
      filtered = filtered.slice(0, filters.limit);
    }

    return filtered;
  }

  async getEpisodeById(id: number): Promise<Episode | undefined> {
    return this.episodes.find(e => e.id === id);
  }

  async createEpisode(episode: InsertEpisode): Promise<Episode> {
    const newEpisode: Episode = {
      ...episode,
      id: this.nextId++,
      viewCount: 0,
      airDate: new Date(),
      createdAt: new Date(),
      description: episode.description || null,
      seriesTitle: episode.seriesTitle || null,
      episodeNumber: episode.episodeNumber || null,
      artworkUrl: episode.artworkUrl || null,
      tags: episode.tags || null,
      status: episode.status || 'published',
      isLive: episode.isLive ?? false,
      isFeatured: episode.isFeatured ?? false,
    };
    this.episodes.push(newEpisode);
    await this.saveData('episodes', this.episodes);
    return newEpisode;
  }

  async updateEpisode(id: number, episode: Partial<Episode>): Promise<Episode> {
    const index = this.episodes.findIndex(e => e.id === id);
    if (index === -1) throw new Error('Episode not found');

    this.episodes[index] = { ...this.episodes[index], ...episode };
    await this.saveData('episodes', this.episodes);
    return this.episodes[index];
  }

  async deleteEpisode(id: number): Promise<void> {
    const index = this.episodes.findIndex(e => e.id === id);
    if (index !== -1) {
      // Create backup before destructive operation
      await backupManager.createBackup(`Before deleting episode ${id}`);

      this.episodes.splice(index, 1);
      await this.saveData('episodes', this.episodes);
    }
  }

  // Guides
  async getGuides(filters?: { featured?: boolean; type?: string; limit?: number }): Promise<Guide[]> {
    let filtered = [...this.guides];

    if (filters?.featured !== undefined) {
      filtered = filtered.filter(g => g.isFeatured === filters.featured);
    }

    if (filters?.type) {
      filtered = filtered.filter(g => g.guideType === filters.type);
    }

    filtered.sort((a, b) => {
      const aTime = a.publishedAt ? new Date(a.publishedAt).getTime() : 0;
      const bTime = b.publishedAt ? new Date(b.publishedAt).getTime() : 0;
      return bTime - aTime;
    });

    if (filters?.limit) {
      filtered = filtered.slice(0, filters.limit);
    }

    return filtered;
  }

  async getGuideById(id: number): Promise<Guide | undefined> {
    return this.guides.find(g => g.id === id);
  }

  async getGuideBySlug(slug: string): Promise<Guide | undefined> {
    return this.guides.find(g => g.slug === slug);
  }

  async createGuide(guide: InsertGuide): Promise<Guide> {
    const newGuide: Guide = {
      ...guide,
      id: this.nextId++,
      viewCount: 0,
      publishedAt: new Date(),
      updatedAt: new Date(),
      tags: guide.tags || null,
      status: guide.status || 'published',
      isFeatured: guide.isFeatured ?? false,
      sections: guide.sections || null,
      coverImageUrl: guide.coverImageUrl || null,
    };
    this.guides.push(newGuide);
    await this.saveData('guides', this.guides);
    return newGuide;
  }

  async updateGuide(id: number, guide: Partial<Guide>): Promise<Guide> {
    const index = this.guides.findIndex(g => g.id === id);
    if (index === -1) throw new Error('Guide not found');

    this.guides[index] = { ...this.guides[index], ...guide, updatedAt: new Date() };
    await this.saveData('guides', this.guides);
    return this.guides[index];
  }

  async deleteGuide(id: number): Promise<void> {
    const index = this.guides.findIndex(g => g.id === id);
    if (index !== -1) {
      // Create backup before destructive operation
      await backupManager.createBackup(`Before deleting guide ${id}`);

      this.guides.splice(index, 1);
      await this.saveData('guides', this.guides);
    }
  }

  // Hero Banners
  async getHeroBanners(): Promise<HeroBanner[]> {
    return this.heroBanners.sort((a, b) => b.displayOrder - a.displayOrder);
  }

  async getActiveBanner(): Promise<HeroBanner | undefined> {
    return this.heroBanners.find(b => b.isActive);
  }

  async getHeroBannerById(id: number): Promise<HeroBanner | undefined> {
    return this.heroBanners.find(b => b.id === id);
  }

  async createHeroBanner(banner: InsertHeroBanner): Promise<HeroBanner> {
    const newBanner: HeroBanner = {
      ...banner,
      id: this.nextId++,
      createdAt: new Date(),
    };
    this.heroBanners.push(newBanner);
    await this.saveData('heroBanners', this.heroBanners);
    console.log(`FileStorage: Created hero banner ${newBanner.id}: "${newBanner.title}"`);
    return newBanner;
  }

  async updateHeroBanner(id: number, updates: Partial<HeroBanner>): Promise<HeroBanner> {
    const index = this.heroBanners.findIndex(b => b.id === id);
    if (index === -1) throw new Error('Hero banner not found');

    this.heroBanners[index] = { ...this.heroBanners[index], ...updates };
    await this.saveData('heroBanners', this.heroBanners);
    console.log(`FileStorage: Updated hero banner ${id}`);
    return this.heroBanners[index];
  }

  async deleteHeroBanner(id: number): Promise<void> {
    const index = this.heroBanners.findIndex(b => b.id === id);
    if (index !== -1) {
      await backupManager.createBackup(`Before deleting hero banner ${id}`);
      this.heroBanners.splice(index, 1);
      await this.saveData('heroBanners', this.heroBanners);
    }
  }

