import { AudioShow } from '@/types/audio';
import { cn } from '@/lib/utils';
import { Calendar, Clock, User, Music } from 'lucide-react';
import { Waveform } from './ui/waveform';

interface FeaturedShowsProps {
  shows: AudioShow[];
  onShowSelect: (show: AudioShow) => void;
  currentShowId?: number;
}

const genreColors = {
  'Deep House': 'from-purple-500 to-pink-500',
  'Techno': 'from-blue-500 to-cyan-500',
  'Hip-Hop': 'from-orange-500 to-navy',
  'Jazz': 'from-indigo-500 to-purple-500',
  'Indie': 'from-green-500 to-blue-500',
  'Electronic': 'from-cyan-500 to-blue-500',
};

export function FeaturedShows({ shows, onShowSelect, currentShowId }: FeaturedShowsProps) {
  const formatTime = (date: Date | string | null) => {
    if (!date) return '';
    try {
      const d = typeof date === 'string' ? new Date(date) : date;
      if (isNaN(d.getTime())) return '';
      return d.toLocaleTimeString('en-US', { 
        hour: 'numeric', 
        minute: '2-digit',
        hour12: true 
      });
    } catch (e) {
      return '';
    }
  };

  const formatDate = (date: Date | string | null) => {
    if (!date) return '';
    try {
      const d = typeof date === 'string' ? new Date(date) : date;
      if (isNaN(d.getTime())) return '';
      return d.toLocaleDateString('en-US', { 
        month: 'short', 
        day: 'numeric' 
      });
    } catch (e) {
      return '';
    }
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
      {shows.map((show) => (
        <div
          key={show.id}
          className={cn(
            "group cursor-pointer transition-all duration-300 hover:transform hover:scale-105",
            "bg-gradient-to-br from-white/5 to-white/10 backdrop-blur-sm",
            "border border-white/10 rounded-xl p-4",
            "hover:shadow-lg hover:shadow-blue-500/20 hover:border-blue-500/30",
            currentShowId === show.id && "ring-2 ring-blue-500"
          )}
          onClick={() => onShowSelect(show)}
        >
          <div className={cn(
            "w-full h-32 rounded-lg mb-3 flex items-center justify-center relative overflow-hidden",
            "bg-gradient-to-br",
            genreColors[show.genre as keyof typeof genreColors] || 'from-gray-500 to-gray-600'
          )}>
            <div className="absolute inset-0 bg-black/20"></div>
            <div className="relative z-10">
              {show.genre === 'Deep House' || show.genre === 'Techno' || show.genre === 'Electronic' ? (
                <Waveform className="w-16 h-16" barCount={8} color="white" />
              ) : show.genre === 'Hip-Hop' ? (
                <Music className="w-12 h-12 text-white" />
              ) : show.genre === 'Jazz' ? (
                <div className="text-white text-3xl">🎷</div>
              ) : (
                <div className="text-white text-3xl">🎸</div>
              )}
            </div>
            {show.isLive && (
              <div className="absolute top-2 right-2 flex items-center space-x-1">
                <div className="w-2 h-2 bg-navy rounded-full animate-pulse"></div>
                <span className="text-xs text-white/90 font-medium">LIVE</span>
              </div>
            )}
          </div>

          <div className="space-y-2">
            <h4 className="font-semibold text-white group-hover:text-blue-400 transition-colors line-clamp-2">
              {show.title}
            </h4>
            <div className="flex items-center space-x-2 text-white/70">
              <User className="w-3 h-3" />
              <span className="text-sm">{show.host}</span>
            </div>
            {show.description && (
              <p className="text-white/60 text-xs line-clamp-2">
                {show.description}
              </p>
            )}
            <div className="flex items-center justify-between pt-2">
              <div className="flex items-center space-x-4">
                <span className="text-xs text-blue-400 font-medium">
                  {show.genre}
                </span>
                {show.scheduledAt && (
                  <div className="flex items-center space-x-1 text-white/50">
                    <Clock className="w-3 h-3" />
                    <span className="text-xs">
                      {formatTime(show.scheduledAt)}
                    </span>
                  </div>
                )}
              </div>
              {show.duration && (
                <span className="text-xs text-white/50">
                  {show.duration}min
                </span>
              )}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

client/src/components/SoundCloudEmbed.ts.content:
import { useState, useEffect } from 'react';
import { getSoundCloudEmbedUrl } from '../utils/soundcloud';

interface SoundCloudEmbedProps {
  url: string;
  title?: string;
  artist?: string;
  height?: number;
  className?: string;
}

export function SoundCloudEmbed({ 
  url, 
  title, 
  artist, 
  height = 300,
  className = "" 
}: SoundCloudEmbedProps) {
  const [embedUrl, setEmbedUrl] = useState<string | null>(null);

  useEffect(() => {
    if (url) {
      const embed = getSoundCloudEmbedUrl(url);
      setEmbedUrl(embed);
    }
  }, [url]);

  if (!embedUrl) {
    return (
      <div className={`${className} bg-gray-800 rounded-lg p-4 flex items-center justify-center`} style={{ height }}>
        <div className="text-white/60 text-center">
          <div className="text-sm">Unable to load SoundCloud embed</div>
          <div className="text-xs mt-1">Check the URL format</div>
        </div>
      </div>
    );
  }

  return (
    <div className={`${className} rounded-lg overflow-hidden`}>
      <iframe
        width="100%"
        height={height}
        scrolling="no"
        frameBorder="no"
        allow="autoplay"
        src={embedUrl}
        title={title ? `${title} by ${artist}` : "SoundCloud player"}
        className="w-full"
      />
    </div>
  );
}

client/src/components/ui/sheet.tsx.content:
"use client"

import * as React from "react"
import * as SheetPrimitive from "@radix-ui/react-dialog"
import { cva, type VariantProps } from "class-variance-authority"
import { X } from "lucide-react"

import { cn } from "@/lib/utils"

const Sheet = SheetPrimitive.Root

const SheetTrigger = SheetPrimitive.Trigger

const SheetClose = SheetPrimitive.Close

const SheetPortal = SheetPrimitive.Portal

const SheetOverlay = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Overlay
    className={cn(
      "fixed inset-0 z-50 bg-black/80  data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className
    )}
    {...props}
    ref={ref}
  />
))
SheetOverlay.displayName = SheetPrimitive.Overlay.displayName

const sheetVariants = cva(
  "fixed z-50 gap-4 bg-background p-6 shadow-lg transition ease-in-out data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:duration-300 data-[state=open]:duration-500",
  {
    variants: {
      side: {
        top: "inset-x-0 top-0 border-b data-[state=closed]:slide-out-to-top data-[state=open]:slide-in-from-top",
        bottom:
          "inset-x-0 bottom-0 border-t data-[state=closed]:slide-out-to-bottom data-[state=open]:slide-in-from-bottom",
        left: "inset-y-0 left-0 h-full w-3/4 border-r data-[state=closed]:slide-out-to-left data-[state=open]:slide-in-from-left sm:max-w-sm",
        right:
          "inset-y-0 right-0 h-full w-3/4  border-l data-[state=closed]:slide-out-to-right data-[state=open]:slide-in-from-right sm:max-w-sm",
      },
    },
    defaultVariants: {
      side: "right",
    },
  }
)

interface SheetContentProps
  extends React.ComponentPropsWithoutRef<typeof SheetPrimitive.Content>,
    VariantProps<typeof sheetVariants> {}

const SheetContent = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Content>,
  SheetContentProps
>(({ side = "right", className, children, ...props }, ref) => (
  <SheetPortal>
    <SheetOverlay />
    <SheetPrimitive.Content
      ref={ref}
      className={cn(sheetVariants({ side }), className)}
      {...props}
    >
      {children}
      <SheetPrimitive.Close className="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-secondary">
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </SheetPrimitive.Close>
    </SheetPrimitive.Content>
  </SheetPortal>
))
SheetContent.displayName = SheetPrimitive.Content.displayName

const SheetHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col space-y-2 text-center sm:text-left",
      className
    )}
    {...props}
  />
)
SheetHeader.displayName = "SheetHeader"

const SheetFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2",
      className
    )}
    {...props}
  />
)
SheetFooter.displayName = "SheetFooter"

const SheetTitle = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Title>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Title
    ref={ref}
    className={cn("text-lg font-semibold text-foreground", className)}
    {...props}
  />
))
SheetTitle.displayName = SheetPrimitive.Title.displayName

const SheetDescription = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Description>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Description
    ref={ref}
    className={cn("text-sm text-muted-foreground", className)}
    {...props}
  />
))
SheetDescription.displayName = SheetPrimitive.Description.displayName

export {
  Sheet,
  SheetPortal,
  SheetOverlay,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
}

