import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, ChevronLeft, ChevronDown, MoreHorizontal, Heart, Bookmark, List, Share, Radio, Headphones, Search, Layers, User } from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { getQueryFn } from '@/lib/queryClient';
import { useWebSocket } from '@/hooks/useWebSocket';

interface Track {
  id: string;
  title: string;
  artist: string;
  artwork: string;
  streamUrl: string;
  duration?: number;
}

interface Show {
  id: number;
  title: string;
  host: string;
  location: string;
  description: string;
  tags: string[];
  isLive: boolean;
  artwork: string;
  date: string;
  time: string;
  streamUrl?: string;
}

export default function MobileRadio() {
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [currentShow, setCurrentShow] = useState<Show | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [playerModal, setPlayerModal] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [activeNav, setActiveNav] = useState('live');

  const audioRef = useRef<HTMLAudioElement>(null);

  // API queries
  const { data: tracksData } = useQuery({
    queryKey: ['/api/tracks'],
    queryFn: getQueryFn({ on401: 'throw' })
  });

  const { data: showsData } = useQuery({
    queryKey: ['/api/shows/mobile'],
    queryFn: getQueryFn({ on401: 'throw' })
  });

  // WebSocket connection for real-time updates
  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  const wsUrl = `${protocol}//${window.location.host}/ws`;

  useWebSocket(wsUrl, {
    onMessage: (message) => {
      if (message.type === 'currentPlayback') {
        console.log('Current playback update:', message.data);
      }
    }
  });

  // Use API data when available, fallback to empty arrays
  const tracks = tracksData || [];
  const shows = showsData || [];

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const updateTime = () => setCurrentTime(audio.currentTime);
    const updateDuration = () => setDuration(audio.duration);
    const handleEnded = () => setIsPlaying(false);

    audio.addEventListener('timeupdate', updateTime);
    audio.addEventListener('loadedmetadata', updateDuration);
    audio.addEventListener('ended', handleEnded);

    return () => {
      audio.removeEventListener('timeupdate', updateTime);
      audio.removeEventListener('loadedmetadata', updateDuration);
      audio.removeEventListener('ended', handleEnded);
    };
  }, []);

  const togglePlayPause = () => {
    const audio = audioRef.current;
    if (!audio) return;

    if (isPlaying) {
      audio.pause();
    } else {
      audio.play();
    }
    setIsPlaying(!isPlaying);
  };

  const playTrack = (track: Track) => {
    setCurrentTrack(track);
    const audio = audioRef.current;
    if (audio) {
      audio.src = track.streamUrl;
      audio.play().then(() => {
        setIsPlaying(true);
      }).catch(error => {
        console.error('Error playing audio:', error);
      });
    }
  };

  const playShow = (show: Show) => {
    setCurrentShow(show);
    if (show.streamUrl) {
      const track: Track = {
        id: show.id.toString(),
        title: show.title,
        artist: show.host,
        artwork: show.artwork,
        streamUrl: show.streamUrl
      };
      playTrack(track);
    }
  };

  const openShowModal = (show: Show) => {
    setCurrentShow(show);
    setShowModal(true);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const progress = duration > 0 ? (currentTime / duration) * 100 : 0;

  const sampleTracklist = [
    { time: "0:00:20", artist: "Artist 1", title: "Track 1" },
    { time: "0:02:58", artist: "Artist 2", title: "Track 2" },
    { time: "0:06:10", artist: "Artist 3", title: "Track 3" },
    { time: "0:09:45", artist: "Artist 4", title: "Track 4" },
    { time: "0:13:20", artist: "Artist 5", title: "Track 5" }
  ];

  const relatedShows = [
    { 
      title: "Show 1", 
      location: "Location 1", 
      date: "5.3.2024", 
      tags: ["TAG1", "TAG2"],
      artwork: "https://images.unsplash.com/photo-1511379938547-c1f69419868d?w=60&h=60&fit=crop"
    },
    { 
      title: "Show 2", 
      location: "Location 2", 
      date: "22.3.2024", 
      tags: ["TAG3", "TAG4"],
      artwork: "https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=60&h=60&fit=crop"
    }
  ];

  const upNext = [
    { 
      title: "Next Show 1", 
      location: "Location 1", 
      date: "5.3.2024",
      artwork: "https://images.unsplash.com/photo-1511379938547-c1f69419868d?w=48&h=48&fit=crop"
    },
    { 
      title: "Next Show 2", 
      location: "Location 2", 
      date: "22.3.2024",
      artwork: "https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=48&h=48&fit=crop"
    }
  ];

  return (
    <div className="min-h-screen bg-black text-white relative overflow-hidden">
      {/* Audio Element */}
      <audio ref={audioRef} crossOrigin="anonymous" preload="metadata" />

      {/* Header */}
      <header className="sticky top-0 z-30 bg-black/90 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between p-4">
          <button className="p-2 -ml-2">
            <ChevronLeft className="w-6 h-6" />
          </button>
          <div className="text-center">
            <div className="text-sm font-bold">LIVE</div>
            <div className="text-xs text-white/60">RADIO</div>
          </div>
          <button className="p-2 -mr-2">
            <MoreHorizontal className="w-6 h-6" />
          </button>
        </div>
      </header>

      {/* Live Shows Feed */}
      <div className="p-4 space-y-4 pb-32">
        {shows.map((show) => (
          <div
            key={show.id}
            className="bg-white/5 rounded-lg overflow-hidden cursor-pointer active:scale-[0.98] transition-transform touch-manipulation"
            onClick={() => openShowModal(show)}
          >
            <div className="relative">
              <img 
                src={show.artwork} 
                alt={show.title} 
                className="w-full h-64 object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent" />

              {show.isLive && (
                <div className="absolute top-4 left-4 flex items-center space-x-2">
                  <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                  <span className="text-xs font-medium">LIVE</span>
                </div>
              )}

              <div className="absolute bottom-4 left-4 right-4">
                <div className="text-xs text-white/80 mb-1">{show.location}</div>
                <h3 className="text-lg font-bold mb-1">{show.title}</h3>
                <div className="text-xs text-white/80">{show.time}</div>
              </div>

              <button 
                className="absolute bottom-4 right-4 w-12 h-12 bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center"
                onClick={(e) => {
                  e.stopPropagation();
                  playShow(show);
                }}
              >
                <Play className="w-5 h-5 ml-0.5" />
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Show Detail Modal */}
      {showModal && currentShow && (
        <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm">
          <div className="flex flex-col h-full">
            {/* Modal Header */}
            <div className="flex items-center justify-between p-4 border-b border-white/10">
              <button onClick={() => setShowModal(false)} className="p-2 -ml-2">
                <ChevronLeft className="w-6 h-6" />
              </button>
              <div className="text-sm font-bold">EPISODE</div>
              <button className="p-2 -mr-2">
                <MoreHorizontal className="w-6 h-6" />
              </button>
            </div>

            {/* Show Info */}
            <div className="p-4 border-b border-white/10">
              <div className="text-xs text-white/60 mb-2">{currentShow.date}</div>
              <div className="text-xs text-white/60 mb-1">{currentShow.location}</div>
              <h2 className="text-xl font-bold mb-2">{currentShow.title}</h2>
              <div className="flex flex-wrap gap-2 mb-4">
                {currentShow.tags.map((tag) => (
                  <span key={tag} className="bg-transparent border border-white/30 px-3 py-1 rounded-full text-xs">
