          <h1 className="text-2xl font-bold mb-4">Episode Not Found</h1>
          <p className="text-gray-400">The episode you're looking for doesn't exist.</p>
        </div>
      </div>
    );
  }

  return <EpisodePlayer episode={episode} />;
}

