import { useQuery, useMutation } from '@tanstack/react-query';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/hooks/use-toast';
import { LogOut, Radio, Calendar, Key, Copy, Eye, EyeOff, PlayCircle, Info, Upload, FileAudio, Clock, CheckCircle, XCircle, CalendarCheck, Sparkles } from 'lucide-react';
import { useState } from 'react';
import { Link } from 'wouter';
import type { Resident, Schedule } from '@shared/schema';
import StreamingGuide from '@/components/StreamingGuide';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';

interface ResidentDashboardProps {
  onLogout: () => void;
  residentData: {
    id: number;
    username: string;
    displayName: string;
    showTitle: string | null;
  };
}

export default function ResidentDashboard({ onLogout, residentData }: ResidentDashboardProps) {
  const { toast } = useToast();
  const [showPassword, setShowPassword] = useState(false);

  // Fetch resident details
  const { data: resident, isLoading: residentLoading } = useQuery<Resident>({
    queryKey: [`/api/residents/${residentData.id}`],
  });

  // Fetch resident's schedule
  const { data: schedule = [], isLoading: scheduleLoading } = useQuery<Schedule[]>({
    queryKey: [`/api/schedule/resident/${residentData.id}`],
  });

  // Fetch resident's episode submissions
  interface EpisodeSubmission {
    id: number;
    title: string;
    seriesTitle?: string;
    episodeNumber?: number;
    status: string;
    submittedAt: string;
    rejectionReason?: string;
    scheduledAirDate?: string;
  }

  const { data: episodes = [], isLoading: episodesLoading } = useQuery<EpisodeSubmission[]>({
    queryKey: [`/api/resident/episodes?residentId=${residentData.id}`],
  });

  const logoutMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest('POST', '/api/resident/logout', {});
    },
    onSuccess: () => {
      onLogout();
    },
  });

  const goLiveMutation = useMutation({
    mutationFn: async ({ scheduleId, status }: { scheduleId: number; status: string }) => {
      return await apiRequest('POST', '/api/resident/live-status', { scheduleId, status });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`/api/schedule/resident/${residentData.id}`] });
      toast({
        title: "Status Updated",
        description: "Your live status has been updated.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error?.message || "Failed to update live status.",
        variant: "destructive",
      });
    },
  });

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    toast({
      title: "Copied!",
      description: `${label} copied to clipboard.`,
    });
  };

  // Find current or next show
  const now = new Date();

  // Current live show = any show marked as live
  const currentLiveShow = schedule.find(s => s.liveStatus === 'live');

  // Active slot = most recent show that has started and isn't completed
  // This is the show the resident should control, regardless of how long ago it started
  const activeSlot = schedule
    .filter(s => new Date(s.scheduledAt) <= now && s.liveStatus !== 'completed')
    .sort((a, b) => new Date(b.scheduledAt).getTime() - new Date(a.scheduledAt).getTime())[0];

  // Next upcoming show = future shows within 4 hours
  const fourHoursFromNow = new Date(now.getTime() + 4 * 60 * 60 * 1000);
  const nextUpcomingShow = schedule
    .filter(s => {
      const showTime = new Date(s.scheduledAt);
      return showTime > now && 
             showTime <= fourHoursFromNow && 
             s.liveStatus !== 'completed';
    })
    .sort((a, b) => new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime())[0];

  // The show to control = active slot (if exists and not already live elsewhere) OR next upcoming
  const showToControl = (activeSlot && !currentLiveShow) ? activeSlot : 
                        currentLiveShow ? currentLiveShow : 
                        nextUpcomingShow;

  const upcomingShows = schedule
    .filter(s => new Date(s.scheduledAt) > now && s.liveStatus !== 'completed')
    .sort((a, b) => new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime())
    .slice(0, 5);

  const handleGoLive = () => {
    if (!showToControl) {
      toast({
        title: "No Show Available",
        description: "You don't have any active or upcoming shows within the next 4 hours.",
        variant: "destructive",
      });
      return;
    }

    // Toggle: if this show is live, go offline; otherwise go live
    const newStatus = showToControl.liveStatus === 'live' ? 'offline' : 'live';
    goLiveMutation.mutate({ scheduleId: showToControl.id, status: newStatus });
  };

  const handleCompleteShow = () => {
    if (!activeSlot) return;

    if (confirm(`Mark "${activeSlot.title}" as completed? This will allow you to go live for your next show.`)) {
      goLiveMutation.mutate({ scheduleId: activeSlot.id, status: 'completed' });
    }
  };

  return (
    <div className="min-h-screen bg-[#FEFCF9]">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-navy rounded-full flex items-center justify-center">
                <Radio className="w-4 h-4 text-white" />
              </div>
              <div>
                <h1 className="text-lg font-mono font-bold">Resident Portal</h1>
                <p className="text-xs text-gray-500">{residentData.displayName}</p>
              </div>
            </div>
            <Button
              variant="outline"
              onClick={() => logoutMutation.mutate()}
              disabled={logoutMutation.isPending}
              data-testid="button-logout"
            >
              <LogOut className="w-4 h-4 mr-2" />
              Logout
            </Button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Streaming Credentials */}
          <Card data-testid="card-streaming-credentials">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Key className="w-5 h-5" />
                Streaming Credentials
              </CardTitle>
              <CardDescription>
                Use these credentials to connect your streaming software (BUTT, Mixxx, etc.)
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {residentLoading ? (
                <div className="text-center py-4">
                  <div className="w-6 h-6 border-2 border-navy border-t-transparent rounded-full animate-spin mx-auto"></div>
                </div>
              ) : resident ? (
                <>
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-700">AzuraCast Username</label>
                    <div className="flex gap-2">
                      <code className="flex-1 px-3 py-2 bg-gray-100 rounded border text-sm font-mono" data-testid="text-azuracast-username">
                        {resident.azuracastUsername || 'Not configured'}
                      </code>
                      {resident.azuracastUsername && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => copyToClipboard(resident.azuracastUsername!, 'Username')}
                          data-testid="button-copy-username"
                        >
                          <Copy className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-700">AzuraCast Password</label>
                    <div className="flex gap-2">
                      <code className="flex-1 px-3 py-2 bg-gray-100 rounded border text-sm font-mono" data-testid="text-azuracast-password">
                        {resident.azuracastPassword 
                          ? showPassword 
                            ? resident.azuracastPassword 
                            : '••••••••••'
                          : 'Not configured'
                        }
                      </code>
                      {resident.azuracastPassword && (
                        <>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => setShowPassword(!showPassword)}
                            data-testid="button-toggle-password"
                          >
                            {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => copyToClipboard(resident.azuracastPassword!, 'Password')}
                            data-testid="button-copy-password"
                          >
                            <Copy className="w-4 h-4" />
                          </Button>
                        </>
                      )}
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium text-gray-700">Mount Point</label>
                    <div className="flex gap-2">
                      <code className="flex-1 px-3 py-2 bg-gray-100 rounded border text-sm font-mono" data-testid="text-mount-point">
                        {resident.mountPoint || 'Not configured'}
                      </code>
                      {resident.mountPoint && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => copyToClipboard(resident.mountPoint!, 'Mount Point')}
                          data-testid="button-copy-mountpoint"
                        >
                          <Copy className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  </div>

                  {resident.canGoLive && resident.azuracastUsername && resident.azuracastPassword && resident.mountPoint && (
                    <div className="space-y-3">
                      <StreamingGuide 
                        credentials={{
                          azuracastUsername: resident.azuracastUsername,
                          azuracastPassword: resident.azuracastPassword,
                          mountPoint: resident.mountPoint
                        }}
                      />

                      <Alert className="bg-blue-50 border-blue-200">
                        <Info className="h-4 w-4 text-blue-600" />
                        <AlertTitle className="text-blue-800">How to Go Live</AlertTitle>
                        <AlertDescription className="text-blue-700 text-sm">
                          The "Go Live" button only updates your status in this portal. To actually broadcast, you must connect BUTT/Mixxx using your credentials above. 
                          When you connect, the playlist will automatically stop and your stream will take over. When you disconnect, the playlist resumes.
                        </AlertDescription>
                      </Alert>

                      {showToControl && (
                        <div className="p-3 bg-gray-100 rounded-lg text-sm">
                          <p className="font-medium">
                            {showToControl.liveStatus === 'live' ? 'Currently Live:' : 
                             activeSlot === showToControl ? 'Active Slot:' : 
                             'Next Show:'}
                          </p>
                          <p className="text-gray-600">{showToControl.title}</p>
                          <p className="text-xs text-gray-500 mt-1">
                            {new Date(showToControl.scheduledAt).toLocaleString()}
                          </p>
                        </div>
                      )}
                      <div className="flex gap-2">
                        <Button 
                          className="flex-1" 
                          size="lg" 
                          onClick={handleGoLive}
                          disabled={goLiveMutation.isPending || !showToControl}
                          variant={showToControl?.liveStatus === 'live' ? 'destructive' : 'default'}
                          data-testid="button-go-live"
                        >
                          <PlayCircle className="w-5 h-5 mr-2" />
                          {showToControl?.liveStatus === 'live' ? 'Go Offline' : 'Go Live'}
                        </Button>
                        {activeSlot && activeSlot.liveStatus !== 'live' && (
                          <Button 
                            variant="outline" 
                            size="lg"
                            onClick={handleCompleteShow}
                            disabled={goLiveMutation.isPending}
                            data-testid="button-complete-show"
                          >
                            Complete
                          </Button>
                        )}
                      </div>
                    </div>
                  )}
                </>
              ) : (
                <p className="text-sm text-gray-500">Unable to load credentials</p>
              )}
            </CardContent>
          </Card>

          {/* Show Information */}
          <Card data-testid="card-show-info">
            <CardHeader>
              <CardTitle>Your Show</CardTitle>
              <CardDescription>Show details and information</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {residentLoading ? (
                <div className="text-center py-4">
                  <div className="w-6 h-6 border-2 border-navy border-t-transparent rounded-full animate-spin mx-auto"></div>
                </div>
              ) : resident ? (
                <>
                  <div>
                    <label className="text-sm font-medium text-gray-700">Show Title</label>
                    <p className="text-lg font-semibold mt-1" data-testid="text-show-title">
                      {resident.showTitle || 'Not configured'}
                    </p>
                  </div>
                  {resident.showDescription && (
                    <div>
                      <label className="text-sm font-medium text-gray-700">Description</label>
                      <p className="text-sm text-gray-600 mt-1" data-testid="text-show-description">
                        {resident.showDescription}
                      </p>
                    </div>
                  )}
                  {resident.genres && (
                    <div>
                      <label className="text-sm font-medium text-gray-700">Genres</label>
                      <div className="flex flex-wrap gap-2 mt-2">
                        {resident.genres.map((genre, i) => (
                          <Badge key={i} variant="secondary">{genre}</Badge>
                        ))}
                      </div>
                    </div>
                  )}
                  <div>
                    <label className="text-sm font-medium text-gray-700">Status</label>
                    <div className="mt-1">
                      <Badge variant={resident.isActive ? 'default' : 'secondary'} data-testid="badge-status">
                        {resident.isActive ? 'Active' : 'Inactive'}
                      </Badge>
                    </div>
                  </div>
                </>
              ) : (
                <p className="text-sm text-gray-500">Unable to load show information</p>
              )}
            </CardContent>
          </Card>

          {/* Submit Episode */}
          <Card data-testid="card-submit-episode" className="bg-gradient-to-br from-red-50 to-white border-red-200">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-red-600">
                <Upload className="w-5 h-5" />
                Submit Pre-Recorded Episode
              </CardTitle>
              <CardDescription>
                Upload your pre-recorded episodes for review and scheduling
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                <p className="text-sm text-gray-600">
                  Record your episode using Audacity or your preferred audio software, then submit it here for editorial review and scheduling.
                </p>
                <Button asChild className="w-full" size="lg" data-testid="button-submit-episode">
                  <Link href="/resident/submit-episode">
                    <Upload className="w-4 h-4 mr-2" />
                    Submit New Episode
                  </Link>
                </Button>
                <Link href="/resident/recording-guide">
                  <button className="w-full text-sm text-blue-600 hover:text-blue-800 hover:underline font-medium" data-testid="link-recording-guide">
                    📚 New to recording? Read our step-by-step Audacity guide →
                  </button>
                </Link>
              </div>
            </CardContent>
          </Card>

          {/* My Episodes */}
          <Card className="lg:col-span-2" data-testid="card-my-episodes">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <FileAudio className="w-5 h-5" />
                My Episode Submissions
              </CardTitle>
              <CardDescription>Track your submitted episodes and their status</CardDescription>
            </CardHeader>
            <CardContent>
              {episodesLoading ? (
                <div className="text-center py-8">
                  <div className="w-6 h-6 border-2 border-navy border-t-transparent rounded-full animate-spin mx-auto"></div>
                </div>
              ) : episodes.length > 0 ? (
                <div className="space-y-3">
                  {episodes.slice(0, 5).map((episode) => (
                    <div
                      key={episode.id}
                      className="flex items-start justify-between p-4 border rounded-lg hover:bg-gray-50"
                      data-testid={`episode-item-${episode.id}`}
                    >
                      <div className="flex-1">
                        <h4 className="font-medium">{episode.title}</h4>
                        {episode.seriesTitle && (
                          <p className="text-xs text-gray-500">{episode.seriesTitle} {episode.episodeNumber && `#${episode.episodeNumber}`}</p>
                        )}
                        <p className="text-sm text-gray-600 mt-1">
                          Submitted {new Date(episode.submittedAt).toLocaleDateString('en-US', {
                            year: 'numeric',
                            month: 'short',
                            day: 'numeric',
                          })}
                        </p>
                        {episode.status === 'rejected' && episode.rejectionReason && (
                          <p className="text-sm text-red-600 mt-2">
                            <strong>Feedback:</strong> {episode.rejectionReason}
                          </p>
                        )}
                        {episode.status === 'scheduled' && episode.scheduledAirDate && (
                          <p className="text-sm text-green-600 mt-2">
                            <strong>Air Date:</strong> {new Date(episode.scheduledAirDate).toLocaleDateString('en-US', {
                              year: 'numeric',
                              month: 'long',
                              day: 'numeric',
                              hour: 'numeric',
                              minute: '2-digit',
                            })}
                          </p>
                        )}
                      </div>
                      <div className="ml-4 flex items-center gap-2">
                        <Badge 
                          variant={
                            episode.status === 'approved' ? 'default' :
                            episode.status === 'scheduled' ? 'default' :
                            episode.status === 'rejected' ? 'destructive' :
                            episode.status === 'aired' ? 'secondary' :
                            'outline'
                          }
                          className="flex items-center gap-1"
                          data-testid={`badge-status-${episode.id}`}
                        >
                          {episode.status === 'pending' && <Clock className="w-3 h-3" />}
                          {episode.status === 'approved' && <CheckCircle className="w-3 h-3" />}
                          {episode.status === 'rejected' && <XCircle className="w-3 h-3" />}
                          {episode.status === 'scheduled' && <CalendarCheck className="w-3 h-3" />}
                          {episode.status === 'aired' && <Sparkles className="w-3 h-3" />}
                          {episode.status.charAt(0).toUpperCase() + episode.status.slice(1)}
                        </Badge>
                      </div>
                    </div>
                  ))}
                  {episodes.length > 5 && (
                    <p className="text-center text-sm text-gray-500 pt-2">
                      Showing 5 of {episodes.length} episodes
                    </p>
                  )}
                </div>
              ) : (
                <div className="text-center py-8">
                  <FileAudio className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                  <p className="text-gray-500 mb-4">No episodes submitted yet</p>
                  <Button asChild variant="outline" data-testid="button-submit-first-episode">
                    <Link href="/resident/submit-episode">
                      <Upload className="w-4 h-4 mr-2" />
                      Submit Your First Episode
                    </Link>
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Upcoming Schedule */}
          <Card className="lg:col-span-2" data-testid="card-schedule">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Calendar className="w-5 h-5" />
                Upcoming Shows
              </CardTitle>
              <CardDescription>Your scheduled time slots</CardDescription>
            </CardHeader>
            <CardContent>
              {scheduleLoading ? (
                <div className="text-center py-8">
                  <div className="w-6 h-6 border-2 border-navy border-t-transparent rounded-full animate-spin mx-auto"></div>
                </div>
              ) : upcomingShows.length > 0 ? (
                <div className="space-y-3">
                  {upcomingShows.map((show) => (
                    <div
                      key={show.id}
                      className="flex items-center justify-between p-4 border rounded-lg hover:bg-gray-50"
                      data-testid={`schedule-item-${show.id}`}
                    >
                      <div className="flex-1">
                        <h4 className="font-medium">{show.title}</h4>
                        <p className="text-sm text-gray-600">
                          {new Date(show.scheduledAt).toLocaleString('en-US', {
                            weekday: 'long',
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric',
                            hour: 'numeric',
                            minute: '2-digit',
                          })}
                        </p>
                      </div>
                      <Badge variant={show.liveStatus === 'live' ? 'destructive' : 'secondary'}>
                        {show.liveStatus || 'scheduled'}
                      </Badge>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-center text-gray-500 py-8">No upcoming shows scheduled</p>
              )}
            </CardContent>
          </Card>
        </div>
      </main>
    </div>
  );
}

client/src/pages/AdminResidents.tsx.content:
import { useQuery, useMutation } from '@tanstack/react-query';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Switch } from '@/components/ui/switch';
import { useToast } from '@/hooks/use-toast';
import { Plus, Edit, Trash2, User, Key, Radio, AlertTriangle, Copy, ExternalLink } from 'lucide-react';
import { useState } from 'react';
import type { Resident } from '@shared/schema';
import { useForm } from 'react-hook-form';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Textarea } from '@/components/ui/textarea';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import AdminShell from '@/components/admin/AdminShell';

interface ResidentFormData {
  username: string;
  password: string;
  displayName: string;
  email?: string;
  bio?: string;
  showTitle?: string;
  showDescription?: string;
  azuracastUsername?: string;
  azuracastPassword?: string;
  mountPoint?: string;
  isActive: boolean;
  canGoLive: boolean;
}

interface AdminResidentsProps {
  onLogout?: () => void;
  currentUser?: string;
}

export default function AdminResidents({ onLogout, currentUser = "admin" }: AdminResidentsProps) {
  const { toast } = useToast();
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [editingResident, setEditingResident] = useState<Resident | null>(null);
  const [copiedId, setCopiedId] = useState<number | null>(null);

  const { data: residents = [], isLoading } = useQuery<Resident[]>({
    queryKey: ['/api/admin/residents'],
  });

  const form = useForm<ResidentFormData>({
    defaultValues: {
      username: '',
      password: '',
      displayName: '',
      email: '',
      bio: '',
      showTitle: '',
      showDescription: '',
      azuracastUsername: '',
      azuracastPassword: '',
      mountPoint: '',
      isActive: true,
      canGoLive: true,
    },
  });

  const createMutation = useMutation({
    mutationFn: async (data: ResidentFormData) => {
      return await apiRequest('POST', '/api/admin/residents', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/residents'] });
      toast({
        title: "Resident Created",
        description: "New resident has been added successfully.",
      });
      setIsCreateOpen(false);
      form.reset();
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error?.message || "Failed to create resident.",
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: number; data: Partial<ResidentFormData> }) => {
      return await apiRequest('PATCH', `/api/admin/residents/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/residents'] });
      toast({
        title: "Resident Updated",
        description: "Resident details have been updated successfully.",
      });
      setEditingResident(null);
      form.reset();
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error?.message || "Failed to update resident.",
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      return await apiRequest('DELETE', `/api/admin/residents/${id}`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/residents'] });
      toast({
        title: "Resident Deleted",
        description: "Resident has been removed successfully.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error?.message || "Failed to delete resident.",
        variant: "destructive",
      });
    },
  });

  const handleEdit = (resident: Resident) => {
    setEditingResident(resident);
    form.reset({
      username: resident.username,
      password: '', // Don't pre-fill password
      displayName: resident.displayName,
      email: resident.email || '',
      bio: resident.bio || '',
      showTitle: resident.showTitle || '',
      showDescription: resident.showDescription || '',
      azuracastUsername: resident.azuracastUsername || '',
      azuracastPassword: resident.azuracastPassword || '',
      mountPoint: resident.mountPoint || '',
      isActive: resident.isActive ?? true,
      canGoLive: resident.canGoLive ?? true,
    });
  };

  const onSubmit = (data: ResidentFormData) => {
    if (editingResident) {
      // Don't send password if it's empty (no change)
      const updateData = { ...data };
      if (!updateData.password) {
        delete (updateData as any).password;
      }
      updateMutation.mutate({ id: editingResident.id, data: updateData });
    } else {
      createMutation.mutate(data);
    }
  };

  const copyToAzuraCast = (resident: Resident) => {
    if (!resident.azuracastUsername || !resident.azuracastPassword) {
      toast({
        title: "Missing Credentials",
        description: "This resident doesn't have AzuraCast credentials set up.",
        variant: "destructive",
      });
      return;
    }

    // Pre-formatted data for easy copying
    const credentials = `AZURACAST STREAMER ACCOUNT
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Streamer/DJ Username: ${resident.azuracastUsername}
Streamer/DJ Password: ${resident.azuracastPassword}
Display Name: ${resident.displayName}
Comments: ${resident.showTitle || 'Resident DJ'}

INSTRUCTIONS:
1. Go to AzuraCast → Station → Streamers/DJs
2. Click "Add Streamer/DJ Account"
3. Copy the credentials above and paste into the form
4. Save the account
━━━━━━━━━━━━━━━━━━━━━━━━━━━━`;

    navigator.clipboard.writeText(credentials).then(() => {
      // Visual feedback: change button state
      setCopiedId(resident.id);
      setTimeout(() => setCopiedId(null), 3000);

      toast({
        title: "✅ Copied to Clipboard!",
        description: "Paste these credentials into AzuraCast to complete setup.",
        duration: 5000,
      });
    }).catch(() => {
      toast({
        title: "Copy Failed",
        description: "Please manually copy the credentials from the resident details.",
        variant: "destructive",
      });
    });
  };

  return (
    <AdminShell
      title="Residents"
      subtitle="Manage resident DJs and streamers"
      breadcrumbs={[{ label: "Residents" }]}
      currentUser={currentUser}
      userRole="admin"
      onLogout={onLogout}
      actions={
        <>
          <a
            href="http://24.199.109.18/admin#/station/1/streamers"
            target="_blank"
            rel="noopener noreferrer"
            className="text-sm text-gray-500 hover:text-gray-700 flex items-center gap-1"
          >
            <ExternalLink className="w-3 h-3" />
            AzuraCast
          </a>
          <Button onClick={() => setIsCreateOpen(true)} data-testid="button-create-resident">
            <Plus className="w-4 h-4 mr-2" />
            Add Resident
          </Button>
        </>
      }
    >
      <Dialog open={isCreateOpen || !!editingResident} onOpenChange={(open) => {
        setIsCreateOpen(open);
        if (!open) {
          setEditingResident(null);
          form.reset();
        }
      }}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
              <DialogHeader>
                <DialogTitle>{editingResident ? 'Edit Resident' : 'Create New Resident'}</DialogTitle>
                <DialogDescription>
                  {editingResident ? 'Update resident details and streaming credentials.' : 'Add a new resident DJ to the platform.'}
                </DialogDescription>
              </DialogHeader>
              <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="username"
                      rules={{ required: 'Username is required' }}
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Username*</FormLabel>
                          <FormControl>
                            <Input {...field} placeholder="resident_username" data-testid="input-username" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="password"
                      rules={editingResident ? {} : { required: 'Password is required' }}
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Password{editingResident ? '' : '*'}</FormLabel>
                          <FormControl>
                            <Input {...field} type="password" placeholder={editingResident ? 'Leave blank to keep current' : 'Enter password'} data-testid="input-password" />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>

                  <FormField
                    control={form.control}
                    name="displayName"
                    rules={{ required: 'Display name is required' }}
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Display Name*</FormLabel>
                        <FormControl>
                          <Input {...field} placeholder="DJ Name" data-testid="input-displayname" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="email"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Email</FormLabel>
                        <FormControl>
                          <Input {...field} type="email" placeholder="dj@example.com" data-testid="input-email" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="showTitle"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Show Title</FormLabel>
                        <FormControl>
                          <Input {...field} placeholder="The Radio Show" data-testid="input-show-title" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="showDescription"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Show Description</FormLabel>
                        <FormControl>
                          <Textarea {...field} placeholder="Description of the show..." rows={3} data-testid="textarea-show-description" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <div className="border-t pt-4 mt-4">
                    <h3 className="font-semibold mb-3 flex items-center gap-2">
                      <Key className="w-4 h-4" />
                      AzuraCast Streaming Credentials
                    </h3>
                    <div className="grid grid-cols-1 gap-4">
                      <FormField
                        control={form.control}
                        name="azuracastUsername"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>AzuraCast Username</FormLabel>
                            <FormControl>
                              <Input {...field} placeholder="streamer_username" data-testid="input-azuracast-username" />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name="azuracastPassword"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>AzuraCast Password</FormLabel>
                            <FormControl>
                              <Input {...field} type="password" placeholder="streaming_password" data-testid="input-azuracast-password" />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name="mountPoint"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Mount Point</FormLabel>
                            <FormControl>
                              <Input {...field} placeholder="/live" data-testid="input-mount-point" />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </div>

                  <Alert className="bg-yellow-50 border-yellow-200">
                    <AlertTriangle className="h-4 w-4 text-yellow-600" />
                    <AlertTitle className="text-yellow-800">Important: Playlist Interruption</AlertTitle>
                    <AlertDescription className="text-yellow-700 text-sm">
                      When residents connect to AzuraCast via BUTT/Mixxx, the scheduled playlist will automatically stop and their live stream will take over. 
                      The playlist resumes when they disconnect. The "Go Live" button only updates internal status - actual broadcasting happens when they connect via streaming software.
                    </AlertDescription>
                  </Alert>

                  <Alert className="bg-blue-50 border-blue-200">
                    <Radio className="h-4 w-4 text-blue-600" />
                    <AlertTitle className="text-blue-800">AzuraCast Setup - One-Click Copy</AlertTitle>
                    <AlertDescription className="text-blue-700 text-sm">
                      After creating a resident, click the "Copy to AzuraCast" button to copy pre-formatted credentials. 
                      Then paste them into AzuraCast → Streamers/DJs → Add Streamer. Takes 10 seconds! 
                      Residents will see their credentials in their dashboard and can stream immediately.
                    </AlertDescription>
                  </Alert>

                  <div className="border-t pt-4 mt-4 space-y-3">
                    <FormField
                      control={form.control}
                      name="isActive"
                      render={({ field }) => (
                        <FormItem className="flex items-center justify-between">
                          <FormLabel>Active Account</FormLabel>
                          <FormControl>
                            <Switch checked={field.value} onCheckedChange={field.onChange} data-testid="switch-is-active" />
                          </FormControl>
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="canGoLive"
                      render={({ field }) => (
                        <FormItem className="flex items-center justify-between">
                          <FormLabel>Can Go Live</FormLabel>
                          <FormControl>
                            <Switch checked={field.value} onCheckedChange={field.onChange} data-testid="switch-can-go-live" />
                          </FormControl>
                        </FormItem>
                      )}
                    />
                  </div>

                  <DialogFooter>
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => {
                        setIsCreateOpen(false);
                        setEditingResident(null);
                        form.reset();
                      }}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      disabled={createMutation.isPending || updateMutation.isPending}
                      data-testid="button-submit-resident"
                    >
                      {editingResident ? 'Update' : 'Create'} Resident
                    </Button>
                  </DialogFooter>
                </form>
              </Form>
            </DialogContent>
      </Dialog>

      {/* Residents List */}
      <Card className="bg-white border border-gray-200">
          <CardHeader>
            <CardTitle>All Residents ({residents.length})</CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="text-center py-8">
                <div className="w-6 h-6 border-2 border-navy border-t-transparent rounded-full animate-spin mx-auto"></div>
