import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Link } from "wouter";
import { Upload, ArrowLeft, CheckCircle2, AlertCircle, FileAudio } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  FormDescription,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { useToast } from "@/hooks/use-toast";

const episodeSchema = z.object({
  residentId: z.string().optional(),
  residentName: z.string().min(1, "Your name is required"),
  title: z.string().min(1, "Episode title is required"),
  genre: z.string().min(1, "Genre is required"),
  description: z.string().optional(),
  showNotes: z.string().optional(),
  seriesTitle: z.string().optional(),
  episodeNumber: z.string().optional(),
  tags: z.string().optional(),
  coverArtUrl: z.string().url("Must be a valid URL").optional().or(z.literal("")),
});

type EpisodeFormData = z.infer<typeof episodeSchema>;

export default function ResidentEpisodeSubmit() {
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadSuccess, setUploadSuccess] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const { toast } = useToast();

  const form = useForm<EpisodeFormData>({
    resolver: zodResolver(episodeSchema),
    defaultValues: {
      residentId: "",
      residentName: "",
      title: "",
      genre: "",
      description: "",
      showNotes: "",
      seriesTitle: "",
      episodeNumber: "",
      tags: "",
      coverArtUrl: "",
    },
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('audio/') && !file.name.endsWith('.mp3')) {
        toast({
          title: "Invalid file type",
          description: "Please upload an MP3 audio file",
          variant: "destructive",
        });
        return;
      }

      if (file.size > 500 * 1024 * 1024) {
        toast({
          title: "File too large",
          description: "Maximum file size is 500MB",
          variant: "destructive",
        });
        return;
      }

      setAudioFile(file);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files?.[0];
    if (file) {
      if (!file.type.startsWith('audio/') && !file.name.endsWith('.mp3')) {
        toast({
          title: "Invalid file type",
          description: "Please upload an MP3 audio file",
          variant: "destructive",
        });
        return;
      }

      if (file.size > 500 * 1024 * 1024) {
        toast({
          title: "File too large",
          description: "Maximum file size is 500MB",
          variant: "destructive",
        });
        return;
      }

      setAudioFile(file);
    }
  };

  const onSubmit = async (data: EpisodeFormData) => {
    if (!audioFile) {
      toast({
        title: "Missing audio file",
        description: "Please upload an MP3 file for your episode",
        variant: "destructive",
      });
      return;
    }

    setIsUploading(true);
    setUploadProgress(0);

    try {
      const formData = new FormData();
      formData.append('audioFile', audioFile);
      formData.append('residentId', data.residentId || '');
      formData.append('residentName', data.residentName);
      formData.append('title', data.title);
      formData.append('genre', data.genre);
      if (data.description) formData.append('description', data.description);
      if (data.showNotes) formData.append('showNotes', data.showNotes);
      if (data.seriesTitle) formData.append('seriesTitle', data.seriesTitle);
      if (data.episodeNumber) formData.append('episodeNumber', data.episodeNumber);
      if (data.tags) formData.append('tags', data.tags);
      if (data.coverArtUrl) formData.append('coverArtUrl', data.coverArtUrl);

      const xhr = new XMLHttpRequest();

      xhr.upload.addEventListener('progress', (e) => {
        if (e.lengthComputable) {
          const percent = Math.round((e.loaded / e.total) * 100);
          setUploadProgress(percent);
        }
      });

      const response = await new Promise<any>((resolve, reject) => {
        xhr.onload = () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            resolve(JSON.parse(xhr.responseText));
          } else {
            reject(new Error(`Upload failed: ${xhr.statusText}`));
          }
        };
        xhr.onerror = () => reject(new Error('Network error'));
        xhr.open('POST', '/api/resident/episode/submit');
        xhr.send(formData);
      });

      if (response.success) {
        setUploadSuccess(true);
        toast({
          title: "Episode submitted!",
          description: "Your episode has been submitted for review. We'll notify you when it's approved.",
        });

        // Reset form
        form.reset();
        setAudioFile(null);
      }
    } catch (error) {
      console.error('Upload error:', error);
      toast({
        title: "Upload failed",
        description: error instanceof Error ? error.message : "Failed to upload episode. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsUploading(false);
      setUploadProgress(0);
    }
  };

  if (uploadSuccess) {
    return (
      <div className="min-h-screen bg-black pt-16 pb-8 px-4">
        <div className="max-w-2xl mx-auto">
          <Card className="bg-zinc-900 border-zinc-800">
            <CardContent className="pt-6">
              <div className="text-center space-y-4">
                <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center mx-auto">
                  <CheckCircle2 className="w-8 h-8 text-green-500" />
                </div>
                <h2 className="text-2xl font-bold text-white">Episode Submitted!</h2>
                <p className="text-zinc-400">
                  Your episode has been submitted for review. Our team will review it and you'll receive a notification once it's approved.
                </p>
                <div className="flex gap-4 justify-center pt-4">
                  <Button
                    onClick={() => setUploadSuccess(false)}
                    variant="outline"
                    className="border-zinc-700 hover:bg-zinc-800"
                    data-testid="button-submit-another"
                  >
                    Submit Another
                  </Button>
                  <Link href="/resident">
                    <Button className="bg-navy-dark hover:bg-red-700" data-testid="link-dashboard">
                      Go to Dashboard
                    </Button>
                  </Link>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black pt-16 pb-8 px-4">
      <div className="max-w-4xl mx-auto">
        <Link href="/resident">
          <Button
            variant="ghost"
            className="mb-6 text-zinc-400 hover:text-white hover:bg-zinc-900"
            data-testid="link-back"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Dashboard
          </Button>
        </Link>

        <div className="mb-8">
          <h1 className="text-4xl font-bold text-white mb-2">Submit Your Episode</h1>
          <p className="text-zinc-400">
            Upload your pre-recorded episode for admin review and scheduling
          </p>
        </div>

        <Card className="bg-zinc-900 border-zinc-800">
          <CardHeader>
            <CardTitle className="text-white">Episode Details</CardTitle>
            <CardDescription className="text-zinc-400">
              Fill in the details for your episode and upload your audio file
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                {/* Audio File Upload */}
                <div className="space-y-2">
                  <label className="text-sm font-medium text-white">
                    Audio File <span className="text-navy">*</span>
                  </label>
                  <div
                    className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
                      isDragging
                        ? 'border-navy bg-navy/10'
                        : 'border-zinc-700 hover:border-zinc-600'
                    } ${audioFile ? 'bg-zinc-800/50' : ''}`}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                  >
                    {audioFile ? (
                      <div className="space-y-2">
                        <FileAudio className="w-12 h-12 text-green-500 mx-auto" />
                        <p className="text-white font-medium">{audioFile.name}</p>
                        <p className="text-sm text-zinc-400">
                          {(audioFile.size / (1024 * 1024)).toFixed(2)} MB
                        </p>
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
                          onClick={() => setAudioFile(null)}
                          className="border-zinc-700 hover:bg-zinc-800 mt-2"
                          data-testid="button-remove-file"
                        >
                          Remove File
                        </Button>
                      </div>
                    ) : (
                      <>
                        <Upload className="w-12 h-12 text-zinc-500 mx-auto mb-4" />
                        <p className="text-white mb-2">
                          Drag and drop your MP3 file here, or click to browse
                        </p>
                        <p className="text-sm text-zinc-500">
                          Maximum file size: 500MB
                        </p>
                        <input
                          type="file"
                          accept="audio/mpeg,audio/mp3,.mp3"
                          onChange={handleFileChange}
                          className="hidden"
                          id="audio-upload"
                          data-testid="input-audio-file"
                        />
                        <label htmlFor="audio-upload">
                          <Button
                            type="button"
                            variant="outline"
                            className="mt-4 border-zinc-700 hover:bg-zinc-800"
                            asChild
                          >
                            <span>Browse Files</span>
                          </Button>
                        </label>
                      </>
                    )}
                  </div>
                </div>

                {/* Resident Name */}
                <FormField
                  control={form.control}
                  name="residentName"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">
                        Your Name <span className="text-navy">*</span>
                      </FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          placeholder="DJ Name / Artist Name"
                          className="bg-zinc-800 border-zinc-700 text-white"
                          data-testid="input-resident-name"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Episode Title */}
                <FormField
                  control={form.control}
                  name="title"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">
                        Episode Title <span className="text-navy">*</span>
                      </FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          placeholder="e.g., Late Night Sessions #12"
                          className="bg-zinc-800 border-zinc-700 text-white"
                          data-testid="input-title"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Genre */}
                <FormField
                  control={form.control}
                  name="genre"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">
                        Genre <span className="text-navy">*</span>
                      </FormLabel>
                      <Select onValueChange={field.onChange} defaultValue={field.value}>
                        <FormControl>
                          <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white" data-testid="select-genre">
                            <SelectValue placeholder="Select a genre" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="House">House</SelectItem>
                          <SelectItem value="Techno">Techno</SelectItem>
                          <SelectItem value="Hip Hop">Hip Hop</SelectItem>
                          <SelectItem value="R&B">R&B</SelectItem>
                          <SelectItem value="Electronic">Electronic</SelectItem>
                          <SelectItem value="Jazz">Jazz</SelectItem>
                          <SelectItem value="Funk">Funk</SelectItem>
                          <SelectItem value="Soul">Soul</SelectItem>
                          <SelectItem value="Disco">Disco</SelectItem>
                          <SelectItem value="Ambient">Ambient</SelectItem>
                          <SelectItem value="Experimental">Experimental</SelectItem>
                          <SelectItem value="Mixed">Mixed</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Series Title */}
                <FormField
                  control={form.control}
                  name="seriesTitle"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">Series Title (Optional)</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          placeholder="e.g., Late Night Sessions"
                          className="bg-zinc-800 border-zinc-700 text-white"
                          data-testid="input-series-title"
                        />
                      </FormControl>
                      <FormDescription className="text-zinc-500">
                        If this episode is part of a series
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Episode Number */}
                <FormField
                  control={form.control}
                  name="episodeNumber"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">Episode Number (Optional)</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          type="number"
                          placeholder="e.g., 12"
                          className="bg-zinc-800 border-zinc-700 text-white"
                          data-testid="input-episode-number"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Description */}
                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">Description (Optional)</FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          placeholder="Brief description of your episode..."
                          className="bg-zinc-800 border-zinc-700 text-white min-h-[80px]"
                          data-testid="textarea-description"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Show Notes */}
                <FormField
                  control={form.control}
                  name="showNotes"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">Show Notes / Tracklist (Optional)</FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          placeholder="Full tracklist, timestamps, links, etc..."
                          className="bg-zinc-800 border-zinc-700 text-white min-h-[120px]"
                          data-testid="textarea-show-notes"
                        />
                      </FormControl>
                      <FormDescription className="text-zinc-500">
                        Include full tracklist, timestamps, or any additional notes
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Tags */}
                <FormField
                  control={form.control}
                  name="tags"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">Tags (Optional)</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          placeholder="e.g., deep house, melodic, sunset vibes"
                          className="bg-zinc-800 border-zinc-700 text-white"
                          data-testid="input-tags"
                        />
                      </FormControl>
                      <FormDescription className="text-zinc-500">
                        Separate tags with commas
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Cover Art URL */}
                <FormField
                  control={form.control}
                  name="coverArtUrl"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-white">Cover Art URL (Optional)</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          type="url"
                          placeholder="https://example.com/cover.jpg"
                          className="bg-zinc-800 border-zinc-700 text-white"
                          data-testid="input-cover-art-url"
                        />
                      </FormControl>
                      <FormDescription className="text-zinc-500">
                        Link to your episode artwork
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Upload Progress */}
                {isUploading && (
                  <div className="space-y-2">
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-white">Uploading...</span>
                      <span className="text-zinc-400">{uploadProgress}%</span>
                    </div>
                    <Progress value={uploadProgress} className="bg-zinc-800" />
                  </div>
                )}

                {/* Submit Button */}
                <div className="flex gap-4 pt-4">
                  <Button
                    type="submit"
                    disabled={isUploading || !audioFile}
                    className="flex-1 bg-navy-dark hover:bg-red-700 disabled:opacity-50"
                    data-testid="button-submit"
                  >
                    {isUploading ? (
                      <>Uploading... {uploadProgress}%</>
                    ) : (
                      <>
                        <Upload className="w-4 h-4 mr-2" />
                        Submit Episode
                      </>
                    )}
                  </Button>
                </div>
              </form>
            </Form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/pages/EditorDashboard.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  Music, 
  Disc,
  Image,
  LogOut,
  CheckCircle2,
  Clock,
  ArrowRight,
  ListMusic
} from "lucide-react";

interface EditorStats {
  pendingEpisodes: number;
  pendingMixes: number;
  pendingAlbums: number;
  pendingPlaylists: number;
  recentActivity: Array<{
    type: 'episode' | 'mix' | 'album';
    title: string;
    submitter: string;
    submittedAt: string;
  }>;
}

interface EditorDashboardProps {
  onLogout: () => void;
  currentUser?: string;
}

export default function EditorDashboard({ onLogout, currentUser }: EditorDashboardProps) {
  const { data: stats, isLoading } = useQuery<EditorStats>({
    queryKey: ['/api/editor/stats'],
    refetchInterval: 30000, // Refresh every 30 seconds
  });

  const taskCards = [
    {
      title: "Episode Queue",
      description: "Review submitted episodes from residents",
      icon: Music,
      href: "/admin/episode-queue",
      count: stats?.pendingEpisodes || 0,
      color: "text-blue-500",
      bgColor: "bg-blue-50",
      dataTestId: "card-episodes"
    },
    {
      title: "Mix Submissions",
      description: "Approve community-submitted mixes",
      icon: Music,
      href: "/admin/mix-submissions",
      count: stats?.pendingMixes || 0,
      color: "text-purple-500",
      bgColor: "bg-purple-50",
      dataTestId: "card-mixes"
    },
    {
      title: "Team Album Picks",
      description: "Submit picks, vote on teammates' albums, build monthly draft",
      icon: Disc,
      href: "/admin/albums",
      count: stats?.pendingAlbums || 0,
      color: "text-green-500",
      bgColor: "bg-green-50",
      dataTestId: "card-albums"
    },
    {
      title: "Hero Banners",
      description: "Upload and manage seasonal homepage banners",
      icon: Image,
      href: "/admin/hero-banners",
      count: 0, // No pending count needed for banners
      color: "text-orange-500",
      bgColor: "bg-orange-50",
      dataTestId: "card-hero-banners"
    },
    {
      title: "Playlist Submissions",
      description: "Review community-curated playlists",
      icon: ListMusic,
      href: "/admin/playlist-submissions",
      count: stats?.pendingPlaylists || 0,
      color: "text-purple-500",
      bgColor: "bg-purple-50",
      dataTestId: "card-playlists"
    }
  ];

  return (
    <div className="min-h-screen bg-[#FEFCF9]">
      {/* Editor Navigation */}
      <nav className="bg-white border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <h1 className="text-xl font-bold font-mono text-navy" data-testid="heading-editor">EDITOR PANEL</h1>
              {currentUser && (
                <Badge variant="outline" className="font-mono" data-testid="badge-user">
                  {currentUser}
                </Badge>
              )}
            </div>

            <Button
              variant="ghost"
              onClick={onLogout}
              className="font-mono text-sm"
              data-testid="button-logout"
            >
              <LogOut className="h-4 w-4 mr-2" />
              Logout
            </Button>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Welcome Section */}
        <div className="mb-8">
          <h2 className="text-3xl font-bold font-mono mb-2">Welcome back{currentUser ? `, ${currentUser}` : ''}!</h2>
          <p className="text-gray-600 font-mono">Here's what needs your attention</p>
        </div>

        {/* Task Queue Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          {taskCards.map((task) => {
            const Icon = task.icon;
            const hasPending = task.count > 0;

            return (
              <Card key={task.href} className="hover:shadow-lg transition-shadow" data-testid={task.dataTestId}>
                <CardHeader>
                  <div className="flex items-start justify-between">
                    <div className={`p-3 rounded-lg ${task.bgColor}`}>
                      <Icon className={`h-6 w-6 ${task.color}`} />
                    </div>
                    {hasPending && (
                      <Badge variant="destructive" className="font-mono" data-testid={`badge-count-${task.dataTestId}`}>
                        {task.count}
                      </Badge>
                    )}
                  </div>
                  <CardTitle className="font-mono text-lg mt-4">{task.title}</CardTitle>
                  <CardDescription className="font-mono text-sm">
                    {task.description}
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <Link href={task.href}>
                    <Button 
                      variant={hasPending ? "default" : "outline"} 
                      className="w-full font-mono"
                      data-testid={`button-view-${task.dataTestId}`}
                    >
                      {hasPending ? (
                        <>
                          <Clock className="h-4 w-4 mr-2" />
                          Review Now
                        </>
                      ) : (
                        <>
                          <CheckCircle2 className="h-4 w-4 mr-2" />
                          All Clear
                        </>
                      )}
                      <ArrowRight className="h-4 w-4 ml-auto" />
                    </Button>
                  </Link>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Recent Activity */}
        <Card>
          <CardHeader>
            <CardTitle className="font-mono">Recent Submissions</CardTitle>
            <CardDescription className="font-mono">
              Latest content awaiting review across all categories
            </CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <p className="text-gray-500 font-mono text-sm" data-testid="text-loading">Loading activity...</p>
            ) : stats?.recentActivity && stats.recentActivity.length > 0 ? (
              <div className="space-y-3">
                {stats.recentActivity.slice(0, 5).map((item, index) => (
                  <div 
                    key={index} 
                    className="flex items-center justify-between py-2 border-b last:border-0"
                    data-testid={`activity-item-${index}`}
                  >
                    <div className="flex items-center space-x-3">
                      <Badge variant="outline" className="font-mono capitalize">
                        {item.type}
                      </Badge>
                      <div>
                        <p className="font-mono text-sm font-medium" data-testid={`text-title-${index}`}>
                          {item.title}
                        </p>
                        <p className="font-mono text-xs text-gray-500" data-testid={`text-submitter-${index}`}>
                          by {item.submitter}
                        </p>
                      </div>
                    </div>
                    <p className="font-mono text-xs text-gray-400">
                      {new Date(item.submittedAt).toLocaleDateString()}
                    </p>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-gray-500 font-mono text-sm" data-testid="text-no-activity">
                No recent submissions
              </p>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/pages/ScheduleManagement.tsx.content:
import { useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/hooks/use-toast';
import { Calendar, CheckCircle, Clock, CalendarCheck, FileAudio, Save, X } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import type { EpisodeSubmission } from '@shared/schema';

interface ScheduleDialogProps {
  episode: EpisodeSubmission;
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

function ScheduleDialog({ episode, isOpen, onClose, onSuccess }: ScheduleDialogProps) {
  const { toast } = useToast();
  const [airDate, setAirDate] = useState('');
  const [airTime, setAirTime] = useState('');

  const scheduleMutation = useMutation({
    mutationFn: async () => {
      const scheduledDateTime = `${airDate}T${airTime}`;
      return await apiRequest('POST', `/api/admin/episode-submissions/${episode.id}/schedule-azuracast`, {
        scheduledAirDate: new Date(scheduledDateTime).toISOString(),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/episode-submissions'] });
      toast({
        title: 'Episode Scheduled with AzuraCast',
        description: `"${episode.title}" uploaded and scheduled to air on ${new Date(`${airDate}T${airTime}`).toLocaleString()}.`,
      });
      onSuccess();
      onClose();
    },
    onError: (error: any) => {
      toast({
        title: 'AzuraCast Integration Error',
        description: error?.message || 'Failed to upload/schedule episode with AzuraCast.',
        variant: 'destructive',
      });
    },
  });

  const handleSchedule = () => {
    if (!airDate || !airTime) {
      toast({
        title: 'Missing Information',
        description: 'Please select both date and time.',
        variant: 'destructive',
      });
      return;
    }

    // Validate that scheduled time is in the future
    const scheduledDateTime = new Date(`${airDate}T${airTime}`);
    const now = new Date();

    if (scheduledDateTime <= now) {
      toast({
        title: 'Invalid Air Date',
        description: 'Air date must be in the future. Please select a later date/time.',
        variant: 'destructive',
      });
      return;
    }

    scheduleMutation.mutate();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" data-testid="dialog-schedule-episode">
      <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold font-mono">Schedule Episode</h2>
          <Button variant="ghost" size="sm" onClick={onClose} data-testid="button-close-dialog">
            <X className="w-4 h-4" />
          </Button>
        </div>

        <div className="space-y-4">
          <div>
            <p className="text-sm text-gray-600 mb-2">
              <strong>{episode.title}</strong>
            </p>
            <p className="text-xs text-gray-500">
              by {episode.residentName}
              {episode.seriesTitle && ` • ${episode.seriesTitle}`}
            </p>
          </div>

          <div className="space-y-3">
            <div>
              <Label htmlFor="air-date">Air Date</Label>
              <Input
                id="air-date"
                type="date"
                value={airDate}
                onChange={(e) => setAirDate(e.target.value)}
                min={new Date().toISOString().split('T')[0]}
                data-testid="input-air-date"
              />
            </div>

            <div>
              <Label htmlFor="air-time">Air Time</Label>
              <Input
                id="air-time"
                type="time"
                value={airTime}
                onChange={(e) => setAirTime(e.target.value)}
                data-testid="input-air-time"
              />
            </div>
          </div>

          <div className="flex gap-2 pt-4">
            <Button
              className="flex-1"
              onClick={handleSchedule}
              disabled={scheduleMutation.isPending}
              data-testid="button-confirm-schedule"
            >
              <CalendarCheck className="w-4 h-4 mr-2" />
              {scheduleMutation.isPending ? 'Scheduling...' : 'Schedule Episode'}
            </Button>
            <Button variant="outline" onClick={onClose} data-testid="button-cancel-schedule">
              Cancel
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function ScheduleManagement() {
  const { toast } = useToast();
  const [selectedEpisode, setSelectedEpisode] = useState<EpisodeSubmission | null>(null);
  const [activeTab, setActiveTab] = useState<'approved' | 'scheduled'>('approved');

  const { data: approvedEpisodes = [], isLoading: approvedLoading } = useQuery<EpisodeSubmission[]>({
    queryKey: ['/api/admin/episode-submissions', { status: 'approved' }],
    queryFn: async () => {
      const response = await fetch('/api/admin/episode-submissions?status=approved');
      if (!response.ok) throw new Error('Failed to fetch approved episodes');
      return response.json();
    },
  });

  const { data: scheduledEpisodes = [], isLoading: scheduledLoading } = useQuery<EpisodeSubmission[]>({
    queryKey: ['/api/admin/episode-submissions', { status: 'scheduled' }],
    queryFn: async () => {
      const response = await fetch('/api/admin/episode-submissions?status=scheduled');
      if (!response.ok) throw new Error('Failed to fetch scheduled episodes');
      return response.json();
    },
  });

  const unscheduleMutation = useMutation({
    mutationFn: async (episodeId: number) => {
      return await apiRequest('PATCH', `/api/admin/episode-submissions/${episodeId}`, {
        status: 'approved',
        scheduledAirDate: null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/episode-submissions'] });
      toast({
        title: 'Episode Unscheduled',
        description: 'Episode moved back to approved queue.',
      });
    },
  });

  const handleScheduleClick = (episode: EpisodeSubmission) => {
    setSelectedEpisode(episode);
  };

  const handleUnschedule = (episode: EpisodeSubmission) => {
    if (confirm(`Remove "${episode.title}" from the schedule?`)) {
      unscheduleMutation.mutate(episode.id);
    }
  };

  return (
    <div className="min-h-screen bg-[#FEFCF9] py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mb-8">
          <h1 className="text-3xl font-bold font-mono mb-2 flex items-center gap-2">
            <Calendar className="w-8 h-8 text-navy" />
            Schedule Management
          </h1>
          <p className="text-gray-600">
            Manage episode air dates and programming schedule
          </p>
        </div>

        {/* Tab Navigation */}
        <div className="flex gap-2 mb-6">
          <Button
            variant={activeTab === 'approved' ? 'default' : 'outline'}
            onClick={() => setActiveTab('approved')}
            data-testid="tab-approved"
          >
            <CheckCircle className="w-4 h-4 mr-2" />
            Approved ({approvedEpisodes.length})
          </Button>
          <Button
            variant={activeTab === 'scheduled' ? 'default' : 'outline'}
            onClick={() => setActiveTab('scheduled')}
            data-testid="tab-scheduled"
          >
            <CalendarCheck className="w-4 h-4 mr-2" />
            Scheduled ({scheduledEpisodes.length})
          </Button>
        </div>

        {/* Approved Episodes */}
        {activeTab === 'approved' && (
          <Card data-testid="card-approved-episodes">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <CheckCircle className="w-5 h-5" />
                Approved Episodes Ready to Schedule
              </CardTitle>
              <CardDescription>
                These episodes have been approved and are waiting for air date assignment
              </CardDescription>
            </CardHeader>
            <CardContent>
              {approvedLoading ? (
                <div className="text-center py-8">
                  <div className="w-6 h-6 border-2 border-navy border-t-transparent rounded-full animate-spin mx-auto"></div>
                </div>
              ) : approvedEpisodes.length > 0 ? (
                <div className="space-y-3">
                  {approvedEpisodes.map((episode) => (
                    <div
                      key={episode.id}
                      className="flex items-start justify-between p-4 border rounded-lg hover:bg-gray-50"
                      data-testid={`approved-episode-${episode.id}`}
                    >
                      <div className="flex-1">
                        <h4 className="font-medium">{episode.title}</h4>
                        {episode.seriesTitle && (
                          <p className="text-xs text-gray-500">
                            {episode.seriesTitle}
                            {episode.episodeNumber && ` #${episode.episodeNumber}`}
                          </p>
                        )}
                        <p className="text-sm text-gray-600 mt-1">
                          by {episode.residentName}
                        </p>
                        <p className="text-xs text-gray-500 mt-1">
                          Approved {episode.reviewedAt && new Date(episode.reviewedAt).toLocaleDateString()}
                        </p>
                      </div>
                      <div className="ml-4 flex flex-col gap-2">
                        <Badge variant="default" className="flex items-center gap-1">
                          <CheckCircle className="w-3 h-3" />
                          Approved
                        </Badge>
                        <Button
                          size="sm"
                          onClick={() => handleScheduleClick(episode)}
                          data-testid={`button-schedule-${episode.id}`}
                        >
                          <Calendar className="w-4 h-4 mr-2" />
                          Schedule
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <FileAudio className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                  <p className="text-gray-500">No approved episodes waiting to be scheduled</p>
                </div>
              )}
            </CardContent>
          </Card>
        )}

        {/* Scheduled Episodes */}
        {activeTab === 'scheduled' && (
          <Card data-testid="card-scheduled-episodes">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <CalendarCheck className="w-5 h-5" />
                Scheduled Episodes
              </CardTitle>
              <CardDescription>
                Episodes with assigned air dates
              </CardDescription>
            </CardHeader>
            <CardContent>
              {scheduledLoading ? (
                <div className="text-center py-8">
                  <div className="w-6 h-6 border-2 border-navy border-t-transparent rounded-full animate-spin mx-auto"></div>
                </div>
              ) : scheduledEpisodes.length > 0 ? (
                <div className="space-y-3">
                  {scheduledEpisodes
                    .sort((a, b) => {
                      const dateA = a.scheduledAirDate ? new Date(a.scheduledAirDate).getTime() : 0;
                      const dateB = b.scheduledAirDate ? new Date(b.scheduledAirDate).getTime() : 0;
                      return dateA - dateB;
                    })
                    .map((episode) => (
                      <div
                        key={episode.id}
                        className="flex items-start justify-between p-4 border rounded-lg hover:bg-gray-50"
                        data-testid={`scheduled-episode-${episode.id}`}
                      >
                        <div className="flex-1">
                          <h4 className="font-medium">{episode.title}</h4>
                          {episode.seriesTitle && (
                            <p className="text-xs text-gray-500">
                              {episode.seriesTitle}
                              {episode.episodeNumber && ` #${episode.episodeNumber}`}
                            </p>
                          )}
                          <p className="text-sm text-gray-600 mt-1">
                            by {episode.residentName}
                          </p>
                          {episode.scheduledAirDate && (
                            <p className="text-sm text-green-600 font-medium mt-2 flex items-center gap-1">
                              <Clock className="w-4 h-4" />
                              Airs: {new Date(episode.scheduledAirDate).toLocaleString('en-US', {
                                weekday: 'short',
                                year: 'numeric',
                                month: 'long',
                                day: 'numeric',
                                hour: 'numeric',
                                minute: '2-digit',
                              })}
                            </p>
                          )}
                        </div>
                        <div className="ml-4 flex flex-col gap-2">
                          <Badge variant="default" className="flex items-center gap-1">
                            <CalendarCheck className="w-3 h-3" />
                            Scheduled
                          </Badge>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleUnschedule(episode)}
                            disabled={unscheduleMutation.isPending}
                            data-testid={`button-unschedule-${episode.id}`}
                          >
                            <X className="w-4 h-4 mr-2" />
                            Unschedule
                          </Button>
                        </div>
                      </div>
                    ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <Calendar className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                  <p className="text-gray-500">No episodes scheduled yet</p>
                </div>
              )}
            </CardContent>
          </Card>
        )}

        {/* Schedule Dialog */}
        {selectedEpisode && (
          <ScheduleDialog
            episode={selectedEpisode}
            isOpen={!!selectedEpisode}
            onClose={() => setSelectedEpisode(null)}
            onSuccess={() => setSelectedEpisode(null)}
          />
        )}
      </div>
    </div>
  );
}

