  --chart-1: var(--accent-navy);
  --chart-2: hsl(215, 19%, 35%);
  --chart-3: hsl(215, 20%, 65%);
  --chart-4: hsl(213, 27%, 84%);
  --chart-5: hsl(210, 40%, 96.1%);

  /* --- SIDEBAR --- */
  --sidebar-background: hsl(42, 100%, 98%);
  --sidebar-foreground: hsl(222, 47%, 11%);
  --sidebar-primary: var(--accent-navy);
  --sidebar-primary-foreground: hsl(0, 0%, 100%);
  --sidebar-accent: hsl(210, 40%, 96.1%);
  --sidebar-accent-foreground: hsl(222, 47%, 11%);
  --sidebar-border: hsl(214, 32%, 91%);
