.dark {
  /* --- SEMANTIC TOKENS (DARK MODE) --- */
  --background: hsl(222, 47%, 11%);
  --foreground: hsl(210, 40%, 98%);

  --card: hsl(217, 33%, 17%);
  --card-foreground: hsl(210, 40%, 98%);

  --popover: hsl(217, 33%, 17%);
  --popover-foreground: hsl(210, 40%, 98%);

  --muted: hsl(217, 33%, 17%);
  --muted-foreground: hsl(215, 20%, 65%);

  /* Primary uses accent navy */
  --primary: var(--accent-navy);
  --primary-foreground: hsl(0, 0%, 100%);

  /* Secondary: Muted background */
  --secondary: hsl(217, 33%, 17%);
  --secondary-foreground: hsl(210, 40%, 98%);

  /* Accent: Muted variant */
  --accent: hsl(217, 33%, 17%);
  --accent-foreground: hsl(210, 40%, 98%);

  /* Destructive uses red (keep red for destructive actions) */
  --destructive: hsl(0, 84%, 60%);
  --destructive-foreground: hsl(0, 0%, 100%);

  /* Input & Border */
  --border: hsl(215, 25%, 27%);
  --input: hsl(215, 25%, 27%);

  /* --- BUTTON TOKENS (DARK) --- */
  --button-primary-bg: var(--accent-navy);
  --button-primary-hover: var(--accent-navy-light);
  --button-primary-text: hsl(0, 0%, 100%);

  --button-secondary-bg: transparent;
  --button-secondary-hover: hsl(217, 33%, 17%);
  --button-secondary-text: var(--accent-navy);

  /* --- FOCUS (DARK) --- */
  --ring-offset: hsl(222, 47%, 11%);

  /* --- CHARTS (DARK) --- */
  --chart-1: var(--accent-navy);
