      h1: {
        fontSize: '40px',
        lineHeight: '1.1',
        fontWeight: '700',
      },
      h2: {
        fontSize: '28px',
        lineHeight: '1.2',
        fontWeight: '700',
      },
      h3: {
        fontSize: '20px',
        lineHeight: '1.25',
        fontWeight: '600',
      },
    },
    body: {
      base: {
        fontSize: '16px',
        lineHeight: '1.5',
      },
      sm: {
        fontSize: '14px',
        lineHeight: '1.4',
      },
      xs: {
