import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Search, Star } from 'lucide-react';
import Navigation from '@/components/Navigation';
import ContentCard from '@/components/ContentCard';
import { ContentItem } from '@shared/schema';

type ContentType = 'all' | 'mix' | 'episode' | 'playlist';

const filterOptions: { value: ContentType; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'mix', label: 'Mixes' },
  { value: 'episode', label: 'Episodes' },
  { value: 'playlist', label: 'Playlists' },
];

export default function CommunityPage() {
  const [activeFilter, setActiveFilter] = useState<ContentType>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Fetch community content with filters
  const { data: allContent = [], isLoading } = useQuery<ContentItem[]>({
    queryKey: ['/api/community', activeFilter, searchQuery],
    queryFn: async () => {
      const params = new URLSearchParams({
        type: activeFilter,
        limit: '48',
        sort: 'recent',
      });

      if (searchQuery.trim()) {
        params.append('search', searchQuery.trim());
      }

      const response = await fetch(`/api/community?${params}`);
      if (!response.ok) throw new Error('Failed to fetch community content');
      return response.json();
    },
    refetchOnWindowFocus: false,
  });

  // Separate featured (Staff Picks) from regular content
  const staffPicks = allContent.filter(item => item.isFeatured);
  const freshContent = allContent.filter(item => !item.isFeatured);

  // When searching, show all results together (don't split)
  const isSearching = searchQuery.trim().length > 0;

  return (
    <div className="min-h-screen bg-cream dark:bg-gray-950">
      <Navigation />

      <main className="container mx-auto px-4 py-8 md:py-12">
        {/* Header */}
        <div className="mb-8 md:mb-12">
          <h1 className="text-4xl md:text-5xl font-serif text-gray-900 dark:text-white mb-4">
            Community
          </h1>
          <p className="text-lg text-gray-600 dark:text-gray-400 max-w-2xl">
            Discover mixes, episodes, and editorial content from our community of music lovers and creators.
          </p>
        </div>

        {/* Filter Tabs */}
        <div className="mb-6 flex flex-wrap gap-2">
          {filterOptions.map(({ value, label }) => (
            <button
              key={value}
              onClick={() => setActiveFilter(value)}
              className={`px-4 py-2 font-mono text-sm transition-colors ${
                activeFilter === value
                  ? 'bg-navy text-white dark:bg-navy-light dark:text-gray-900'
                  : 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700'
              }`}
              data-testid={`filter-${value}`}
            >
              {label}
            </button>
          ))}
        </div>

        {/* Search Bar */}
        <div className="mb-8">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Search by title, artist, or description..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-gray-900 dark:text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-navy dark:focus:ring-navy-light"
              data-testid="input-search"
            />
          </div>
        </div>

        {/* Content Sections */}
        {isLoading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {Array.from({ length: 12 }).map((_, i) => (
              <div
                key={i}
                className="aspect-square bg-gray-200 dark:bg-gray-800 animate-pulse rounded-xl"
              />
            ))}
          </div>
        ) : allContent.length === 0 ? (
          <div className="text-center py-16">
            <p className="text-xl text-gray-600 dark:text-gray-400 mb-2">
              No content found
            </p>
            <p className="text-sm text-gray-500 dark:text-gray-500">
              {searchQuery ? 'Try adjusting your search or filters' : 'Check back soon for new content'}
            </p>
          </div>
        ) : isSearching ? (
          // Search results - show all together without sections
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {allContent.map((item) => (
              <ContentCard key={`${item.type}-${item.id}`} content={item} />
            ))}
          </div>
        ) : (
          <div className="space-y-12">
            {/* Staff Picks Section - Only show if there are featured items */}
            {staffPicks.length > 0 && (
              <section>
                <div className="flex items-center gap-3 mb-6">
                  <div className="flex items-center gap-2 bg-navy/10 dark:bg-navy/20 px-4 py-2 rounded-lg">
                    <Star className="w-4 h-4 text-navy dark:text-navy-light fill-current" />
                    <h2 className="text-lg font-bold font-mono text-navy dark:text-navy-light">
                      Staff Picks
                    </h2>
                  </div>
                  <div className="flex-1 h-px bg-gray-200 dark:bg-gray-800" />
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                  {staffPicks.slice(0, 4).map((item) => (
                    <ContentCard 
                      key={`${item.type}-${item.id}`} 
                      content={item} 
                      showFeaturedBadge={true}
                    />
                  ))}
                </div>
              </section>
            )}

            {/* Fresh from Community Section */}
            {freshContent.length > 0 && (
              <section>
                <div className="flex items-center gap-3 mb-6">
                  <h2 className="text-lg font-bold font-mono text-gray-900 dark:text-white">
                    Fresh from the Community
                  </h2>
                  <div className="flex-1 h-px bg-gray-200 dark:bg-gray-800" />
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                  {freshContent.map((item) => (
                    <ContentCard key={`${item.type}-${item.id}`} content={item} />
                  ))}
                </div>
              </section>
            )}
          </div>
        )}

        {/* Results Count */}
        {!isLoading && allContent.length > 0 && (
          <div className="mt-8 text-center">
            <p className="text-sm font-mono text-gray-600 dark:text-gray-400">
              Showing {allContent.length} {allContent.length === 1 ? 'item' : 'items'}
              {staffPicks.length > 0 && !isSearching && ` (${staffPicks.length} staff pick${staffPicks.length !== 1 ? 's' : ''})`}
            </p>
          </div>
        )}
      </main>
    </div>
  );
}

client/src/pages/CommunityDetailPage.tsx.content:
import { useQuery } from '@tanstack/react-query';
import { useRoute } from 'wouter';
import { ArrowLeft, ExternalLink, Calendar, User, Tag, Play, Pause } from 'lucide-react';
import Navigation from '@/components/Navigation';
import { Link } from 'wouter';
import { ContentItem } from '@shared/schema';
import { Button } from '@/components/ui/button';
import { useAudio } from '@/providers/AudioProvider';

export default function CommunityDetailPage() {
  const [, params] = useRoute('/community/:id');
  const itemId = params?.id;

  const { state, actions } = useAudio();
  const currentSrc = state.src;

  // Fetch the specific content item
  const { data: item, isLoading } = useQuery<ContentItem>({
    queryKey: ['/api/community', itemId],
    queryFn: async () => {
      const response = await fetch(`/api/community/${itemId}`);
      if (!response.ok) throw new Error('Failed to fetch content item');
      return response.json();
    },
    enabled: !!itemId,
    refetchOnWindowFocus: false,
  });

  // Fetch enhanced oEmbed data
  const { data: oembed, isLoading: oembedLoading } = useQuery({
    queryKey: ['/api/oembed/enhanced', item?.url],
    queryFn: async () => {
      if (!item?.url) return null;
      const response = await fetch(`/api/oembed/enhanced?url=${encodeURIComponent(item.url)}`);
      if (!response.ok) return null;
      return response.json();
    },
    enabled: !!item?.url,
    refetchOnWindowFocus: false,
  });

  if (isLoading) {
    return (
      <div className="min-h-screen bg-cream dark:bg-gray-950">
        <Navigation />
        <main className="container mx-auto px-4 py-8">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 dark:bg-gray-800 w-48 mb-8" />
            <div className="grid md:grid-cols-2 gap-8">
              <div className="aspect-square bg-gray-200 dark:bg-gray-800" />
              <div className="space-y-4">
                <div className="h-12 bg-gray-200 dark:bg-gray-800" />
                <div className="h-6 bg-gray-200 dark:bg-gray-800 w-2/3" />
                <div className="h-32 bg-gray-200 dark:bg-gray-800" />
              </div>
            </div>
          </div>
        </main>
      </div>
    );
  }

  if (!item) {
    return (
      <div className="min-h-screen bg-cream dark:bg-gray-950">
        <Navigation />
        <main className="container mx-auto px-4 py-8">
          <div className="text-center py-16">
            <h1 className="text-3xl font-serif text-gray-900 dark:text-white mb-4">
              Content Not Found
            </h1>
            <Link href="/community">
              <a className="text-navy dark:text-navy-light hover:underline" data-testid="link-back-community">
                ← Back to Community
              </a>
            </Link>
          </div>
        </main>
      </div>
    );
  }

  // Get type-specific display data
  const getTypeLabel = () => {
    switch (item.type) {
      case 'mix': return 'Mix';
      case 'episode': return 'Episode';
      case 'art': return 'Art';
      case 'playlist': return 'Playlist';
      default: return 'Content';
    }
  };

  const getCreatorName = () => {
    if ('name' in item) return item.name;
    if ('hostName' in item) return item.hostName;
    if ('authorName' in item) return item.authorName;
    if ('artistName' in item) return item.artistName;
    if ('curatorName' in item) return item.curatorName;
    return 'Unknown';
  };

  const getDate = () => {
    if ('submittedAt' in item) return item.submittedAt;
    if ('airDate' in item) return item.airDate;
    if ('publishedAt' in item) return item.publishedAt;
    return null;
  };

  const getTracklist = (): Array<{artist: string; title: string; timestamp?: number}> | null => {
    if ('tracklist' in item && item.tracklist) {
      try {
        // Parse JSON string if it's a string
        if (typeof item.tracklist === 'string') {
          return JSON.parse(item.tracklist);
        }
        // Return directly if already an array
        if (Array.isArray(item.tracklist)) {
          return item.tracklist;
        }
      } catch (error) {
        console.error('Failed to parse tracklist:', error);
      }
    }
    return null;
  };

  return (
    <div className="min-h-screen bg-cream dark:bg-gray-950">
      <Navigation />

      <main className="container mx-auto px-4 py-8 md:py-12">
        {/* Back Button */}
        <Link href="/community">
          <a className="inline-flex items-center gap-2 text-gray-600 dark:text-gray-400 hover:text-navy dark:hover:text-navy-light mb-8 transition-colors" data-testid="link-back">
            <ArrowLeft className="w-4 h-4" />
            Back to Community
          </a>
        </Link>

        {/* Split Pane Layout */}
        <div className="grid md:grid-cols-2 gap-8 lg:gap-12">
          {/* Left Pane: Metadata */}
          <div>
            {/* Type Badge */}
            <div className="mb-4">
              <span className={`inline-block px-3 py-1 text-xs font-mono uppercase tracking-wider ${
                item.type === 'mix' ? 'bg-navy text-white' :
                item.type === 'episode' ? 'bg-blue-600 text-white' :
                item.type === 'playlist' ? 'bg-purple-600 text-white' :
                'bg-gray-600 text-white'
              }`} data-testid={`badge-${item.type}`}>
                {getTypeLabel()}
              </span>
            </div>

            {/* Title */}
            <h1 className="text-4xl md:text-5xl font-serif text-gray-900 dark:text-white mb-4" data-testid="text-title">
              {item.title}
            </h1>

            {/* Creator */}
            <div className="flex items-center gap-2 text-lg text-gray-600 dark:text-gray-400 mb-6">
              <User className="w-5 h-5" />
              <span data-testid="text-creator">{getCreatorName()}</span>
            </div>

            {/* Metadata Grid */}
            <div className="space-y-3 mb-8">
              {getDate() && (
                <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                  <Calendar className="w-4 h-4" />
                  <span data-testid="text-date">
                    {new Date(getDate()!).toLocaleDateString('en-US', {
                      year: 'numeric',
                      month: 'long',
                      day: 'numeric',
                    })}
                  </span>
                </div>
              )}

              {'genre' in item && item.genre && (
                <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                  <Tag className="w-4 h-4" />
                  <span data-testid="text-genre">{item.genre}</span>
                </div>
              )}
            </div>

            {/* Description */}
            {'description' in item && item.description && (
              <div className="mb-8">
                <h2 className="text-xl font-serif text-gray-900 dark:text-white mb-3">
                  About
                </h2>
                <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap" data-testid="text-description">
                  {item.description}
                </p>
              </div>
            )}

            {/* External Link */}
            {item.url && (
              <a
                href={item.url}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 text-navy dark:text-navy-light hover:underline"
                data-testid="link-external"
              >
                <ExternalLink className="w-4 h-4" />
                Open in {oembed?.provider_name || 'original platform'}
              </a>
            )}
          </div>

          {/* Right Pane: Player / Artwork */}
          <div>
            {item.type === 'episode' && item.url && item.url.startsWith('/episodes/') ? (
              /* Episode Audio Player - uses shared audio context for persistent playback */
              (() => {
                const episodeUrl = item.url!; // We know it's defined from the condition above
                const isThisEpisodePlaying = currentSrc === episodeUrl && state.status === 'playing';
                const isThisEpisodeLoaded = currentSrc === episodeUrl;

                const handleEpisodePlay = async () => {
                  if (isThisEpisodePlaying) {
                    actions.pause();
                  } else if (isThisEpisodeLoaded) {
                    actions.toggle();
                  } else {
                    await actions.play(episodeUrl, {
                      title: item.title,
                      artist: getCreatorName(),
                      artwork: item.artworkUrl || undefined,
                      isLive: false,
                    });
                  }
                };

                return (
                  <div className="bg-white dark:bg-gray-900 rounded-lg shadow-lg overflow-hidden">
                    {item.artworkUrl ? (
                      <img
                        src={item.artworkUrl}
                        alt={item.title}
                        className="w-full aspect-square object-cover"
                        data-testid="img-artwork"
                      />
                    ) : (
                      <div className="aspect-square bg-gradient-to-br from-navy to-navy-light flex items-center justify-center">
                        <span className="text-white/20 text-6xl font-serif">
                          {item.title.charAt(0)}
                        </span>
                      </div>
                    )}
                    <div className="p-4">
                      <div className="flex items-center gap-4">
                        <Button
                          onClick={handleEpisodePlay}
                          size="lg"
                          className="w-14 h-14 rounded-full bg-navy hover:bg-navy-dark text-white"
                          data-testid="button-play-episode"
                        >
                          {isThisEpisodePlaying ? <Pause className="w-6 h-6" /> : <Play className="w-6 h-6 ml-1" />}
                        </Button>
                        <div className="flex-1">
                          <div className="text-sm font-mono text-gray-600 dark:text-gray-400">
                            {isThisEpisodePlaying ? 'Now Playing' : isThisEpisodeLoaded ? 'Paused' : 'Press play to listen'}
                          </div>
                          <div className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                            {'duration' in item && item.duration ? item.duration : 'Episode'}
                          </div>
                        </div>
                      </div>
                      {isThisEpisodeLoaded && (
                        <div className="mt-3 text-xs text-navy dark:text-navy-light">
                          ✓ Playing in sticky player - browse the site while listening
                        </div>
                      )}
                    </div>
                  </div>
                );
              })()
            ) : oembedLoading ? (
              <div className="aspect-square bg-gray-200 dark:bg-gray-800 animate-pulse" />
            ) : oembed?.html ? (
              <div 
                className="rounded-lg overflow-hidden shadow-lg"
                dangerouslySetInnerHTML={{ __html: oembed.html }}
                data-testid="oembed-player"
              />
            ) : item.artworkUrl ? (
              <img
                src={item.artworkUrl}
                alt={item.title}
                className="w-full aspect-square object-cover rounded-lg shadow-lg"
                data-testid="img-artwork"
              />
            ) : (
              <div className="aspect-square bg-gradient-to-br from-navy to-navy-light flex items-center justify-center rounded-lg shadow-lg">
                <span className="text-white/20 text-6xl font-serif">
                  {item.title.charAt(0)}
                </span>
              </div>
            )}
          </div>
        </div>

        {/* Full-Width Tracklist Section */}
        {getTracklist() && (
          <div className="mt-12 border-t border-gray-200 dark:border-gray-800 pt-12">
            <h2 className="text-2xl font-serif text-gray-900 dark:text-white mb-6">
              Tracklist
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {getTracklist()!.map((track, index) => (
                <div
                  key={index}
                  className="bg-white dark:bg-gray-900/50 border border-gray-200 dark:border-gray-700 hover:border-navy dark:hover:border-sky-500 p-3 rounded-lg transition-all duration-150 hover:-translate-y-0.5 hover:shadow-md hover:shadow-navy/10 dark:hover:shadow-sky-500/20 group cursor-default"
                  data-testid={`track-${index}`}
                >
                  <div className="flex items-start gap-3">
                    <div className="text-navy dark:text-sky-400 font-mono font-bold text-sm pt-0.5 min-w-[2rem]">
                      #{String(index + 1).padStart(2, '0')}
                    </div>
                    <div className="flex-1">
                      <div className="text-sm font-bold text-gray-900 dark:text-white font-mono group-hover:text-navy dark:group-hover:text-sky-400 transition-colors">
                        {track.artist}
                      </div>
                      <div className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">
                        {track.title}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

client/src/pages/HeroBannersAdmin.tsx.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Image, Upload, Trash2, CheckCircle2, ArrowLeft } from "lucide-react";
import { Link } from "wouter";
import type { HeroBanner } from "@shared/schema";

export default function HeroBannersAdmin() {
  const { toast } = useToast();
  const [title, setTitle] = useState("");
  const [subtitle, setSubtitle] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [overlayText, setOverlayText] = useState("");
  const [displayOrder, setDisplayOrder] = useState(0);

  const { data: banners = [], isLoading } = useQuery<HeroBanner[]>({
    queryKey: ['/api/editor/hero-banners'],
  });

  const createMutation = useMutation({
    mutationFn: async (bannerData: {
      title: string;
      subtitle: string | null;
      imageUrl: string;
      overlayText: string | null;
      isActive: boolean;
      displayOrder: number;
    }) => {
      return apiRequest('POST', '/api/editor/hero-banners', bannerData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/editor/hero-banners'] });
      queryClient.invalidateQueries({ queryKey: ['/api/hero-banners/active'] });
      toast({ title: "Hero banner created successfully" });
      // Reset form
      setTitle("");
      setSubtitle("");
      setImageUrl("");
      setOverlayText("");
      setDisplayOrder(0);
    },
    onError: () => {
      toast({ title: "Failed to create hero banner", variant: "destructive" });
    },
  });

  const activateMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiRequest('POST', `/api/editor/hero-banners/${id}/activate`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/editor/hero-banners'] });
      queryClient.invalidateQueries({ queryKey: ['/api/hero-banners/active'] });
      toast({ title: "Banner activated successfully" });
    },
    onError: () => {
      toast({ title: "Failed to activate banner", variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiRequest('DELETE', `/api/editor/hero-banners/${id}`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/editor/hero-banners'] });
      queryClient.invalidateQueries({ queryKey: ['/api/hero-banners/active'] });
      toast({ title: "Banner deleted successfully" });
    },
    onError: () => {
      toast({ title: "Failed to delete banner", variant: "destructive" });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!title || !imageUrl) {
      toast({ title: "Title and image URL are required", variant: "destructive" });
      return;
    }

    createMutation.mutate({
      title,
      subtitle: subtitle || null,
      imageUrl,
      overlayText: overlayText || null,
      isActive: banners.length === 0, // First banner is auto-activated
      displayOrder,
    });
  };

  return (
    <div className="min-h-screen bg-[#FEFCF9]">
      {/* Header */}
      <nav className="bg-white border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center h-16">
            <Link href="/admin/editor">
              <Button variant="ghost" size="sm" className="mr-4" data-testid="button-back">
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back to Dashboard
              </Button>
            </Link>
            <h1 className="text-xl font-bold font-mono text-navy" data-testid="heading-hero-banners">
              HERO BANNERS
            </h1>
          </div>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Upload Form */}
          <Card data-testid="card-upload">
            <CardHeader>
              <div className="flex items-center gap-2">
                <Upload className="h-5 w-5 text-orange-500" />
                <CardTitle className="font-mono">Upload New Banner</CardTitle>
              </div>
              <CardDescription className="font-mono">
                Create a seasonal hero banner for the homepage
              </CardDescription>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <Label htmlFor="title" className="font-mono">Title *</Label>
                  <Input
                    id="title"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    placeholder="Summer Vibes 2025"
                    className="font-mono"
                    data-testid="input-title"
                    required
                  />
                </div>

                <div>
                  <Label htmlFor="subtitle" className="font-mono">Subtitle</Label>
                  <Input
                    id="subtitle"
                    value={subtitle}
                    onChange={(e) => setSubtitle(e.target.value)}
                    placeholder="Hot tracks for the season"
                    className="font-mono"
                    data-testid="input-subtitle"
                  />
                </div>

                <div>
                  <Label htmlFor="imageUrl" className="font-mono">Image URL *</Label>
                  <Input
                    id="imageUrl"
                    value={imageUrl}
                    onChange={(e) => setImageUrl(e.target.value)}
                    placeholder="https://example.com/banner.jpg"
                    className="font-mono"
                    data-testid="input-image-url"
                    required
                  />
                  <p className="text-xs text-gray-500 mt-1 font-mono">
                    Recommended: 1920x600px, hosted externally
                  </p>
                </div>

                <div>
                  <Label htmlFor="overlayText" className="font-mono">Live Metadata Overlay Text</Label>
                  <Textarea
                    id="overlayText"
                    value={overlayText}
                    onChange={(e) => setOverlayText(e.target.value)}
                    placeholder="NOW PLAYING: {artist} - {title}"
                    className="font-mono"
                    data-testid="input-overlay-text"
                    rows={3}
                  />
                  <p className="text-xs text-gray-500 mt-1 font-mono">
                    Use placeholders: {"{artist}"}, {"{title}"}, {"{show}"}
                  </p>
                </div>

                <div>
                  <Label htmlFor="displayOrder" className="font-mono">Display Order</Label>
                  <Input
                    id="displayOrder"
                    type="number"
                    value={displayOrder}
                    onChange={(e) => setDisplayOrder(parseInt(e.target.value) || 0)}
                    className="font-mono"
                    data-testid="input-display-order"
                  />
                  <p className="text-xs text-gray-500 mt-1 font-mono">
                    Higher numbers appear first
                  </p>
                </div>

                {imageUrl && (
                  <div className="rounded-lg overflow-hidden border border-gray-200">
                    <img
                      src={imageUrl}
                      alt="Preview"
                      className="w-full h-48 object-cover"
                      onError={(e) => {
                        e.currentTarget.src = "https://placehold.co/1920x600/003F87/FEFCF9?text=Image+Not+Found";
                      }}
                    />
                  </div>
                )}

                <Button
                  type="submit"
                  className="w-full font-mono"
                  disabled={createMutation.isPending}
                  data-testid="button-create-banner"
                >
                  {createMutation.isPending ? "Creating..." : "Create Banner"}
                </Button>
              </form>
            </CardContent>
          </Card>

          {/* Banner List */}
          <Card data-testid="card-banner-list">
            <CardHeader>
              <div className="flex items-center gap-2">
                <Image className="h-5 w-5 text-orange-500" />
                <CardTitle className="font-mono">Existing Banners</CardTitle>
              </div>
              <CardDescription className="font-mono">
                {banners.length} banner{banners.length !== 1 ? 's' : ''} total
              </CardDescription>
            </CardHeader>
            <CardContent>
              {isLoading && (
                <p className="text-gray-500 font-mono text-center py-8">Loading banners...</p>
              )}

              {!isLoading && banners.length === 0 && (
                <p className="text-gray-500 font-mono text-center py-8">
                  No banners yet. Create your first one!
                </p>
              )}

              <div className="space-y-4">
                {banners.map((banner) => (
                  <div
                    key={banner.id}
                    className="border border-gray-200 rounded-lg p-4 space-y-3"
                    data-testid={`banner-item-${banner.id}`}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-mono font-semibold">{banner.title}</h3>
                          {banner.isActive && (
                            <Badge variant="default" className="font-mono" data-testid={`badge-active-${banner.id}`}>
                              <CheckCircle2 className="h-3 w-3 mr-1" />
                              Active
                            </Badge>
                          )}
                        </div>
                        {banner.subtitle && (
                          <p className="text-sm text-gray-600 font-mono">{banner.subtitle}</p>
                        )}
                        <p className="text-xs text-gray-400 font-mono mt-1">
                          Order: {banner.displayOrder}
                        </p>
                      </div>
                    </div>

                    <div className="rounded overflow-hidden">
                      <img
                        src={banner.imageUrl}
                        alt={banner.title}
                        className="w-full h-24 object-cover"
                        onError={(e) => {
                          e.currentTarget.src = "https://placehold.co/1920x600/003F87/FEFCF9?text=Image+Error";
                        }}
                      />
                    </div>

                    <div className="flex gap-2">
                      {!banner.isActive && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => activateMutation.mutate(banner.id)}
                          disabled={activateMutation.isPending}
                          className="font-mono flex-1"
                          data-testid={`button-activate-${banner.id}`}
                        >
                          <CheckCircle2 className="h-3 w-3 mr-1" />
                          Activate
                        </Button>
                      )}
                      <Button
                        variant="destructive"
                        size="sm"
                        onClick={() => {
                          if (confirm(`Delete "${banner.title}"?`)) {
                            deleteMutation.mutate(banner.id);
                          }
                        }}
                        disabled={deleteMutation.isPending}
                        className="font-mono"
                        data-testid={`button-delete-${banner.id}`}
                      >
                        <Trash2 className="h-3 w-3 mr-1" />
                        Delete
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

client/src/pages/PlaylistSubmissionsAdmi.content:
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { 
  Check, 
  X, 
  Star,
  Music2,
  ExternalLink,
  Trash2,
  StarOff,
  Clock,
  CheckCircle,
  ListMusic,
} from "lucide-react";
import { SiSpotify, SiApplemusic, SiSoundcloud, SiYoutube } from "react-icons/si";
import { useState } from "react";
import AdminShell from "@/components/admin/AdminShell";
import DataTable, { StatusBadge, DateCell, TruncatedText, type Column, type RowAction } from "@/components/admin/DataTable";

interface PlaylistSubmission {
  id: number;
  curatorName: string;
  curatorEmail: string | null;
  title: string;
  description: string | null;
  playlistUrl: string;
  platform: 'spotify' | 'apple_music' | 'soundcloud' | 'youtube' | 'unknown';
  artworkUrl: string | null;
  tags: string[] | null;
  status: 'pending' | 'approved' | 'rejected' | 'featured';
  likes: number;
  submittedAt: string;
  approvedAt: string | null;
  featuredAt: string | null;
}

interface PlaylistSubmissionsAdminProps {
  currentUser: string;
  onLogout: () => void;
}

function PlatformBadge({ platform }: { platform: string }) {
  switch (platform) {
    case 'spotify':
      return (
        <Badge className="bg-green-600 text-white flex items-center gap-1">
          <SiSpotify className="w-3 h-3" />
          Spotify
        </Badge>
      );
    case 'apple_music':
      return (
        <Badge className="bg-pink-600 text-white flex items-center gap-1">
          <SiApplemusic className="w-3 h-3" />
          Apple Music
        </Badge>
      );
    case 'soundcloud':
      return (
        <Badge className="bg-orange-500 text-white flex items-center gap-1">
          <SiSoundcloud className="w-3 h-3" />
          SoundCloud
        </Badge>
      );
    case 'youtube':
      return (
        <Badge className="bg-red-600 text-white flex items-center gap-1">
          <SiYoutube className="w-3 h-3" />
          YouTube
        </Badge>
      );
    default:
      return <Badge variant="secondary">{platform}</Badge>;
  }
}

export default function PlaylistSubmissionsAdmin({ currentUser, onLogout }: PlaylistSubmissionsAdminProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useState<'all' | 'pending' | 'approved' | 'featured' | 'rejected'>('pending');
  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
  const [playlistToReject, setPlaylistToReject] = useState<number | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  const { data: allPlaylists = [], isLoading } = useQuery<PlaylistSubmission[]>({
    queryKey: ['/api/editor/playlists'],
  });

  const pendingCount = allPlaylists.filter(p => p.status === 'pending').length;
  const approvedCount = allPlaylists.filter(p => p.status === 'approved').length;
  const featuredCount = allPlaylists.filter(p => p.status === 'featured').length;
  const rejectedCount = allPlaylists.filter(p => p.status === 'rejected').length;

  const getFilteredData = () => {
    switch (activeTab) {
      case 'pending': return allPlaylists.filter(p => p.status === 'pending');
      case 'approved': return allPlaylists.filter(p => p.status === 'approved');
      case 'featured': return allPlaylists.filter(p => p.status === 'featured');
      case 'rejected': return allPlaylists.filter(p => p.status === 'rejected');
      default: return allPlaylists;
    }
  };

  const approveMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiRequest('PATCH', `/api/editor/playlists/${id}/approve`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/editor/playlists'] });
      queryClient.invalidateQueries({ queryKey: ['/api/community'] });
      toast({
        title: "Playlist Approved",
        description: "The playlist is now visible to the community.",
      });
    },
    onError: (error) => {
      toast({
        title: "Approval Failed",
        description: error instanceof Error ? error.message : "Failed to approve playlist",
        variant: "destructive",
      });
    },
  });

  const rejectMutation = useMutation({
    mutationFn: async ({ id, reason }: { id: number; reason?: string }) => {
      return apiRequest('PATCH', `/api/editor/playlists/${id}/reject`, { reason });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/editor/playlists'] });
      setRejectDialogOpen(false);
      setPlaylistToReject(null);
      setRejectionReason('');
      toast({
        title: "Playlist Rejected",
        description: "The playlist has been rejected.",
      });
    },
    onError: (error) => {
      toast({
        title: "Rejection Failed",
        description: error instanceof Error ? error.message : "Failed to reject playlist",
        variant: "destructive",
      });
    },
  });

  const handleRejectClick = (id: number) => {
    setPlaylistToReject(id);
    setRejectionReason('');
    setRejectDialogOpen(true);
  };

  const handleRejectConfirm = () => {
    if (playlistToReject !== null) {
      rejectMutation.mutate({ id: playlistToReject, reason: rejectionReason || undefined });
    }
  };

  const toggleFeatureMutation = useMutation({
    mutationFn: async ({ id, featured }: { id: number; featured: boolean }) => {
      return apiRequest('PATCH', `/api/editor/playlists/${id}/feature`, { featured });
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['/api/editor/playlists'] });
      queryClient.invalidateQueries({ queryKey: ['/api/community'] });
      toast({
        title: variables.featured ? "Playlist Featured" : "Playlist Unfeatured",
        description: variables.featured 
          ? "The playlist is now featured on the community page." 
          : "The playlist is no longer featured.",
      });
    },
    onError: (error) => {
      toast({
        title: "Feature Toggle Failed",
        description: error instanceof Error ? error.message : "Failed to update playlist feature status",
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiRequest('DELETE', `/api/editor/playlists/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/editor/playlists'] });
      queryClient.invalidateQueries({ queryKey: ['/api/community'] });
      toast({
        title: "Playlist Deleted",
        description: "The playlist has been permanently deleted.",
      });
    },
    onError: (error) => {
      toast({
        title: "Delete Failed",
        description: error instanceof Error ? error.message : "Failed to delete playlist",
        variant: "destructive",
      });
    },
  });

  const columns: Column<PlaylistSubmission>[] = [
    {
      key: 'title',
      header: 'Playlist',
      sortable: true,
      render: (playlist) => (
        <div className="flex items-center gap-3">
          {playlist.artworkUrl ? (
            <img 
              src={playlist.artworkUrl} 
              alt={playlist.title}
              className="w-10 h-10 rounded object-cover"
            />
          ) : (
            <div className="w-10 h-10 rounded bg-gray-100 flex items-center justify-center">
              <Music2 className="w-5 h-5 text-gray-400" />
            </div>
          )}
          <div>
            <span className="font-medium text-gray-900"><TruncatedText text={playlist.title} maxLength={30} /></span>
            <p className="text-xs text-gray-500">{playlist.curatorName}</p>
          </div>
        </div>
      ),
    },
    {
      key: 'platform',
      header: 'Platform',
      sortable: true,
      render: (playlist) => <PlatformBadge platform={playlist.platform} />,
    },
    {
      key: 'status',
      header: 'Status',
      sortable: true,
      render: (playlist) => <StatusBadge status={playlist.status} />,
    },
    {
      key: 'tags',
      header: 'Tags',
      render: (playlist) => playlist.tags && playlist.tags.length > 0 ? (
        <div className="flex flex-wrap gap-1">
          {playlist.tags.slice(0, 2).map((tag, idx) => (
            <Badge key={idx} variant="outline" className="text-xs">
              {tag}
            </Badge>
          ))}
          {playlist.tags.length > 2 && (
            <Badge variant="outline" className="text-xs">
              +{playlist.tags.length - 2}
            </Badge>
          )}
        </div>
      ) : (
        <span className="text-gray-400">—</span>
      ),
    },
    {
      key: 'submittedAt',
      header: 'Submitted',
      sortable: true,
      render: (playlist) => <DateCell date={playlist.submittedAt} />,
    },
    {
      key: 'playlistUrl',
      header: 'Link',
      render: (playlist) => (
        <a 
          href={playlist.playlistUrl} 
          target="_blank" 
          rel="noopener noreferrer"
          className="text-blue-600 hover:underline flex items-center gap-1"
          data-testid={`link-playlist-${playlist.id}`}
        >
          <ExternalLink className="w-3 h-3" />
          <span className="text-sm">Open</span>
        </a>
      ),
    },
  ];

  const rowActions: RowAction<PlaylistSubmission>[] = [
    {
      label: 'Approve',
      icon: Check,
      onClick: (playlist) => approveMutation.mutate(playlist.id),
      show: (playlist) => playlist.status === 'pending',
    },
    {
      label: 'Feature',
      icon: Star,
      onClick: (playlist) => toggleFeatureMutation.mutate({ id: playlist.id, featured: true }),
      show: (playlist) => playlist.status === 'approved',
    },
    {
      label: 'Unfeature',
      icon: StarOff,
      onClick: (playlist) => toggleFeatureMutation.mutate({ id: playlist.id, featured: false }),
      show: (playlist) => playlist.status === 'featured',
    },
    {
      label: 'Re-approve',
      icon: Check,
      onClick: (playlist) => approveMutation.mutate(playlist.id),
      show: (playlist) => playlist.status === 'rejected',
    },
    {
      label: 'Reject',
      icon: X,
      onClick: (playlist) => handleRejectClick(playlist.id),
      variant: 'destructive',
      show: (playlist) => playlist.status !== 'rejected',
    },
    {
      label: 'Delete',
      icon: Trash2,
      onClick: (playlist) => {
        if (confirm('Are you sure you want to permanently delete this playlist?')) {
          deleteMutation.mutate(playlist.id);
        }
      },
      variant: 'destructive',
    },
  ];

  return (
    <AdminShell
      title="Playlist Submissions"
      subtitle="Review and manage community-submitted playlists"
      breadcrumbs={[{ label: "Playlists" }]}
      currentUser={currentUser}
      userRole="editor"
      onLogout={onLogout}
    >
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-white border border-gray-200 rounded-lg p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center">
            <ListMusic className="w-5 h-5 text-gray-600" />
          </div>
          <div>
            <p className="text-2xl font-bold text-gray-900">{allPlaylists.length}</p>
            <p className="text-sm text-gray-500">Total Playlists</p>
          </div>
        </div>
        <div className="bg-white border border-gray-200 rounded-lg p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-orange-100 rounded-lg flex items-center justify-center">
            <Clock className="w-5 h-5 text-orange-600" />
          </div>
          <div>
            <p className="text-2xl font-bold text-orange-600">{pendingCount}</p>
            <p className="text-sm text-gray-500">Pending Review</p>
          </div>
        </div>
        <div className="bg-white border border-gray-200 rounded-lg p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
            <CheckCircle className="w-5 h-5 text-green-600" />
          </div>
          <div>
            <p className="text-2xl font-bold text-green-600">{approvedCount}</p>
            <p className="text-sm text-gray-500">Approved</p>
          </div>
        </div>
        <div className="bg-white border border-gray-200 rounded-lg p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center">
            <Star className="w-5 h-5 text-purple-600" />
          </div>
          <div>
            <p className="text-2xl font-bold text-purple-600">{featuredCount}</p>
            <p className="text-sm text-gray-500">Featured</p>
          </div>
        </div>
      </div>

      <div className="bg-white border border-gray-200 rounded-lg">
        <div className="p-4 border-b border-gray-200">
          <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
            <TabsList className="bg-gray-100">
              <TabsTrigger value="all" data-testid="tab-all">
                All ({allPlaylists.length})
              </TabsTrigger>
              <TabsTrigger value="pending" data-testid="tab-pending">
                Pending ({pendingCount})
              </TabsTrigger>
              <TabsTrigger value="approved" data-testid="tab-approved">
                Approved ({approvedCount})
              </TabsTrigger>
              <TabsTrigger value="featured" data-testid="tab-featured">
                Featured ({featuredCount})
              </TabsTrigger>
              <TabsTrigger value="rejected" data-testid="tab-rejected">
                Rejected ({rejectedCount})
              </TabsTrigger>
            </TabsList>
          </Tabs>
        </div>

        <DataTable
          data={getFilteredData()}
          columns={columns}
          rowActions={rowActions}
          searchKeys={['title', 'curatorName', 'platform']}
          searchPlaceholder="Search playlists..."
          isLoading={isLoading}
          emptyMessage={activeTab === 'pending' 
            ? "No pending playlists to review"
            : "No playlists match your filters"}
        />
      </div>

      <Dialog open={rejectDialogOpen} onOpenChange={setRejectDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Reject Playlist</DialogTitle>
            <DialogDescription>
              Optionally provide a reason for rejecting this playlist.
            </DialogDescription>
          </DialogHeader>
          <Textarea
            placeholder="e.g., Playlist doesn't match our community guidelines..."
            value={rejectionReason}
            onChange={(e) => setRejectionReason(e.target.value)}
            rows={4}
            data-testid="input-rejection-reason"
          />
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setRejectDialogOpen(false);
                setPlaylistToReject(null);
                setRejectionReason('');
              }}
              data-testid="button-cancel-reject"
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleRejectConfirm}
              disabled={rejectMutation.isPending}
              data-testid="button-confirm-reject"
            >
              {rejectMutation.isPending ? 'Rejecting...' : 'Reject Playlist'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </AdminShell>
  );
}

